/* 平成29年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h29.committeeSessions.push(...[{"id":"h29-20170421-9","meetingId":"h29-cm04","date":"2017年4月21日","dateIso":"2017-04-21","committee":"文教委員会","time":"午後 １時００分～午後 ４時０５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件整理しています。","topics":[{"id":"topic-01","title":"しながわこども冒険ひろばの開設","agenda":"しながわこども冒険ひろばの開設","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"要望もあったものの、２カ所目が１４年後ということで、これまでどういったことがネックだったのか。ぜひやっていただきたいと思いながら伺っておりますが、これはいかがか尋ねました。","respondent":"高山子ども育成課長","answer":"４カ所目ということで、そういった機会が必ずしも計画的に訪れるわけではありませんので、その機会を逃さぬように努めてまいります。","id":"exchange-001"},{"speaker":"あべ委員","kind":"質問","question":"こうしたものを開設していくのに、さまざまな区民の活動、ＮＰＯとかの団体もいろいろな活動をされていたと思います。例えば、そういったさまざまな団体との関係とこの運営、どういうふうな関係になっているのかということもの説明を求めました。","respondent":"高山子ども育成課長","answer":"ご説明のほうが漏れてしまったのですが、そういった意見を組み入れる形で、今回の全体配置という形でやらせていただいております。そして、思いの強い方の思いをできるだけ酌み取れるような形で、運営については心がけてまいりたいと考えております。","id":"exchange-002"},{"speaker":"新妻委員","kind":"質問・要望","question":"万が一事故があった場合の対応はどのようになっているのかというところを、確認をさせてほしいと求めました。今後また品川区全域で検討していただきたいと思うのですけれども、そのような要望もいただいておりますので、以上の点をお願いいたします。","respondent":"高山子ども育成課長","answer":"事故への対応ということなのですが、医療救護などの必要性があれば、そういったところへのつなぎなどもするようにしています。１,４００m2という面積で確保したのですが、引き続き３カ所目の確保については、機会を捉えて要望してまいりたいと考えております。","id":"exchange-003"},{"speaker":"新妻委員","kind":"確認","question":"１点だけ。対応はしていただけると思うのですけれども、具体的に行く病院を指定しているのかとか、そこら辺の確認を１点だけお願いいたします。","respondent":"高山子ども育成課長","answer":"緊急時の対応として、特に指定の医療機関などを設けているものではございません。１１９番などをしますと、あいている病院などを検索した後の対応になりますので、できる限りの速やかな対応ということで。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"資料の中に、事業目的のところに、これは具体的に子どもに何を身につけてほしいということなのでしょうか。例えば、どういうことをすればけがをするとか、危険だとか、そういったことを身につけるということと捉えてよろしいのか尋ねました。","respondent":"高山子ども育成課長","answer":"それは身につくものですので、例えばそういったことで、このような表現を使わせていただいております。多少のけがを伴うかもしれませんが、そういった意味に対しての、このような事業趣旨というふうに受けとめていただければと考えています。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"後でお話を伺ったりしたのですけれども、やはり遊びというのは、遊びを求めていくという文化がすごく大事なのだというのを実感したわけです。１日４人ということなのかどうか、その辺を具体的に教えていただきたいのと、金土は難しいのか尋ねました。","respondent":"高山子ども育成課長","answer":"事業を開始するに当たりましては、まずは週に２日程度の休みを入れた上で、この事業のほうをやらせていただきたいと考えております。時間外は立ち入りができないということではございませんので、どうぞ一つの公園の一部として、有効にご活用いただければと考えております。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここのところの資格を持った方以外の研修がどうなっているのか教えていただきたいのが１つと、あと、遊びの内容的には。児童センターなんかに来て遊ぶ子どものけがの対応とか、そういうところとの違いがあるのかどうか、の説明を求めました。","respondent":"高山子ども育成課長","answer":"そういった意味では、そういった事業については必ず実施するようにというようなことで、仕様書上はうたっているところです。最終的には区の保険などで補填される部分が当然出てくるというふうには考えております。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"指導員でいらっしゃる方の力量というのですか、きちんとやっていただきたいと思うのと、そういった面は事前にできることを十分しておいてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問","question":"ちょっと細かくなってすみません。委託ということなのですけれども、毎年毎年更新されていく形態の委託なのか、それとも複数年で結ばれる契約とするのか尋ねました。","respondent":"高山子ども育成課長","answer":"３点ご質問いただきまして、正直、あまりぱっと見た分にはわからない状態ということです。事業の実績なども踏まえまして、次年度以降の計画については、契約部分もご相談しながら決めてまいりたいというふうに考えております。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"北浜のほうもあわせてこれをお伺いしたいと思います。それが開園時間中といいますか、活動時間中に使えるような状態であるのかということの説明を求めました。","respondent":"高山子ども育成課長","answer":"けがへの対応ということで、５月７日のオープンということもありますので、これについては北浜も同様に備えているというものです。ＡＥＤにつきましては、そういった部分では比較的近い距離で、有事の際に機器の取り扱いができるというふうに考えているところです。","id":"exchange-010"}]},{"id":"topic-02","title":"子ども食堂フォーラムの開催","agenda":"子ども食堂フォーラムの開催","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"確認なのですけれども、開設を今後区内に増やしていくということには、積極的に支援していこうという姿勢であるということでいいのか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"情報が欲しいということで、情報共有する場を提供して、お互いに解決できることは解決していただくというところをまず１つ考えているところです。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問","question":"そのように捉えているようなことも伺ったのですけれども、そこでどこかヒアリングをしてみたいな、何かそういうことがあるのでしょうか。教えてほしいと求めました。","respondent":"廣田子ども家庭支援課長","answer":"６月１７日のキックオフの後にネットワークの中で要望を聞いて、どこまで支援できるのかということを、公平にやりたいというお話をしています。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問","question":"それについては、確かにおっしゃるとおり、どこに対してどう提供していくかというのは、ある程度選んでいく必要があるだろうと。","respondent":"廣田子ども家庭支援課長","answer":"このネットワークを進めていく中で、内部の連携もできているので、ご提供できるかと思います。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なかなかそこが伝わらないみたいなお話をちらっと伺ったので、ずっとかかわらなくてもいいので、そこをご検討いただけないかと一つ思っています。その辺、財源的にどのぐらい援助をしていかれる予定があるのか、その辺をお伺いしたいと思いますが、いかがか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"実際に遊びに来ている子どもたちで、フォーラムに来られないまでも、こういうことがあるということは案内していくつもりです。学習支援であったりとか、そこで検討する予定ですので、そういうところについてはまだお答えしかねます。","id":"exchange-014"},{"speaker":"新妻委員","kind":"質問・要望","question":"１点だけ確認します。世代関係なく、そういう生活困窮の方にもフードバンク機能が対象となっていくのかどうかというところを１点、確認をさせてほしいと求めました。","respondent":"廣田子ども家庭支援課長","answer":"もちろん生活福祉課とも連携はするのですけれども、どういうツールがいいのかということも含めてこの中で検討して、いろいろな人に届くようにというふうに進めていくことを考えております。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問","question":"当日のフォーラムに、協賛なりという立場で出席される予定はないのでしょうか。実際やられている方のお話を伺えるのもそうですし、区はどうなのみたいな話になったときに、その辺はどうなのかということです。","respondent":"廣田子ども家庭支援課長","answer":"フォーラムの当初には、今のところ区長を予定しているのですけれども、区長と副区長も出席しまして、お話をする予定です。近藤さんの実施されている内容は私ども区の求める子ども食堂と近いので、なるべく２部の中で、より具体的に話そうというようなところを考えています。","id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今お話をお伺いして、ぜひどちらかの場面できちんと内容を説明していただいて、これからやる方の参考になるようにしてほしいと求めました。子ども食堂の性格については、また後で子どもの未来プロジェクトのほうで伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-03","title":"子どもの未来応援プロジェクト","agenda":"子どもの未来応援プロジェクト","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"こうした施策と絡めていくということも必要ではないかと思うのですけれども、そこはどのようにお考えでしょうか。どういった層に対して手厚くしていくとか、今後の奨学金のあり方をどのようにお考えか、の説明を求めました。","respondent":"廣田子ども家庭支援課長、高山子ども育成課長","answer":"新規の学習支援事業につきましては、親子ともども支援していくので、低所得の世帯にぐっと絞って平成２９年度は実施するつもりです。他の団体との連携という点で申しますと、例えば、そこをきっかけとする支援というのが少しずつ広がりを持っているというふうに思っております。","id":"exchange-018"},{"speaker":"あべ委員","kind":"質問","question":"こうした高校生段階での支援ですとか、日常的にといいましょうか、やっていくというような仕組みになっているのかどうかというのが１つ。すごく私は大切だと思っているのですけれども、そういったことも視点に入っているかどうかということをお伺いしたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"先ほど組織を説明したように、平成２８年度の組織というふうに説明させていただいたのですが、さらに深めていくというようなことを考えています。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"私も再三求めてきました入学資金の支給時期検討ということで、どういった状況まで進んでいるのか、伺いたいと思います。今、ほかのところで負担があって大変だという家庭もありますので、奨学金の検討状況も現在どうなっているのか伺いたいと思います。","respondent":"有馬学務課長、廣田子ども家庭支援課長","answer":"実際には区の中では、それを受けて、いわゆる準要保護の取り扱いをどうするかということの検討にこれから入っていくというような段階です。これからどういうふうにしていくというような段階です。どういう時期にかかってくるのかというところの把握をした上で検討を進めていくのですけれども、できるだけ平成３０年度生に間に合うように、何らかの見直しをと考えているところです。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"返還免除型がありますけれども、給付型の奨学金をぜひつくってほしいと求めましたが、これは高校生が対象ということですか。それはやはり足りない部分を区が支援していくことも必要ではないかと思うのですけれども、大学生のところの考えを伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"対象については、今の奨学金も高校の入学の奨学金なので、高校生を考えています。支援が平成２９年度から前倒しでやりながら平成３０年度というところで、大学については国にお任せするのがよしと現時点では考えています。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"生活保護世帯の大学進学についても、学習支援のカテゴリのほうで、審査、検討するということですけれども、やはり学習支援も必要だと思います。経済支援のほうも、そういったところへの経済的支援も必要だと思いますけれども、お考えを伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"福祉部のほうで検討するというふうに言われているので、情報が入りましたら、こちらでも厚生委員会で決まったものを報告させていただこうと思っています。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、なかなか貧困と格差が広がっている中で、やはりこういったところ、親の経済力で子どもの未来が左右されないように、しっかりと区のほうでも支援していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どちらかというと、区の対策の姿勢、やはり子どもの貧困ということをきちんと位置づけていただきたいというのが１点です。１９ページのところに、ぜひ受け皿のところをしっかりと考えてほしいと求めましたが、いかがか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"自立を支援していくわけで、自立のために支援が必要なことは行政が手を出し、自分の力で歩いていけるようにという支援をするので。そこに中学３年、使える資源、連携できる資源がないかというところを洗い出して整理をこれからしていくところです。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"つなぎを考えてほしいと求めました。やはり子どもの貧困、しっかりと位置づけをしていただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-04","title":"子ども・子育て会議の報告","agenda":"子ども・子育て会議の報告","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"もう４月に入っているので、どこかできちんとご説明がされればいいと思うのですが、今日いい機会だからお聞きしたいと思ったのが１点です。結論的に、策定をどうやって会議的に結論を出したのか、結論のところを教えてほしいと求めました。","respondent":"吉田保育施設調整担当課長","answer":"それにつきましては、保育士がかわるということに対するのが一番保護者説明会でも多かった質問だったということが、議事録に記載されております。平成２９年度につきましては、平成２７年度から始めて５年間の、各課を通して調整中です。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"きっと３月の終わりあたりから、どうやっていこうかというところで、具体的にご報告をいただきたいと思うのが１点。改めて担当者を決めていくのか、その辺がわからないので、の説明を求めました。","respondent":"吉田保育施設調整担当課長、高山子ども育成課長","answer":"子ども・若者の会議のメンバーについては、かぶる者もありますし、同じになる者もあります。ひろまち保育園の引き継ぎにつきましては、後日お答えさせていただければと思います。１つは子ども・子育て支援事業計画という計画と、もう一つは次世代育成支援対策推進行動計画という２つの計画の要素を持った計画でございました。","id":"exchange-027"}]},{"id":"topic-05","title":"平成２９年度学級編制","agenda":"平成２９年度学級編制","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"ピンクの弾力的運用なのですけれども、品川区の判断でやったものだということでしたけれども、これは何か条例とか、そういったものに基づいてやられているということなのか尋ねました。","respondent":"有馬学務課長","answer":"教育総合支援センターのほうに就学相談の窓口がありまして、それとも固定級に行くのか、相談をする場があります。したがって、こういう場合が必ずこうとかという明確な基準というものはないというふうなことで認識しております。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問","question":"就学相談の中で、特別支援が必要な方がいるということで、人数を少なくして、指導が充実できるようにということで、こうされているということでよろしいのか尋ねました。","respondent":"有馬学務課長","answer":"浅間台小学校の「９」ですとか、第一日野小学校の「１９」というのが、固定級に在籍している数ということで見ていただければと思います。それの配慮ということで１クラス増やして、そのクラスは人数を少し少な目にして、その子に対応をしていこうです。","id":"exchange-029"},{"speaker":"あべ委員","kind":"質問・要望","question":"仕組みの問題で教えていただきたいのですけれども、学級数が計２クラス分増えているわけですけれども、固有教員がいるからできることなのですか。確認です。","respondent":"有馬学務課長","answer":"それは区の判断で認めるということは、東京都のほうからも見解が出ているのですけれども、都から教員の手当てはいたしませんと。ということで、この場合につきましては、区の固有教員を活用してという形で、区の判断による学級編制という形でお示しをしております。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"どういうところに配置をしているのか、どういった考えで配置しているのか、基本的なところを教えてほしいのが１点です。希望したところに入れなかったお子さんの状況が、子どもの人数、学校でどうなっているのかというところの説明を求めました。","respondent":"有馬学務課長、熊谷指導課長","answer":"小山台小学校が１１名、日野学園が５名ということで、合計１１０名、兄弟で入れなかった方が３名です。中学校のほうは、戸越台中学校で６名ということになってあります。固有教員の配置ですが、これまでと変わってございません。１５中学校区に２名ずつということで配置しておりますけれども、ただ、この２校については、そうした配慮も踏まえて配置をしています。","id":"exchange-031"},{"speaker":"高橋（し）委員","kind":"確認","question":"直前にクラスが１つ増えたところがあるとお聞きしているのですけれども、そのあたりをどう対応して、次の年度はまたクラスが３つから２つになってしまうのかということの確認です。","respondent":"有馬学務課長","answer":"源氏前小学校の３年生とかが、ここは２クラスだったところが、逆に３年生になると１クラスになるというような状況というのが出てきております。要するに人数の基準に照らして、１人でも２人でも増減すれば学級数は増減していくということにはなります。","id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"確認","question":"鈴ヶ森中学校が、８年生に上がるときに８０人から８１人になったので、３クラスになったわけですよね。中学校の先生は、１クラス分の先生が増えた訳ですけれども、これがまた９年生になったときに８０人になると２クラスになるのですよねという確認です。","respondent":"熊谷指導課長","answer":"ですので、提示されたカードをもとに、私どものほうで面接をいたしまして、配置というふうになります。クラスが１クラス減ってしまったときには、過員ということで、次年度の異動の教員を過員対象として異動させるということになっているところです。","id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"質問","question":"現場の先生方が随分ご苦労されて、時間割も全部変えたというふうにお聞きしているので、そのあたりも教育委員会のほうでバックアップしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-06","title":"平成２９年度品川区立学校長・副校長、幼稚園長異動者名簿","agenda":"平成２９年度品川区立学校長・副校長、幼稚園長異動者名簿","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"どうも人事上のバランスといいますか、また、打開策ということを考えていらっしゃるのかというのが１点です。３点目、何か仕組み的なこともあわせて考えていらっしゃるのか、の説明を求めました。","respondent":"熊谷指導課長","answer":"それから、２点目なのですけれども、まず、幼稚園なのですが、幼稚園の採用は２３区で実施しております。そういう意味では、２３区で幼稚園を持っているところ同士での連携ということをこれまでも深めてまいりました。","id":"exchange-035"},{"speaker":"高橋（し）委員","kind":"質問","question":"独自採用の先生方のキャリアアップの中でこういう方がおられると、モチベーションも上がりますし、いいことだと思うのです。校長先生になるためのハードルがかなり高いとお聞きしているのですけれども、越えるべきハードルというか、お尋ねします。","respondent":"熊谷指導課長","answer":"平成１８年４月１日付で通知が出ておりまして、その中で、人事交流で県費負担の教職員にしなければならないというのが一筆あるのです。杉並区と連携しながら都に求め、また、国にも求めていくことを行っていきたいというふうに考えております。","id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"質問","question":"仮に人事交流で都費の方になったとすると、人事交流ですから、そこで退職されるわけではなくて、戻ってくると。そうすると、校長先生ではなくなってしまうということなのか尋ねました。","respondent":"熊谷指導課長","answer":"まさに委員ご指摘のとおり、交流ということになりましたので、戻ってきたときにどうするか。そういったことも含めて、副校長が出たところですので、検討を進めてまいりたいと思います。","id":"exchange-037"}]},{"id":"topic-07","title":"品川コミュニティ・スクール","agenda":"品川コミュニティ・スクール","exchanges":[{"speaker":"高橋（し）委員","kind":"確認","question":"ちょっと確認なのですけれども、本当は注釈みたいなのがあればあれなのですけれども、そういう形をしていただけると。どこかに区費教員の説明というのは入っているのか尋ねました。","respondent":"熊谷指導課長","answer":"６ページにも「区費教職員等」というふうにしているのですが、それから区費の教職員、区費講師もおります。学校で説明される際にも、区費教職員とは一体どういう人たちなのかということの説明も加えていただくように、伝えていきたいと思います。","id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"質問","question":"現在１５校があるのですけれども、コーディネーターの方が入ってやられていると思うのですが、もう決まっていないところはないのでしょうか。１６校についてそういった状況のところが今どれぐらいかというのをお尋ねします。","respondent":"熊谷指導課長","answer":"昨年度の指定校につきましては、全校決まっております。平成２９年度の指定校につきましては、９割ぐらい決まっているのですけれども、活用していただくということになると思います。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"いろいろなことを知っていらっしゃるコーディネーターに来ていただいてすごく助かるという話も伺ってはいるのですけれども、あと、保護者のこととか。","respondent":"熊谷指導課長","answer":"焦らず慌てず諦めずということで、本当に一朝一夕にはできないものですので、まずは始めてみるというところからだと思います。学校支援地域本部におろしていくときに、これは地域支援本部にやってもらうこと、さまざまあると思いますので。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"意見","question":"複数名にしたらどうかというアドバイスもありましたし、ものすごく人員が増えてくるという中で、大変であろうと思っています。今は思っている段階なので、またいろいろ現場の声もこれから聞かせていただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"あべ委員","kind":"意見","question":"２０１８のほうではぜひ言葉をもう少しやわらかくしていただいたらいいのではないかと思います。これは本当に当事者、これではなかなかまだ地域の方に読んでいただくのも難しいかと思いますので、ぜひそこは工夫してほしいと求めました。","respondent":"熊谷指導課長","answer":"２０１７としましたのは、まず学校できちんとこれを使いながら説明をしていただくというところと、また工夫していきたいと思います。","id":"exchange-042"}]},{"id":"topic-08","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"創刊号はご説明いただいて、今回３号ということで、２号の報告がなかったと思うのですけれども、何か違いがあるのでしょうか。今、年度当初だということだったのですが、そういうことなのか尋ねました。","respondent":"横山品川図書館長","answer":"創刊が昨年１０月でありまして、年度初めに当たっては初めてでしたので、ご紹介がてらご報告させていただきました。","id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/203794?Template=document&Id=4910#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":56335,"voices":148}},{"id":"h29-20170421-5","meetingId":"h29-cm04","date":"2017年4月21日","dateIso":"2017-04-21","committee":"総務委員会","time":"午後 １時００分～午後 ２時２５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"平成２９年度組織改正","agenda":"平成２９年度組織改正","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"一例を言っていただけるとどんな内容なのかなということがわかるので、その辺を具体的に教えていただきたいなと思います。さまざまな施策をやってきたのではないかなという認識は持っているのですけれども、その辺、もう少し具体的に教えていただきたいなと思います。","respondent":"柏原企画調整課長","answer":"商業・ものづくり課になった際に、今後の産業施策をどういった形で進めるのだということで、区の中でも方向性の検討を行ったところです。もう１つは、これも一定程度立ち上げがうまくいっているところもありますので、そういったこともあるです。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"随分というか、そういうことも含めて、しっかり進めていけるようにつくっていただければと改めて思ったりしております。それよりもさらにもう少し突っ込んだというか、もう少し具体的なというか、体制をもっと広くしてやる必要があるというようなご認識なのか尋ねました。","respondent":"柏原企画調整課長","answer":"今後の施策の中で、より精度を上げた施策展開につなげられるのではないかというところもありまして、こういった形の担当を置くものです。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"そういうご認識を持っておられると思いますけれども、やっぱり今の区民の状況がどうなのか、要求がどこなのかというところも受けとめて施策展開していただきたいということを改めて申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"総務委員会に出席される理事者の方は、派閥みたいなものがあって、異動しないようなシステムになっているのかなと。場所、席は変わっていますけれども、そういうことが何かあるのですかとちょっと不思議に思うのですが、簡単にの説明を求めました。","respondent":"黒田人事課長","answer":"人事異動につきましては、退職等がありまして、その際の組織の必要に応じて人材を配置しているということで、派閥等があるものではございません。","id":"exchange-004"}]},{"id":"topic-02","title":"ケーブルテレビ品川による地域ＢＷＡ事業の開始","agenda":"ケーブルテレビ品川による地域ＢＷＡ事業の開始","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"八潮に限らず、そういうところとどういうふうに仕切って考えていったらいいのかというのがわからないので、教えていただきたいと。ちょっと漠然としてしまっているかもしれないのですけれども。","respondent":"柏原企画調整課長","answer":"アンテナの設置の場所がどの辺からですけれども、アンテナ設置については、設置できるところから進めていきたいという形で聞いてあります。今後、それによっては関連してくる部分もあるのではないかと思いますが、今のところは直接的な関係は考えていないところです。","id":"exchange-005"},{"speaker":"南委員","kind":"意見","question":"何度も区で補助金を出してくれないかみたいなことも含めて、そんなお話をされたことがあったのですが、ＦＭ放送と言っていましたね。すみません、間違えましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"今回、自治体で免許を了解するということで出すのですが、これによって特段ケーブルテレビ品川に独占権というのですか、そういうふうに縛られることはないと考えてよろしいのですよね。","respondent":"柏原企画調整課長","answer":"それがゆえに、区の了承を得てという動きになっています。本当に一般と同じ使い方になりますので、全国的に使っている通信の会社、キャリア等と同様の扱いになっているというものです。","id":"exchange-007"},{"speaker":"つる副委員長","kind":"質問","question":"アンテナの設置なのですが、公共施設とかを中心にという答弁があったかと思うのですけれども、アンテナの設置協力費みたいなものがこういう場合に発生するのかどうかとか、月とかですね、そういう何らかの収入になっていくのかどうか、このあたりの説明を求めました。","respondent":"柏原企画調整課長","answer":"１つのアンテナで２キロ四方ぐらいをカバーするというところで、先ほど申しましたように、２０カ所以上はつけないといけないということです。そういったところと照らしながら、どういった形でお貸しできるのかというのは、今後の協議になってこようかと思います。","id":"exchange-008"},{"speaker":"つる副委員長","kind":"確認","question":"確認ですけれども、民間の携帯電話会社にアンテナを設置させたときに収入になるというところで協力をしたという経緯があるものですから、の説明を求めました。","respondent":"立川経理課長","answer":"区の施設、道路、公園等にアンテナを立てるとか電柱を立てるとかといった場合は、全て規定により料金をいただいているです。","id":"exchange-009"},{"speaker":"つる副委員長","kind":"質問","question":"そもそも前提でそういう料金が発生するものかという。そこをもしケーブルテレビ品川から伺っていなければ、また別途で結構ですけれども。","respondent":"柏原企画調整課長","answer":"どういった形でお貸しできるか、料金が発生するかどうかというのは、協議をしながらということになってくるというものです。","id":"exchange-010"},{"speaker":"大沢委員","kind":"意見","question":"話がわからなくなってしまったのですけれども、サービス自体は、２の、「サービス開始後、区内避難所の通信環境の提供を行っていく」というのが今までのやりとりだったのですがとの意見を述べました。","respondent":"柏原企画調整課長","answer":"アンテナの設置の具合によっては、１個アンテナを設置してもサービスはできないような状況ですので、希望的なところも含めて４月からサービス開始準備をやっていきたいという意味でここは書かせていただいたものです。","id":"exchange-011"},{"speaker":"大沢委員","kind":"質問","question":"既に今４月ですから、９月以降は、サービスが開始されるという時系列でいいのか尋ねました。","respondent":"柏原企画調整課長","answer":"今ご指摘いただいたとおりでございまして、そういったスケジュール感で動くということで、ケーブルテレビ品川からも聞いてあります。","id":"exchange-012"},{"speaker":"大倉委員","kind":"質問・要望","question":"どこかでこの取組みがされていることがあれば教えていただきたいのと、その中で、どういったものが検討されるのか。免許取得に先立ち、そういう部分ではできるのかどうかを確認されているのかどうか、余地があるのかどうかというのを教えてほしいと求めました。","respondent":"柏原企画調整課長","answer":"例えば河川の監視であったりだとか、それから見守りであったりだとか、そういったところで使っているということは情報として聞いてあります。","id":"exchange-013"},{"speaker":"大倉委員","kind":"質問・要望","question":"わかりました。防災対策以外でも見守り、そういった方向性はどういう感じで進めていくのかというイメージがもしあれば、教えていただきたいです。","respondent":"柏原企画調整課長","answer":"他自治体の事例を、どのような効果が出ているかという他の自治体の事例は、実際に見たり聞いたりというところはしていきたいと思ってあります。そういったところもありますので、他自治体の事例等をよく見ながら、区の中でも検討を進めたいと思っています。","id":"exchange-014"}]},{"id":"topic-03","title":"品川音頭","agenda":"品川音頭","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"１点、補作詩の方のほうの著作権の問題ということで、これから協議ということなのでしょうか。リニューアルの周知予定が７月１日に決まっているということで、今はもう４月末で、そういうことについての手順を少し教えていただけますか。","respondent":"中元広報広聴課長","answer":"やはり本人や遺族の方に説明をきちんとしていきながら行うのがトラブルにならないところだというアドバイスを受けておりまして、そうは申しましても。総務委員会でもご報告が終わった段階で、きちんと再度進めする、お話に上がろうです。","id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"それで、一部手直しをしただけで八潮の皆さんのご要望が入るということで、本当に喜ばれるのではないかと思います。個人名は別にいいのですけれども、どういうふうにしてこういう言葉が決まっていったのかなという経過の説明を求めました。","respondent":"中元広報広聴課長","answer":"こちらは区内の音楽家の方にご相談をしながらご提案をいただき、ただそれをそのままということではなく、区としても、広報広聴課といたしましても検討し、また、区の内部でも会議等を開き、検討した結果、これがよろしいのではないかということになりました。","id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"ちょっとだけ教えてください。（２）に歌無ダンスリミックスというのがいまいちわからなかったので、どういうふうになるか教えていただきたいのと、ご説明ほしいと求めました。","respondent":"中元広報広聴課長","answer":"このたび、ダンスリミックスバージョンで曲を少しアップテンポにしたものを検討していただこう、つくっていただこうということで考えております。もう１点の「踊る人の輪」ですが、先ほどと繰り返しのご説明になりますが、区として考えさせていただきました。","id":"exchange-017"},{"speaker":"大倉委員","kind":"質問・要望","question":"どういった人たちが踊れるようにしていこうとしているのかというのを教えていただきたいのと、「人の輪」なのですけれども、「わ！八潮を入れてほしいというお話だったと思うので、何かお考えがあれば、お話ほしいと求めました。","respondent":"中元広報広聴課長","answer":"させてくださいというお取り交わしの承諾書もお願いしていくということで、今、考えております。先ほどの歌詩のところですが、委員のご意見も踏まえまして、今後、検討、調整をさせていただければと思います。","id":"exchange-018"}]},{"id":"topic-04","title":"オープンデータ利活用による地域課題を考えるワークショップの開催","agenda":"オープンデータ利活用による地域課題を考えるワークショップの開催","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"例えば地域とか年齢とか、そういうことは一切なく、純粋にまるっきり全体の中からいわゆる抽選をするという趣旨なのでしょうか。その辺の説明を求めました。","respondent":"仁平情報推進課長","answer":"さまざまな年代の方とか性別関係など、平均して集まっていただければうれしいかなと思うのですけれども、公募抽選という形ですので、別に色をつけたような抽選はとらずに、シャッフルした中で、その結果に沿ってということで、公平性を担保していきたいと考えております。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"それは１つの例として出すのですけれども、そういう点での協働作業というのがどういうふうになってしまうのかなと思ったりもするのです。","respondent":"仁平情報推進課長","answer":"今後のことを考えますと、多角的なところからいろいろなアイデアといいますか、こちらから最初から範囲を狭めるという考えはございません。どういう対応をしていくかというのは、ある種、最初からがちがちにならないような形で取り組んでいきたいと考えております。","id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"１０月にアイデアソン、１１月にハッカソン、お願いします。の説明を求めました。","respondent":"仁平情報推進課長","answer":"もう１つのハッカソンなのですけれども、もともとハッカーというのはコンピューター関係の知識にたけた方のことをハッカーと呼んでおります。こちらもそういう取組みを継続して行っていくという、そういう意味でこの２つの造語になりますけれども、取組みの中で使われています。","id":"exchange-021"},{"speaker":"吉田委員","kind":"提案","question":"たとえ協働事業提案制度で採択されたものであっても、いろいろな人の参加を募りながら、持っていっていただきたいなと思います。１回１回ご報告があると私たちも意見を言ったりしやすいかなと思いますので、その辺だけ、要望しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"}]},{"id":"topic-05","title":"八潮北公園改修工事請負契約","agenda":"八潮北公園改修工事請負契約","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"全然わからないので教えてほしいのですが、日本パブリックサービス株式会社も含めて、それなりの知識のある事業所ということでいいのですよね。","respondent":"立川経理課長","answer":"その後、オリンピック競技にスケートボードが決まったということもありまして、それで急遽設計変更をしてこういう形にしたです。テニスコートもありますので防球ネットを配置したりしまして、危険性については十分配慮した設計をしています。","id":"exchange-023"},{"speaker":"南委員","kind":"質問","question":"利用したいという場合には、どこかに申し込んで、申し込み制なのですよね。これから設計してやるので大分先だと思うのですが、その辺はどんなふうに考えているのか、考え方の説明を求めました。","respondent":"立川経理課長","answer":"料金については現在検討中ですけれども、そちらの料金設定の状況とかを勘案して検討すると聞いているところです。管理につきまして、有人の管理施設がありますので、一体的に管理していくということです。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問","question":"すごく基本的な質問です。全然スケートボードがわからないので、スケートパーク設備の中のコンクリート製セクション３基が何かを教えていただけますか。","respondent":"立川経理課長","answer":"平面図の一番下のところなのですけれども、コンクリート製セクションということで、いわゆるコンクリート製の遊具というか、そこを滑って遊ぶみたいな、そういったイメージです。","id":"exchange-025"},{"speaker":"大倉委員","kind":"確認","question":"いろいろお話が出たので気になって聞かせてもらうのですが、スケートパークの特徴とかというのが品川区のスケートパークはあるのか。どういう人たちに利用されたいのかというのも、もしかしたら聞いたかもしれませんが、改めて確認をさせてください。","respondent":"立川経理課長","answer":"そういった内容、どういった利用者を想定するかとかいうことも含めまして、日本スケートボード協会と協議しながら計画をつくっていくです。","id":"exchange-026"},{"speaker":"大倉委員","kind":"質問","question":"これからこういう内容については検討していくというお話なのか尋ねました。","respondent":"立川経理課長","answer":"どういった遊具を配置するかとか、そういったことを日本スケートボード協会と協議しているですので、今後、設計内容に入っていくと考えています。","id":"exchange-027"}]},{"id":"topic-06","title":"品川区西五反田二丁目付近再構築工事請負契約","agenda":"品川区西五反田二丁目付近再構築工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"ということは、何年か前に工事をされていて、やはり排水の能力が不足したために、今回、それも兼ねて行うという対応なのですか。何年ぐらい前にやったのか尋ねました。","respondent":"立川経理課長","answer":"再構築工事につきましては、整備後、約５０年経過したことから、実施していると聞いております。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/762881?Template=document&Id=2072#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":26869,"voices":117}},{"id":"h29-20170425-14","meetingId":"h29-cm04","date":"2017年4月25日","dateIso":"2017-04-25","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ４時０５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件整理しています。","topics":[{"id":"topic-01","title":"平成２９年請願第４号、羽田空港機能強化による品川区低空への新飛行ルート","agenda":"平成２９年請願第４号、羽田空港機能強化による品川区低空への新飛行ルート","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"まず最初にお伺いしたいのは、前回も前々回も伺ったのですが、国に回答を求めていただいたのでしょうか。それと、品川区の上を通る新ルートの実施にかかわる部分というのはどこになるのか、伺いたいと思います。","respondent":"中村都市計画課長","answer":"まだ詳しい位置というのは未定で、あくまで案の段階ということですので、そういったものに対する情報の提供ができないです。完成の時期ですが、この施設整備につきましては、そういった国の目標の年度を達成できるスケジュールで進んでいるというふうに考えてあります。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"国は言ってくれないわけですから、国に事実確認をしていただきたいのですけれども、いかがでしょうか。伺います。","respondent":"中村都市計画課長","answer":"新飛行ルートを仮に国が実施をするとしたときに、このための設備としては、この設備は必要だということにはなります。これは国のほうに問い合わせるまでもなく数学的に数式で出るので、事実確認はこの式が正しいかどうかをもって確認ができるかと考えております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"確認","question":"昨年の２０１６年では既に２,４００万人を達成しているわけですけれども、お伺いしたいのですが、どれぐらいなのでしょうか。それをまずお伺いしたいと思います。","respondent":"中村都市計画課長","answer":"訪日外国人の割合、空港の割合ですけれども、こちらのほうは羽田とか成田とか関西ですとか、重立った空港の中で占める割合が、羽田は全体の１２.６％、これは２０１５年の出入国管理統計からそういった数字の記載があります。","id":"exchange-003"},{"speaker":"安藤委員","kind":"提案","question":"直近でいうと２,４００万人なわけですから、提案されているのが南風時の３時から７時で、何人分増やせるという計画なのでしたか。伺いますとの意見を述べました。","respondent":"中村都市計画課長","answer":"しっかりとした整備ですとか、こういった人的育成にも力を入れているという説明が、この説明会の中でもございました。ここでめぐりめぐってつながってくる問題だと考えておりますので、しっかりと国のほうへは申し入れをしていきたいと考えております。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"こんなに羽田空港以外で、１,３８８万人もほかのところで増やせるのかというのが率直な疑問なのですが、そういう計画なのでしょうか。伺いたいと思います。","respondent":"中村都市計画課長","answer":"国のほうからの説明の資料がホームページなどで掲載されているものでは、考え方として１つ示されております。あくまで未定の中で検討はされているのかとは思いますが、はっきり言いまして、これ以上の情報が来ていないというところが現状です。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"そうした中で、そういった意味でもやめるべきではないかということをお伺いしましたので、そこの点はご答弁をお願いしたいと思います。とりあえず３時から７時でとどまらないということになるのではないかというのは心配なので、そこら辺をお伺いしたいと思います。","respondent":"中村都市計画課長","answer":"実質４時間の中の、実際切りかえも含めると３時間というような国の説明がございましたが、あくまで区としてはその中で必要な情報を求めていくという姿勢をとっているところです。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"やはり今から将来の増便を見据えたような、しっかりとこの時点で計画はやめるべきだということを言うべきだと思いますけれども、いかがでしょうか。そして、幹事会の副座長というのはどこの区の方が務めているのか、伺いたいと思います。","respondent":"中村都市計画課長","answer":"検討の中では概念としてはございませんけれども、即座に国のほうへはその対応や必要な情報を求めるということが大切だというふうに考えてあります。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこでも言っているのかどうかというのは、１３回の幹事会のなどでどのような議論があって、品川区は何を発言したのか伺いたいと思います。今回の請願は、説明会については再三求めているというふうに言っていると思うのですけれども、それもあわせて伺いたいと思います。","respondent":"中村都市計画課長","answer":"地域への説明をしっかり行ってほしいということと、あと、必要な情報をしっかり提供してほしいと。それで、説明会ですが、教室型の説明会というものも国に対して開いてほしいというようなことは、これは各区から意見が出ているところです。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、必要な情報提供や不安の払拭など、説明を丁寧にという意見にとどまらない反対表明をぜひしていただきたいと。述べてほしいというふうに要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"いろいろと議論を伺わせていただいたのですけれども、先ほどのご質問の中にあった、すごく限定した数字の中での１.７倍ということなのです。国際線は中型機が主流ですから、３,５００万人増やしていくということでいえば、せいぜい１割ちょっとということなのです。","respondent":"中村都市計画課長","answer":"先ほどもご質問にあった教室型の説明会ですとか、こういったものもそうなのですが、区としてはいかんともしがたいというふうに考えております。","id":"exchange-010"},{"speaker":"あべ委員","kind":"確認","question":"１点目のほうなのですけれども、羽田空港の利用客がさらに増えることをプラスと考えているという、その考え方でよろしいのでしょうか。ここで議会のレベルで伺っていることについても、そういったことから、数字をきちんと読み取るところからしてほしいと。","respondent":"中村都市計画課長","answer":"初めのご質問で、品川区内の外の方がたくさん来ていただくということは、すごく品川区にとってメリットがあることだと考えております。そういった中で、そういったところは東京都にもそういった問題点を指摘してまいりたいと考えています。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問・要望","question":"これ、皆さん品川区役所ですから、品川区民にとって非常に大きな影響があるということがほぼ確実な計画なわけですよね。難しくないという議論もあるかもしれませんけれども、でも、質問にただ答えるために答えるような形で進めてはいただきたくないと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"明らかにしていくためにもお聞きしたいと思うのですけれども、新ルートをやるためには必要だけれども、飛ぶため以外というのは何があるのか尋ねました。","respondent":"中村都市計画課長","answer":"これは区としては具体的に挙げることはできませんけれども、まだあくまで案ですので、それ以外の可能性もあるでしょうという意味です。これは国の説明会等、あるいはパイロットの専門的な教育、そういったものを人材育成というふうに国の説明資料の中では書かれているところです。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"今回紹介された事例でいえば、検査員の方の事例でしたけれども、そういったところの人材育成はやられていないということなのでしょうか。伺いたいと思います。","respondent":"中村都市計画課長","answer":"そこら辺は国のほうではしっかりと事前に研修等の教育を行って、抜き打ち検査がしっかりできるような人材を育成してこの職に充てるということは、かねてから言っているところです。","id":"exchange-014"},{"speaker":"のだて委員","kind":"確認","question":"もう一つの質問のほうで、実際には飛ぶための施設整備をしていると私は認識していますが、区の認識を伺いたいと思います。その後、約２カ月が経過しましたけれども、確認されたのか伺いたいと思います。","respondent":"中村都市計画課長","answer":"それ以外の説明は国のほうではございません。外国からも受け入れをするという、この国際基準に基づいて行っているです。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうでなければ、日本と他国の安全性には違いがあると思いますけれども、いかがでしょうか。１９９４年のときには、中華航空の墜落事故で２６４名の死亡者も出ているというところで、安全性は同レベルと言えるのか伺います。","respondent":"中村都市計画課長","answer":"特に整備なんかは、機種がいろいろ違いますので、やはりなかなか機械化は非常に難しいと思います。日本国内に入国、それを国際航空機関ですとか、さまざまな関連の機関のほうに伝えていただくように申し入れはしてまいります。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問","question":"しっかり監視できていない部分もあるというところで、日本の航空機と海外の航空機が同レベルだと本当に言えるのか、改めて伺いたいと思います。そして、日本で国際基準より高い部分はあるのかということもお伺いしたので、改めて伺いたいと思います。","respondent":"中村都市計画課長","answer":"ただ、こういった機械的なところにつきましては、国際基準というのは十分に整備に対する安全の基準というのは満たされているのかなと考えております。航空機の整備に関しましては、その範囲の中でしっかりと適正な整備が行われていると考えております。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"やはり国際線が増えてくると、安全性についても危険が増してくる可能性があるのではないかと思います。この間も３回の説明会が品川でも行われてきましたが、そして、合計人数もあわせて伺います。","respondent":"中村都市計画課長","answer":"３回にわたる説明会ですが、第１フェーズですけれども、こちらは品川区役所の第二庁舎、アトレ等で行われて、合計来場者が８６０名です。それから、２月１１日のアトレでつい先日行いました説明会では、１日でしたが、速報値で３９６名です。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"区民に知らせていくためにも、やはりこの請願にもあるように、説明会を行うべきだと思いますけれども、いかがでしょうか。これを求めているのは、幹事会でもしっかりと発言されているのか、伺いたいと思います。","respondent":"中村都市計画課長","answer":"説明を行ってほしいという話をしておりまして、この説明会まで国としてやってもらっているところですけれども、また。説明会をたくさん開いてほしい、教室型の説明会を開いてほしい、こういった意見もくまなく国のほうへは伝えているところです。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間も求めているというお話ですけれども、実際に国はやらないわけです。区が国を呼んで会場を確保して、そして、周知もして主催する説明会を１３地域センター管内それぞれで行うことを求めますが、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"これからも区民の皆様へ周知するための説明会、これは区が直接説明をして、やはり国にしっかり参加していただくことが大切だと考えております。国のほうもそういった設定の中で説明会をやるということは今までもやってきておりますので、引き続き区も説明会について協力して。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひいろいろなところでやってほしいと求めましたけれども、今のご答弁は、しっかりと進めていく、国と連携をとって区が主催で説明会を設定していくという認識でよろしいか尋ねました。","respondent":"中村都市計画課長","answer":"形としては、あくまで国が主催ということになりますが、それに対する調整等の協力をしっかりとしてまいります。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"これをつくっていく、このことをやっていくべきだと思いますけれども、区がやらない理由は何なのか伺いたいと思います。先ほどの質疑でも、それも区がやっていくこともできると思いますが、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"区が説明会を開催した中で、変更しますといった回答までできませんので、区はそれに可能な限り協力をするという形で行わざるを得ないところをご理解いただければと思います。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後にしますけれども、国がやらない中で、区が主催して、国を呼んで説明させる、こういった場のやり方もあると思いますので、しっかりと国が説明するまで、教室型説明会を開くまで求めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"国が丁寧に説明すると言っているわけですから、採択できないというか、その理由がむしろ聞きたいなと。もしあるのなら、ぜひ他会派の皆さんのお考えも、聞かせていただきたいというふうにも思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"あべ委員","kind":"質問・要望","question":"そういう手法も考えていただけないかということも含めて、今回は継続としてほしいと求めました。多分、区の事業でないものを区が説明会を開くというのは困難であるかと感じます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問・要望","question":"理由は、この請願者の方が求める説明会の中で、どなたが説明するのか。国にもっと説明会を開いてくださいということを求めるということなのか、今回、この趣旨について採択をいたしたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-02","title":"平成２８年請願第８号、住民の理解が得られない中、平成２９年度予算概算要求に、新ルート費用を入れないよう品川区として政府に求める請願","agenda":"平成２８年請願第８号、住民の理解が得られない中、平成２９年度予算概算要求に、新ルート費用を入れないよう品川区として政府に求める請願","exchanges":[{"speaker":"渡部委員","kind":"確認","question":"終わっていることに対して、ここでどうこうというのはどうなのかと思っているのですが、その辺の確認だけ、委員長、お願いいたします。どうしてもここで採決を行わなければならないというのであれば、不採択しかやりようがないものですから、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"渡部委員","kind":"確認","question":"もしですけれども、この羽田の内容等が引き継がれるようであれば、それは私どもは継続になるという思いでおります。ですから、内容が内容だからというところで取り下げの確認をお願いしているわけですから、であれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"若林委員","kind":"質問","question":"継続で結構です。前回３月ですか、一回継続で、ほかのものと一緒にまた審査を継続するということで結構だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"概算要求をしないように求めてほしいというもので、事実を積み重ねないでほしいというものなので、酌むべきだと思います。ですから、私たちとしては、先ほどの趣旨で、結論を出すで、趣旨採択ということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"あべ委員","kind":"質問・要望","question":"まさに平成２９年度概算要求の内容そのものを求めているとすると、その趣旨について賛同できるところもあると感じているところです。非常に今、悩ましい判断を求められていると思うのですが、私ども……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"趣旨採択でお願いします。平成２９年度政府予算概算要求についてなので、住民の理解が得られないまま、趣旨採択でお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/172349?Template=document&Id=6026#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":31711,"voices":98}},{"id":"h29-20170426-18","meetingId":"h29-cm04","date":"2017年4月26日","dateIso":"2017-04-26","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ３時２７分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を6件整理しています。","topics":[{"id":"topic-01","title":"東京都宛の要望書","agenda":"東京都宛の要望書","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"周辺道路のところ、要望書の項目４番にはこういうふうに書いていただいているのですけれども、その辺をうまく挿入できないかと思ったりしていました。改めて東京都に出すのであれば、しつこいかもしれないのですけれども、もう一度入れていただけないかと思って発言しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"南委員","kind":"意見","question":"その後に、具体的な文章を出していない中でのあれで申しわけないのですけれども、正副のところで検討していただければありがたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"意見","question":"５番目のところ、反映をしていただいてありがとうあります。お任せいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問","question":"議運でやるときには、ここで確定していかないと議運で諮れなくなってしまうのではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]},{"id":"topic-02","title":"の４、その他","agenda":"の４、その他","exchanges":[{"speaker":"藤原委員","kind":"確認","question":"１点だけ確認したいのですけれども、質問してよろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"どうなってしまっているのですかということだけお伺いしたい。よろしいか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そのような形になって、私、今、大変反省しております。今、皆さんがきちんとオリンピック・パラリンピック機運醸成に向けて親しんでいただけるように、今後とも工夫してまいります。","id":"exchange-006"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/645888?Template=document&Id=6512#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":5208,"voices":33}},{"id":"h29-20170428-10","meetingId":"h29-cm04","date":"2017年4月28日","dateIso":"2017-04-28","committee":"議会運営委員会","time":"午後 １時０１分～午後 １時２３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"特別委員会の調査事項","agenda":"特別委員会の調査事項","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"行財政改革特別委員会の備考について、区有施設、国・都有地等の有効活用について、一言意見、要望だけ述べたいと思います。これまでどおり、こうした区の土地も含まれる方向で議論を進めていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/706163?Template=document&Id=5220#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":8675,"voices":40}},{"id":"h29-20170515-6","meetingId":"h29-cm05","date":"2017年5月15日","dateIso":"2017-05-15","committee":"区民委員会","time":"午後 １時００分～午後 ３時０１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"「支え愛・ほっとステーション」の開設","agenda":"「支え愛・ほっとステーション」の開設","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"どういうふうに仕切っているというのか、役割分担をしているというのか、そこを伺いたいと思うのです。町会や民生委員から上がってくる、なかなかなり手がいないというのもどういうふうに届いているのか、そこをご説明ほしいと求めました。","respondent":"遠藤協働・国際担当課長","answer":"今回、地域センターに引き続きその拠点を置きますので、福祉計画課と今後も調整しながらまた進めていくような形になろうかと思います。その辺と協力しながら、全地区になりましたので、どんどん進めていければと考えているところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"率直に言えば所長に何でも相談できる、そういう関係は構築しているとは思うのですけれども、どちらの課に相談をすればよいのでしょうか。コーディネーターの話もありましたけれども、そこだけもう一度ご説明いただけますか尋ねました。","respondent":"遠藤協働・国際担当課長","answer":"今までですと、民生委員の所管が福祉計画課で、町会の所管が地域活動課という形で、何となく分かれてきたところです。それぞれつながりの強いところがありますので、そこは区側で一体となっていろいろなところに働きかけてやっていければです。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問","question":"今までやってきた支え愛・ほっとステーション、その中で見えてきた課題と問題点、あと、そこをどのように改善していって、今回の開設に向けて動いているのかということを伺いたいのですけれども。","respondent":"遠藤協働・国際担当課長","answer":"地域支援員というのが、ボランティア活動をお願いするところなのですが、その方たちのなかなかなり手がいないという部分があったかと思います。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問","question":"荏原第五地域センターの方からお話を伺ったときに、やはりすぐ支え愛・ほっとステーションができてほしいという声が聞かれたのですけれども、人を増やしていくかということをお聞きしたいのですけれども。","respondent":"遠藤協働・国際担当課長","answer":"説明が悪かったかもしれませんが、生活支援サービスの中のほっとサービスというなり手の方、そのボランティアを地域支援員というふうに呼んでいるところなのですけれども。","id":"exchange-004"},{"speaker":"田中委員","kind":"意見","question":"先ほども出ていたように、ボランティアをしてくださる方がいっぱい来てくれたらいいなと思うので、その周知活動をしっかりとやってほしいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"こんの委員","kind":"質問","question":"今までの委員と質問がかぶってしまうこともあるかもしれないのですが、その辺、理解度が違いましたらご指摘ください。これまで開設したところの課題も含めて、コーディネーター２人で全部やっていくという、これはどのようにお考えか尋ねました。","respondent":"遠藤協働・国際担当課長","answer":"２人ではなかなか全員をといいますか、高齢者をサポートするのは難しいというのは、おっしゃるとおりかと思います。新たに登録いただいた地域支援員が定期訪問ですとか、お二人だけではできない形でありますので、現在もそういう形で行っていると聞いております。","id":"exchange-006"},{"speaker":"こんの委員","kind":"質問","question":"わかりました。例えば、介護が必要だという高齢者のご相談だった場合に、在宅介護支援センターとも連携をとりながらやっているという理解でいいのか尋ねました。","respondent":"遠藤協働・国際担当課長","answer":"あくまでも地域支援員が行くのは、介護が必要な方につきましては、在宅介護支援センターと連携をとって進めるというふうに聞いております。","id":"exchange-007"},{"speaker":"こんの委員","kind":"質問・要望","question":"だけど、いろいろな地域の資源となる方々と連携をとってということで、多分、周知されると、本当にいろいろな相談が入ってくると思うのです。どう相談者を必要なところにつないであげられるかというのは、頑張っていただきたいというところですが、いかがか尋ねました。","respondent":"遠藤協働・国際担当課長","answer":"どんどんいろいろなケースを踏まえて、その中でケーススタディーみたいなものも行うというふうに聞いておりますので、徐々にすぐに回答できるような態勢をとれるようにしていければと考えています。","id":"exchange-008"}]},{"id":"topic-02","title":"今後の区の産業活性化に向けた調査の実施結果について（平成２８年度産業活性化推進事業）","agenda":"今後の区の産業活性化に向けた調査の実施結果について（平成２８年度産業活性化推進事業）","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"もう一度確認なのですが、これを簡単に教えていただきたいということと、なぜ６９.６％の回収率なのか。ここに上記のうち１２商店街（１７名）役員等に個別ヒアリングを実施と書いてあるのですけれども、個別ヒアリングとはどういう意味なのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"その下に(3)、商店街アンケート及びインタビューの実施状況のところで３９票という、これが先ほどの３９の根拠になっているところです。答えになっていなかったら申しわけありませんが、経過は以上です。","id":"exchange-009"},{"speaker":"いながわ委員","kind":"質問","question":"５６商店街というのは、見える商店街なわけですから、なぜ５６商店街のアンケートをとれなかったのか。逆に言えば、３９商店街だから、１７商店街は、アンケートも答えていなければ、要するに行ってもいないということなのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"私ども、この報告書の１６ページから記載しておりますが、商店街を実は区内１０ブロックに分けてあります。１２カ所、１０ブロックを包括する１２回行ったということで、ご理解を賜れればと考えているところです。","id":"exchange-010"},{"speaker":"いながわ委員","kind":"質問","question":"品川区の商業にかかわることですから、５年に１回ですとか、１０年に１回なのかわからないですけれども。政策にも反映されるわけですから。","respondent":"山崎商業・ものづくり課長","answer":"商店街のほうは実際のヒアリング調査は７月４日から７月２９日という限られた時期にできる限りのヒアリングを行ったというようなところで、何とか担保させていただけるかなということで、ご理解を賜りたいと考えています。","id":"exchange-011"},{"speaker":"いながわ委員","kind":"質問・要望","question":"パーセンテージですから、それは多いほうがいいと思いますし、回収率も多いほうがいいのではないでしょうか。これはやはり真剣に品川区としてぜひお考えほしいと求めましたので、行ってどういう現状があるのかという、ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"幾つか伺いたいのですけれども、テンポといいますか、今後のスケジュールやテンポについてご説明ほしいと求めました。最後に３点目なのですけれども、コンサルティング会社はどこなのか、会社名を伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"それから、こういった方向の施策の展開が必要ではないかということで、特にそれに対してわかりやすい概要版をつくるという予定にはなっておりません。ここから何かしらわかりやすいものにするというのは、技術的には簡単ですので、そこは検討させていただければと考えています。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"まず進めていただきたいのは、２５ページの一番下にあります中小企業の、いわゆる防災対策耐震化等の活用の希望が多いということです。２００名程度の製造業であり、この点については今後どういう展開を考えていらっしゃるのか、現状を伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"いわゆる震災以降、区民の方々の生活の部分に加えまして、すごく大事なことだと区としては認識しております。ここに書いてあるとおり、関係機関などとの調整を踏まえながら、これは検討なり研究していく必要はあるかとは思っております。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"雇用の確保も含めて、大事な支援だと思いますので、適宜急いで具体化の要望をお願いしたいと思います。補助第２９号線、この最終報告ではどのような考えが示されているのか伺いたいと思いますし、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"商店街の持つ公益化、多様化などにも対応していく必要があるので、それに対して支援を検討すべきだというような調査結果です。区としましては、そうした考えのもと、当該商店街の皆様とこの問題についてもいろいろしっかり対応していきたいと考えています。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、ずばり補助第２９号線や戸越公園駅周辺のまちづくり、そこを改めて伺いたいと思います。これが区の商業支援の基本的な考え方なのか、ここは改めるべきだと思うのですけれども、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"路線型の商店街の中で、それぞれの個店の立地位置によって、いわゆる都市計画道路の整備による影響は違ってくると。ただ、あるいはまちづくりのほうと連携していきながら、そうしたものを火を消さずにしっかりこれはつないでいこうというようなことで一致しています。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどから伺っているのは、そこを伺っているので、しっかりと区の考えをご説明ほしいと求めました。それだけに、いわゆる再開発事業の推進が位置づけられているのかいないのか、そこをしっかりとご説明ほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"変貌に合わせた新しい個店の集積なども含めて、そこも一つの個店の集まりとしての商店街の機能であろうというようなことを考えております。例えば、パトリアを中心にした個店の集積に対しまして、商店街機能として区としてご支援をさせていただいたりというようなことですので。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問","question":"商業編についてです。お伺いしたいのですけれども、全国でも３６位にランクされて、その辺を聞かせてください。","respondent":"山崎商業・ものづくり課長","answer":"確かに区の境界という意味では、私どもが認識をしている、京浜急行で言うところの北品川と品川の間に区境があります。そのエリアというのは、目黒区の区民の方々も含めてというようなことで考えて対応しているというようなことで、ご理解いただけたらと考えています。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問","question":"もっと具体的にどのあたりが旅行者の方たちが好んでまち歩きをされているのかわかったら、観光事業のほうなどでも役立つのかなと思います。","respondent":"山崎商業・ものづくり課長","answer":"細かい、なぜ不動前にというようなところについては、直ちに私どもで調査をした結果ではございませんのでというようなことです。","id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"期待している声とともに、やはり商店街は再開発によって潰されてしまうのではないかという声も、商店街の方からは伺っています。期待されている反面、そういう声もあることは反映されないのかという、その辺はどうなのかということを伺わせてほしいのですけれども。","respondent":"山崎商業・ものづくり課長","answer":"商店街の現状と周辺の大きなエリアとしてのまちづくりの方向性などと重ね合わせた表現というようなことになっております。現状のにぎわいを、こうしたまちづくりの大きな動きの中でともに検討して、商店街振興側としてはそういった思いで書かせていただいているところです。","id":"exchange-020"},{"speaker":"田中委員","kind":"意見","question":"もしかしたら、不安な声がアンケートに書けなかったのかもしれない等、あるかもしれないです。そういう声が反映されていたらいいなと思うのですけれども、そういう声に対して、一言いただければとの意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"本調査表のほうでも、４４ページ、４５ページあたりに個別意見をいろいろ書かせていただいております。それをどちらかに答えを決めるとかということではなくて、区のほうではしっかり丁寧に拝聴してまいりたいと思ってあります。","id":"exchange-021"},{"speaker":"こんの委員","kind":"質問・要望","question":"確認ですが、報告をまとめたものまとめないものも含めてされていたかどうかという確認が１点と、それ以外は約１年前に調査が終わっていると。","respondent":"山崎商業・ものづくり課長","answer":"「はぐくむ」「つなげる」「ひろげる」というようなことを先程ご説明申し上げましたけれども、途中では、弱みと申し上げていいのでしょうか。もう少しわかりやすく説明しますと、商売を繁盛させるための販路をしっかり拡大していくということが１つです。","id":"exchange-022"},{"speaker":"こんの委員","kind":"確認","question":"これとその３カ月のとはどういうふうに見ていくのですか。これはどういうふうに見たらいいのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"ものづくり・経営支援課という、中小企業の支援をメインに行っているところと、商業・観光課という課が２年前に一つになりました。そういう意味では、組織をつくって今後の大きな方向性はどんなところにあるかということをやらせていただいたというのが今日の調査報告書です。","id":"exchange-023"},{"speaker":"こんの委員","kind":"質問","question":"わかりました。確かに平成２９年度、本当に今時点でどうなのかという調査にもっとしていきながらやっていくべきではないかと思いますけれども、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"こうした結果を次の産業活性化の施策のためにしっかりと基本的に活かしてまいるように使ってまいりたいと考えております。２点目につきましても、商店街の皆さんの活力を高めることに資することは何なのかということですので、最適をしっかり考えてまいりたいと思います。","id":"exchange-024"},{"speaker":"伊藤副委員長","kind":"確認","question":"お伺いしたいのが、表現が最終報告書なのです。ですので、どちらのものを品川区は政策の方向としてとっていくのかという確認させてください。","respondent":"山崎商業・ものづくり課長","answer":"全体のまちの変容なり、再開発の構想におきましては、副委員長のおっしゃったとおりのことが正しい表現かなという感じがいたします。記載をさせていただければと率直に思っておりますが、そうした意味合いで捉えていただきたくよろしくご理解を賜りたいと思います。","id":"exchange-025"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"だから、縦割りではなくて横串の中で品川区がどう取り組んでいくのかというのをしっかり見詰めていかないと、こういうことになるわけです。だから、議会はそこを今指摘させていただいていますので、連携をとって進めていっていただきたいと思うのですが、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"工場跡地が大規模マンションに変貌していくようなまちの変化が見られるようなエリアということは十分認識してございまして、一番最寄りの。横串とおっしゃいましたけれども、まさにそのとおりで、しっかり努めてまいりたいと考えています。","id":"exchange-026"}]},{"id":"topic-03","title":"総合体育館非構造部材他耐震化工事","agenda":"総合体育館非構造部材他耐震化工事","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"便所排水管耐震化工事ということですけれども、要するにどういう工事になるのか。これが実施されると、災害時に避難をされた方がどういうふうに何が改善されるのか、そこをご説明いただけますか尋ねました。","respondent":"池田スポーツ推進課長","answer":"こちらのほうは、こちらのほうが鉛管になっているところがございまして、こちらが大きな地震が来るとずれが生じて使えなくなることがあります。そういったものを、大きな地震が来たとしても、排水がきちんとできるように、耐震化工事です。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"つなぎ目だったり、ずれが生じないため、要するに、下水道管の耐震化という趣旨なのでしょうか。補完避難所機能の強化ということですから、大震災を想定した際にどういうふうにこれが使えるようになるのか、そこを伺いたいのですけれども。","respondent":"池田スポーツ推進課長","answer":"排水の部分につきまして、外管のところでのつなぎ目の工事をするというふうなことを伺っておりまして、内部については特段の工事はする予定はないということです。","id":"exchange-028"},{"speaker":"中塚委員","kind":"確認","question":"水道のライフラインが途切れても、総合体育館の、補完避難所としてこのトイレは使えるということでよろしいのでしょうか。そこだけ最後、確認いたします。","respondent":"池田スポーツ推進課長","answer":"そのように使えるようにということでの今回の工事です。","id":"exchange-029"},{"speaker":"本多委員","kind":"質問","question":"工事の必要性については理解できますので、ぜひよろしくお願いします。それで、武道場と卓球・レクリエーション室の代替えについて、何か工夫とかあれば、その辺、の説明を求めました。","respondent":"池田スポーツ推進課長","answer":"そのほかのものとしまして、文化センター、それからこみゅにてぃぷらざがありますけれども、そちらのほうも卓球等ができる部屋があります。現在、総合体育館を利用されている方に対して、そこを優先的に利用していただくというようなことは考えていないところです。","id":"exchange-030"},{"speaker":"本多委員","kind":"質問","question":"わかりました。配慮しなければいけない部分が出てくるかと思うのですが、その辺というのは、今回の工事とかに活かされるのか尋ねました。","respondent":"池田スポーツ推進課長","answer":"今回の工事につきましては、あくまでも非構造部材の耐震化の工事ということでございまして、主に行う工事につきましては、天井の工事を行う予定です。","id":"exchange-031"},{"speaker":"本多委員","kind":"質問","question":"説明方はわかりましたけれども、オリンピック・パラリンピックに向けてそれでいいのか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"大会組織委員会のほうで全体の練習会場の見直しを行いまして、今、検討をしています。特にバスケットボールということはございません。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"予特でもちょっと伺ったのですけれども、はっきりこの委員会でどちらを言葉的に言えばいいのか教えていただきたいのが１点と、それと。これは安藤部長が当時の課長でしたから教えていただきたいのと、誘致といいますか、その辺についてどう思っていらっしゃいますか。","respondent":"池田スポーツ推進課長、小川オリンピック・パラリンピック準備課長","answer":"１階から地下２階まで、こちらのほうにそれぞれシャワーつきの温水が出るもの、ヒーターつきの便座をつける予定になってあります。練習会場ですが、昨年度より区のほうに協力をしてほしいということで話があります。区といたしましては、積極的にぜひ協力したいと考えているところです。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問・要望","question":"ほかの特別委員会でも伺ったのですけれども、どうなっているのだという質問を特別委員会でさせていただいたのですけれども。部を挙げてやっていたわけですから、そこだけははっきり答弁していただきたいのですけれども、いかがか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"できればあちらにつきましては、イベントですとか、職員の目の届くところで活用していきたいと考えています。あちらは今、食堂のところからは取り外しましたけれども、気持ちとしては機運醸成の気持ちを一生懸命やっていきたいと考えているところです。","id":"exchange-034"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"これは歌とか振りつけとか、全部でき上がっているのですか。それとも、１８日に向けて、今、いろいろ音楽の調整とかをしているのかどうなのかというのをお聞きします。","respondent":"池田スポーツ推進課長","answer":"およそ２分半がまず１つございまして、もう一つの曲が３分ということでございまして、気軽にできるスポーツです。そのころにはＣＤとかＤＶＤも完成する予定ですので、完成した暁には、よろしくお願いいたします。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/824061?Template=document&Id=2780#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":36605,"voices":92}},{"id":"h29-20170515-7","meetingId":"h29-cm05","date":"2017年5月15日","dateIso":"2017-05-15","committee":"厚生委員会","time":"午後 １時００分～午後 ３時０５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"「支え愛・ほっとステーション」の開設","agenda":"「支え愛・ほっとステーション」の開設","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その対策というか対応をどうされてきたのかについてお聞かせほしいと求めました。日中独居など、そういう利用者の状況というのがまとめられているようなものがあれば、その状況もわかったら教えていただけたらと思います。","respondent":"大串福祉計画課長","answer":"ただ、あるいは電球の交換といったものをやってほしいというお声をいただくときには、それに対応する形でボランティアの方をお願いする。そういった方に対して対応をしています。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"様々やってほしいという要望、できないとか、どうしてこんな状況なのかというところもお聞かせほしいと求めました。以前伺ったときに、設置時と運営費に２分の１の補助が出るということで説明をいただいたと思うのですけれども、これは今も同じ状況なのか。","respondent":"大串福祉計画課長","answer":"こちらは生活支援体制整備事業の中で、こういった第１層、第２層協議体といったものが介護保険上で提唱されているところです。第２層協議体という形を位置づけておりますので、そこにつきましては介護保険の対象、介護保険上の事業という形をとらせていただいているところです。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"去年１１月５日に地域の支え愛推進フォーラムをやりましたが、そこのところが介護保険の財政から出されるということでいいのかということです。その支え愛活動会議のメンバーとワークショップの内容とか、そこら辺のところも教えていただけたらと思います。","respondent":"大串福祉計画課長","answer":"ワークショップは、昨年３地区で実施をさせていただきました。今年度も１３カ所分の予算をとっておりますので、地域福祉、地域で支え合う体制づくりといったものをつくっていきたいと考えているところです。","id":"exchange-003"},{"speaker":"安藤副委員長","kind":"質問","question":"例えば品川第二ですと、年々件数が大きく減っていたりするのですけれども、この理由は何なのでしょうか。それと、利用している方で要介護に相当する人ですとか要支援に相当する人が、このサービスを利用しているということはないということなのか尋ねました。","respondent":"大串福祉計画課長","answer":"ただ、当然生活していく中で、先ほども言っておりますような日常生活上の何かお手伝いといったことが発生すれば、それは対応しています。平成２５年度には、民生委員は３年に１度、通常よりは増えているといった状況かと考えています。","id":"exchange-004"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"もう１点は、これは全国に先駆けてという状況なのか、進んでいる自治体ということになるのでしょうか。そこら辺の品川区としての相対的な位置についてのご認識についてお伺いします。","respondent":"大串福祉計画課長","answer":"あるいは在宅介護支援センターに行くというのは、なかなか一般の区民の皆様にとってはハードルが高いのかなということを考えております。","id":"exchange-005"}]},{"id":"topic-02","title":"「しながわっこのサポートブック」の作成","agenda":"「しながわっこのサポートブック」の作成","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこら辺のところはどういう子どもを対象に考えているのか、何歳くらいまでを考えているのかということをお聞かせいただきたいのが１点です。","respondent":"中山障害者福祉課長","answer":"そのため説明会も、既にサービスを使っている方はある程度、障害に対する受容があるということで、そこから進めていこうと思っています。品川区もこれは第１版ということで、説明会を行い、版を重ねていく必要があるかなとは思っています。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことを私も育成会の方からも伺ったのですけれども、様々な勉強会を通して、記入していくということにもつながっていくのかなと思うのです。それで、様々とインターネットを見ていたら、こういうサポートブックも障害の種類によって、知ってほしい項目も違っています。","respondent":"中山障害者福祉課長","answer":"相手先がそれを有効に支援につなげていただかないと、逆にこれから保育課ですとか教育委員会に説明する際にも、例えば発達系のお子さんであれば。使っていく中で、例えば発達障害の方向けのシートをもう一枚プラスしていくなどの形で対応していければと考えております。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういうのを書いていただいたほうが、よりわかるかなと思ったのですけれども、その点についてお聞かせいただきたい。個人情報が丸々全て、個人情報の取り扱いに対しての取り組みというのは、区としてどう考えられているかということについてもの説明を求めました。","respondent":"中山障害者福祉課長","answer":"このサポートブックがどういうものなのか、どういったことを大事にしていきたいのかということを、勉強会の中で周知を図っていきたいと考えています。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"大田区などでは、多分この勉強会に参加はしなくても、こういうものがあったら自分も使いたいという人はいると思うのです。そういう方が使えるようにもなるのかどうか、そのことを最後にの説明を求めました。","respondent":"中山障害者福祉課長","answer":"６月の品川児童学園の保護者向けの説明会をやった後に、区のホームページにもこちらは載せようと考えています。ですので、そのときにこのシートだけではなく、目的ですとか利用の方法といったところも、しっかり載せさせていただければと考えております。","id":"exchange-009"},{"speaker":"たけうち委員","kind":"質問","question":"これは「サポートブック」になっているのですけれども、そうすると、今配られている紙ではなくて、冊子みたいな形になるのかなというのが１つです。３年前だったか、こういう形になったのか、そこの説明を求めました。","respondent":"中山障害者福祉課長","answer":"支援者同士がつなぐのか、個人情報の取り扱いのこともあって、どちらのパターンでつくっていくのがいいのかというのが議論になっていたかと思います。自分の子どもの特性ですとか、安心することであったり、不安になることを知ってもらうために、今回つくったものになります。","id":"exchange-010"},{"speaker":"横山委員","kind":"質問・要望","question":"６月下旬か７月頭の品川児童学園での保護者の説明の後に掲載するというお話があったのですけれども、ＰＤＦとかそういった形式なのか尋ねました。","respondent":"中山障害者福祉課長","answer":"現在考えていたのは、ＰＤＦファイルでと思っていたのですが、確かに枠をちょっと広げたいところがあったり利用方法は、家庭ごとに違うかもしれませんので、そこは研究をさせていただければと思います。","id":"exchange-011"},{"speaker":"横山委員","kind":"質問・要望","question":"ＰＤＦで配布をする中で様々なご意見をお聞きしていただいて、使いやすいものに進化していってほしいと求めました。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"安藤副委員長","kind":"質問","question":"そうした関係機関への働きかけといいますか、そこら辺で区が重視している、考えていることなどがあればお伺いします。","respondent":"中山障害者福祉課長","answer":"このサポートブックをつくるに当たりましては、区内の療育支援ネットワークの中でもんできた経緯もありますので。そこに対する説明、関係機関への周知、それからその活用をできるだけしていけるような形をお願いしていきたいと考えております。","id":"exchange-013"},{"speaker":"浅野委員","kind":"質問","question":"学齢期ぐらいまでというふうにさっき伺いまして、それ以降についてはどのように考えられているのかをお伺いしたいと思います。福祉課でも利用できるのか、そのような考え方があるのかどうか、他課との連携も含めて可能性について教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"成人期シートをどうしようかと考えたときに、ご本人のための支援につなげていきたいということで、今考えているところです。この支援というのは学齢期で終わりということではもちろんなく、そこから社会生活につなげていくための支援のブックになってきますので。","id":"exchange-014"}]},{"id":"topic-03","title":"「グロー障害者相談支援センター」の開設","agenda":"「グロー障害者相談支援センター」の開設","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３カ所目の相談支援センターができるということですけれども、どういう資格の人が何人ぐらい配置になるのかということを教えてください。楓ハイツ３階ということですが、普通の事務所ビルみたいなところの３階というところになるのか、そのところもの説明を求めました。","respondent":"中山障害者福祉課長","answer":"こちらの「グロー障害者相談支援センター」は、現在まだ指定特定相談が始まっていないので、今は２名体制なのですが、これから３名体制になります。今現在どれぐらいの相談支援の人数がいるかということですが、福栄会と会館それぞれ６人ずつ職員がいる状況になります。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それぞれ６人の体制と、区での２人の体制ということなのですけれども、何人くらいのケアプランが立てられているのか。障害者の場合、必要な人にはすべてケアプランが立てられるという状況になっているのか、その点についての説明を求めました。","respondent":"中山障害者福祉課長","answer":"身体と知的で平成２９年３月１日現在で７７２件、精神が２６５件ということで、合わせて１,０３７件になっております。区で進めている関係がありまして、こちらがまだ１００％にとても届かないような状況であるところになります。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"子どものケアプランがこれからももっと充実をさせていくというのが課題としてある。では、この「グロー相談支援センター」は、そういうところも受け持つことにより充実をされていくということになるのか尋ねました。","respondent":"中山障害者福祉課長","answer":"子どものケアプランにつきましては、平成２９年度、３０年度は区の障害者福祉課で立てる予定になっております。それとも児から者へつなぐことを考えて、こうした３つの相談支援センターでも持つようにしたほうがいいのか、相談支援事業所とも検討しています。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ということは、「グロー障害者相談支援センター」というのは、今まで福栄会と身障者会館でやっていたのを、さらに３カ所で分担して、より充実をさせていくという形での相談支援センターということでいいのかということだけ、最後にお願いしますとの意見を述べました。","respondent":"中山障害者福祉課長","answer":"そのとおりです。は大人の部分のケアプランを３拠点に分けて、しっかりとつくっていきたいと考えているところです。","id":"exchange-018"},{"speaker":"たけうち委員","kind":"質問","question":"２番の事業内容のところの米印に、いわゆるショートステイみたいな宿泊可のイメージなのか、まずそこの説明を求めました。","respondent":"中山障害者福祉課長","answer":"こちらの緊急時の受け入れというのは、委員ご指摘のとおり、ショートステイを想定しています。ただ、ほかの福栄会と会館にある生活・相談支援センターと連携しながら、区内のショートステイの活用をしていくようなイメージです。","id":"exchange-019"},{"speaker":"たけうち委員","kind":"意見","question":"ここで相談を受けて、様々なあいている場所を見つけてくれて、調整するということですね。わかりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"}]},{"id":"topic-04","title":"乳がん検診実施機関の拡大","agenda":"乳がん検診実施機関の拡大","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから、４カ所新たに増やすことで、どれくらいキャパが増えるのかというのがわかったら教えてほしいと求めました。平成２７年度は２５％ということで、平成２８年度はさらに増えているという状況があるのか、そこら辺もわかったらの説明を求めました。","respondent":"川島健康課長","answer":"国は５０％と言っておりますが、少しでも高い検診の受診率を目指して、毎回様々な取り組みをしているです。実数は今、資料を持ちあわせてございません。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"平成２８年度がどれぐらいかというのがわかったら教えてください。さらに増えているのか尋ねました。","respondent":"川島健康課長","answer":"そうです。まだ３月分の集計ができていないので、正確な数字というのはお答えはできないのですが、伸びが予想されると見込んです。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その結果がどうだったかというところのデータは、区としてはどうされているのか、わかったらの説明を求めました。","respondent":"川島健康課長","answer":"精密検査を受けた方の情報につきましては、区に情報を提供していただくようにドクターにお願いをしまして、情報を収集しておりまして、アフターフォローといった部分もデータを積み上げているところです。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その中で、乳がんがこの検診によってわかったとかということが、これだけあるという件数があると、また説得力があって、さらに検診に向かうという部分があるのかなと思うのですけれども、そこら辺がわかったらの説明を求めました。","respondent":"川島健康課長","answer":"がんの発見数というところになるかと思いますが、平成２６年度から順に申しまして、２６年度が５１人、２７年度が５７人、２８年度は１月末現在ですが、２６人の方のがんが発見されていると把握しています。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"改めて、検診でこれだけがんが発見されてというところからすると、さらに受診率が向上されれば、もっと早期発見、早期治療で、人生にとっても大きなマイナスにならなくて済むというところにもつながるかと思いますので、引き続きよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"たけうち委員","kind":"質問","question":"裏面の医療機関のところで、みなと健診クリニックというのが港区にありますけれども、港南なので比較的近いところだと思うのですが、こういう品川区ではないところでも、場合によっては例えば大田区や目黒区などでも。","respondent":"川島健康課長","answer":"利便性も考えて、そういう場合には、乳がん検診に関しては検討の余地はあるのではないかと考えています。","id":"exchange-026"},{"speaker":"たけうち委員","kind":"意見","question":"４つ増やしていただいて、もしそういう必要性があれば、ぜひ区を越えてでもお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"}]},{"id":"topic-05","title":"胃がんリスク検診の判定基準の変更","agenda":"胃がんリスク検診の判定基準の変更","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"この中で、過去感染の方、かかっていたけれども除菌したという方は、除菌しておりますので問題があるのでしょうか。その方にもまた内視鏡を受けなさいという案内が行くのか尋ねました。","respondent":"川島健康課長","answer":"ドクターのほうも十分にその辺の聞き取りができずに、もしかすると過去に除菌した方が、このままリスク検診を受けてという形になっている方がいるのではないかということも推測されているです。","id":"exchange-028"},{"speaker":"たけうち委員","kind":"質問","question":"１回やっていれば受ける必要はないのだけれども、忘れて受けたと。私自身が除菌したものですから、区の検査で５０歳のときにやったので除菌したのですが、そこはどうなのか尋ねました。","respondent":"川島健康課長","answer":"５０代ということだと、大体８割ぐらいの方が感染していると言われているのですけれども、定期的に胃がんの内視鏡検査を受けることを推奨されるというカテゴリーに入るです。","id":"exchange-029"},{"speaker":"浅野委員","kind":"質問","question":"内視鏡の検査もしましたけれども、該当するかどうかは秋ぐらいにわかるということですので、その結果を見て判断したいと思います。そこら辺を含めて、考え方の説明を求めました。","respondent":"川島健康課長","answer":"今ご説明しました数値に当たる方ということになりますと、内視鏡の検査を受けた場合、多分５,０００円から１万５,０００円ぐらいの間の本人負担になるだろうと一般的には言われているところです。","id":"exchange-030"}]},{"id":"topic-06","title":"一般不妊治療医療費助成制度の変更","agenda":"一般不妊治療医療費助成制度の変更","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"不妊治療には非常に高額な費用がかかると思うのですけれども、品川区は１人当たり年間１０万円が限度ということだと思うのですが、大体１人平均で、不妊治療に幾らぐらいかかっているのかを教えてほしいと求めました。","respondent":"川島健康課長","answer":"法律婚されている方で、１組の助成額となります。少しずつですが、助成単価も上がってきているところです。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その辺のところで、区が不妊治療におおよそどれぐらい費用がかかるのかということを把握されていたらお聞かせほしいと求めました。","respondent":"川島健康課長","answer":"先ほど、私は５万円と言いましたけれども、１０万円を上限に助成となります。これは国の定めたものを都道府県が実施しているのですけれども、それに上乗せをして助成しているところが１０区というところになっております。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、品川区が行っている一般不妊治療の保険のきかない本人の自己負担というのは、おおよそ年間２０万円くらいで済むということでいいのか尋ねました。","respondent":"川島健康課長","answer":"一応、自己負担の半分ということで、助成しているのが例えば５万円ぐらいですので、それを倍すれば、１０万円ぐらいを本人が負担されているのだろうなとは推測しています。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"すみません。おおよそ足りてしまうという考え方で、品川区の制度か東京都かということで、上乗せをする必要はないという考え方ということか尋ねました。","respondent":"川島健康課長","answer":"それから、今後例えば予算額がまた増やされていくのかとかということも含めて、区の制度のあり方も考えていく必要があるのかなとご説明させていただいたところです。","id":"exchange-034"},{"speaker":"安藤副委員長","kind":"質問","question":"妻の年齢が４３歳までにということなのですが、４３歳以上の方も結構いると思うし、そうした方々への支援というのはどのようになっているのかお伺いします。","respondent":"川島健康課長","answer":"国が特定不妊治療の年齢制限を設けたタイミングで同じような考え方で、３５歳までが多分、その年齢を上限にしております。様々な考え方、様々な需要もあると思いますので、その辺も慎重に検討していかなければならないと認識しています。","id":"exchange-035"},{"speaker":"安藤副委員長","kind":"質問","question":"こういった年齢要件が設けられたということなのですけれども、そういった年齢要件で、妻の年齢が４３歳以上の方々からの相談とか、受けたいのですけれどもという問い合わせですとか、そういった状況がわかれば、あるのかないのか、どういった実態なのか。","respondent":"川島健康課長","answer":"現実に何件かそういったご相談というのはあるのですけれども、実際問題、国の制度の入り口部分を担うところというところもありますので、こちらは年齢制限というのを設けさせていただいたという考え方は、変わるというところではございません。","id":"exchange-036"}]},{"id":"topic-07","title":"予防接種の接種方法に誤りがあったことへの対応","agenda":"予防接種の接種方法に誤りがあったことへの対応","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのような方に対して、５年以前のものはクリニックにはないのか、そこら辺の可能性はないのでしょうかということをお聞かせほしいと求めました。","respondent":"舟木保健予防課長","answer":"なので、ホームページ等には、保健予防課と３保健センターという形で問い合わせ窓口を周知する予定です。最後の３つ目の自己負担についてですが、今回のことに伴う再接種費用につきましては、定期・任意とも無料で実施する方向です。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成２４年３月以前のものというのは、クリニックにはカルテは残っていないということで、情報として得られないということなのでしょうか。これは、その点については、何とか法違反みたいなものにはならないのかについてもお聞かせほしいと求めました。","respondent":"舟木保健予防課長","answer":"カルテの保存年限が最初の記載から５年間となっているので、今回の確認作業ではそこまではしておりません。それから、登録削除以外に何か違反とかにはなるのかということですが、特に医療法とか薬事法とか、そういうものの違反にはならないと聞いております。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"５年間だけを調査したということですけれども、５年間保存というのは法律で決められているので必ずありますけれども、その考え方はいかがか尋ねました。","respondent":"舟木保健予防課長","answer":"そういう意味では、区に請求があってということで、こちらが把握できる５年間を調査して、その方に対して通知するという形で今回はいたしました。なので、そのほかのお申し出については、きちんと確認した上で、丁寧に対応させていただきたいと思います。","id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"このクリニックにかかられた方がきちんと気づけるようなＰＲというのも含めて、そしてまた不安のないような対応というところを、しっかりお願いしておきたいと思いますとの意見を述べました。","respondent":"舟木保健予防課長","answer":"先ほどの質問で１点、名簿を削除しただけで診療は続けているのかというご質問にお答えするのを忘れましたので、お答えいたします。ただ、閉院して、問い合わせ等がきちんとその後も継続してできるように、こちらからは確認先とかについては提出を求めているところです。","id":"exchange-040"},{"speaker":"たけうち委員","kind":"質問・要望","question":"そういうところに委託し、接種方法に誤りがあったというおわびも当然あると思うので、どんな感じのニュアンスでプレスを発表するか尋ねました。","respondent":"舟木保健予防課長","answer":"一緒に協力して対応するということで、今後の対応については協力していただきたいということを、改めて申し入れをしているところです。希望者には再接種という形での対応ということで、そういうことを含めて検討した上で、このような対応となっております。","id":"exchange-041"},{"speaker":"たけうち委員","kind":"質問","question":"１回でいいと言われているのにもう一回打ってしまって、何か副作用があると心配なので、そこだけ大丈夫だということを教えてほしいと求めました。その辺はどうなのか尋ねました。","respondent":"舟木保健予防課長","answer":"今後費用請求などを考えていくのかということですが、取り急ぎの対応として、またその対応ということでやらせていただいています。費用的な面については、今後改めて専門家を交えて検討していくこととなっております。","id":"exchange-042"},{"speaker":"松永委員","kind":"質問・要望","question":"私からは幾つかなのですが、いつごろからまぜてワクチンを打たれたのかというのを聞きたいなというのがあります。先ほども効果があるかないかというお話だったのですけれども、悪影響はないのか、ちょっと不安だったのでお聞かせほしいと求めました。","respondent":"舟木保健予防課長","answer":"医師からの聴取によりますと、開院したときからという話でしたので、平成２１年４月からとこちらは考えております。きちんとついているとも言えない状況なので、様々予防接種事故調査委員会の中で議論した結果、このような対応となっております。","id":"exchange-043"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"できるはずの抗体ができないというだけにとどまるのか、わからないということなのか、そこら辺をもう少しご答弁いただきたいというのが１点です。そういった保育課などの所管との連携や情報共有などはどのようになっているのか尋ねました。","respondent":"舟木保健予防課長","answer":"希望者の方には抗体検査を実施するという中で検証するとともに専門の先生方と検討しながら判断してまいりたいと思います。子ども部門との連携ですが、周知等にご協力いただければということで、今後していく予定です。","id":"exchange-044"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"これは要望したいのですが、いかがでしょうか。そういった形で最大限努力をしていただきたいのですけれども、いかがか尋ねました。","respondent":"舟木保健予防課長","answer":"見落としがないよう、かなり目立つような形でお送りしていますので、お送りされた方の見忘れということはないのではないかなと考えています。教育部門とも連携して、周知についてはこちらから情報提供して、どのようにしたらいいのか相談しながらやっていきたいと思います。","id":"exchange-045"},{"speaker":"安藤副委員長","kind":"質問","question":"５月末を過ぎて、そうした連絡が来る方もいると思うのですが、そちらの希望申請というのは当然受け付けるということでよろしいのでしょうか。ぜひそうしてほしいのですが、いかがか尋ねました。","respondent":"舟木保健予防課長","answer":"確かに５月３０日までに出してくださいという形で書かせていただいておりますが、その後もこちらで調整して、もちろん重々承知しています。ここにもできる限り可能な範囲で対応させていただきたいと思います。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/999880?Template=document&Id=3476#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":39620,"voices":136}},{"id":"h29-20170515-8","meetingId":"h29-cm05","date":"2017年5月15日","dateIso":"2017-05-15","committee":"建設委員会","time":"午後 １時００分～午後 ２時４６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"平成２９年６月区民住宅（空き室）入居予定者登録募集","agenda":"平成２９年６月区民住宅（空き室）入居予定者登録募集","exchanges":[{"speaker":"西本委員","kind":"質問","question":"区民住宅の現在の空き状況がどうなっているのかと、いずれ、区民住宅というのは変わっていくと思うのですけれども、それの告知というものはどういう方法を行って、理解をしていただきながらお申し込みをしていただくことになると思うのですが。","respondent":"長尾住宅課長","answer":"あっ旋を受けられる予定の方にはお知らせをしまして、その後、空き室が出た段階で皆様に入居審査のための資料をご提出いただきます。それで入居審査を行いまして、審査を通過した方から順番に入居のご案内をしているところです。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"いずれは区民住宅がなくなってくるわけではないですか。それをどう説明されているのかということです。","respondent":"長尾住宅課長","answer":"アイルサイドテラスが２３戸、ロビン成田が１戸、ファミーユ大井が３戸となっております。登録募集のしおりの中で各住宅につきまして返還予定時期を記載しており、その中で周知を図っております。","id":"exchange-002"},{"speaker":"西本委員","kind":"意見","question":"でも、まだ決まっていないという形になると、かなり不安になると思うのです。そこはどう対処しますかとの意見を述べました。","respondent":"長尾住宅課長","answer":"そのうちアイルサイドテラスに関しては第１所得区分の部分で減免が残っておりまして、第１、第２所得区分に関して減免の制度が今は残っております。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"ですので、申込みされている方が、そういうのを知った上で、納得した形で借りていただきたいのです。そこは工夫して、細かく対応してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]},{"id":"topic-02","title":"中延二丁目旧同潤会地区防災街区整備事業に伴う建設工事","agenda":"中延二丁目旧同潤会地区防災街区整備事業に伴う建設工事","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"先日も、やはりまだまだ住民の皆さんからは要望があるなと感じているので、そこを何点か伺いたいと思うのです。ですので、こういったところをどのように感じられているのかを伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"委員ご指摘のありました工事説明会についてなのですが、５３名の出席のもと開催されたと、区でも報告を受けております。組合が実施する説明会とはいえども、説明会の開催に際しましては、こちらは区としても非常に残念に思っているところです。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういうことを要望すると、誰がどう結ぶのかわからない、こういった回答が返ってくる。もっと水の量を増やしてほしいという声も出ているのですけれども、振動、一緒に住民の声を受けとめるという立場で進めていく考えはあるのか尋ねました。","respondent":"高梨木密整備推進課長","answer":"説明会の中で、どうしても影響がある１列目のみの実施というところで説明があったということで、私どもも聞いております。５列目の方々までは、どうしても家屋調査というのは難しいという説明が組合からあったということも把握しております。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私の自宅の近くに大きなマンションができるということで説明を受けたときも、要望に応じて対応してくれる業者もありました。そういった柔軟な対応をしていただけたらと思うのですけれども、事業者、組合は柔軟な対応をしていただけるのかどうかを伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"この事業は、先ほどご説明させていただきましたとおり、事業組合が事業者として進めている事業でございまして、区が実施する事業ではございません。区といたしましても、そのような声があるということを事業組合に伝え、住民としっかり話をするように申し伝えたいと思います。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"解体にあたって、アスベストをこういうふうに対策して取り壊したという説明がなかったそうなので、どうやったのかを伺いたいと思うのです。ですので、そういったアスベストの関係での解体がどのように進んだのかを伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"解体工事を行う前に、全８６棟中、アスベストが建材に含有されている家屋が７７棟だったという報告を受けております。それは当然、法令で定められている防護レベル以上のものを施してやったという報告は受けておるところです。","id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"先ほども、区も言っていますけれども、やはり応えられるものには真摯に対応していただきたいと思うのです。引き続きやっていただきたいですし、そして入っていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問・要望","question":"組合側、もちろん指導はしていただくということはあると思うのですけれども、その辺の原因をもう少し詳しくご説明してほしいと求めました。それでこういう結果になってしまったという。","respondent":"高梨木密整備推進課長","answer":"説明の仕方であるとか、施工業者、それと今ご紹介のありました設計会社にも事前のリハーサル等で申し伝えていたところです。このようなことが二度とないように、順調に事業が進むように働きかけをしてまいりたいと、このように考えております。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういうことは大変よろしくないと思うのです、今後、何年もかけて建築していくわけですので。ここの段階でしっかりと事業者側に改めていただいて、できることは対応してほしいと求めましたので、その点はよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"確認","question":"基本的なことの確認になるのですけれども、建設工事の発注は整備事業組合になるのですが、この総額と企業負担はどうなっていたのですか。その辺の基本的な事項を確認させてください。","respondent":"高梨木密整備推進課長","answer":"そのうち、国と区から拠出されます補助金が約２４億円となっております。なお、その２４億円のうち、区の負担は約６億円です。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"戸数が１９５戸で、控え損なってしまったのだけれども、建設によってできたものは所有権になるのか。そこら辺をもう一回、の説明を求めました。","respondent":"高梨木密整備推進課長","answer":"従前お住まいになられていたり、土地、建物を所有されていた方々がそちらに権利を変換してお住まいになるのが、１９５戸のうち７２戸です。残りの１２３戸につきましては、売却し、その金額を事業費に充てていく、そのようなことで報告を受けております。","id":"exchange-013"}]},{"id":"topic-03","title":"がけ・擁壁安全化支援事業の実施","agenda":"がけ・擁壁安全化支援事業の実施","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"この助成金は、区の独自のものでしょうか。目標は何かあるのかを伺いたいと思います。","respondent":"鈴木建築課長","answer":"崩落の事故が発生した擁壁は大谷石がほとんどでございまして、まず大谷石で道路沿いに面している所、それが２１０カ所程度あります。それから、先ほどご説明した４３カ所程度、急傾斜地崩壊危険箇所、まずはこれらの安全化に向けて事業を進めてまいりたいというものです。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、助成の内訳、国費も入るということですけれども、区の負担としてはどうなるのかを伺いたい。その母数、これだけあって、これだけ進めたいというものを伺えたらと思うのですけれども、そういうものはあるのかどうか伺いたいと思います。","respondent":"鈴木建築課長","answer":"最終的な整理をしておりまして、これから近々、すぐに郵送等でお知らせをしていく予定です。先ほど道路沿いの大谷石は２１０カ所程度というご説明を差し上げましたが、目視の状態では比較的状態がいいという調査結果が出ているものもあります。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"支援１のアドバイザーの派遣のところでは、そうやって直接訪問なりお知らせをして、こちらからそういう投げかけなどはするのでしょうか。それとも、こちらから積極的にアドバイスを受けたほうがいいと働きかけるのか、その辺の強弱を教えていただきたいのです。","respondent":"鈴木建築課長","answer":"その４３カ所の個々の状態を見て、所有者のところに行って、事業説明あるいはアドバイザーの派遣等について働きかけを行っていきたいです。そういった方に、電話あるいは窓口で直接的にご紹介をして、ご利用いただくことを考えてあります。","id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"大谷石が風化して、いずれ危険なことに陥るということで、それはＲＣの擁壁にしなければいけないということで私も認識しています。今現在やられたのか、これからそういった周知をしていくのか、それをお知らせほしいと求めました。","respondent":"鈴木建築課長","answer":"一昨年から２カ年をかけて調査してまいりましたが、こういった調査が入ると、コンサルの職員が地域を回るというご説明はしてまいりました。その前に、調査結果の概略になりますけれども、町会に説明をしていきたいと考えています。","id":"exchange-017"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それとあと、この分布図、マップなのですけれども、ちょっとこれは見にくいのですが、これはこれからホームページでアップするのか。もっと見やすくこれからアップしていくのかどうか、お知らせほしいと求めました。","respondent":"鈴木建築課長","answer":"こちらの資料３－２の分布図のホームページ上へのアップですが、基本的には今この形で、ホームページ上でアップを考えてあります。そういったところに安全性の低いものがあるというところを認識していただいて、その方が必要な情報をお伝えできる範囲でお伝えしていきたいです。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問","question":"相手はＪＲですけれども、この辺は区としてどう考えていったらいいのかがちょっと気になった。何か考え方があったらの説明を求めました。","respondent":"中村都市計画課長","answer":"このＪＲのほうは、都市計画課でもかねてから危険性についてはお知らせをしておりまして、ＪＲも十分認識をしています。いずれにしましても、注視をしながら安全性を確保していく、そういう考えです。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"意見","question":"かなりそういう話が出てくるのではないかというのは、自分も見た瞬間に色がつながっていると、気になっていたもので。普段からあの辺の道はどうにかならないかというのはよく言われている話なので、安全性を守っていくために、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"西本委員","kind":"意見","question":"ですので、そこの交通整理というのをどうしていくのか。は、どうも助成金があるようだからそれを使ってやりませんかみたいな話も当然出ると思うのですけれども、その辺の調整はどう考えていますかとの意見を述べました。","respondent":"鈴木建築課長","answer":"このがけ・擁壁の説明も、集まっていただいて、こういう事業を行っていくと説明もしました。その際、そういったところもしっかり載せて、最終的には事業者のご協力もいただきながら事業を進めていくことを考えてあります。","id":"exchange-021"},{"speaker":"西本委員","kind":"意見","question":"いろいろ考えている方もいらっしゃると思うし、区内業者、区外もあるかもしれませんけれども、いい関係をつくりながら、悪用されないような状況との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"今までの質疑の中で聞き漏らしたかもしれないのですけれども、がけ・擁壁の安全性に関する分布図に出ているところで、急傾斜地崩壊危険度の対象にもなっている、その中の範囲ということだと思うのですが、急傾斜地の崩壊危険箇所の中で。","respondent":"鈴木建築課長","answer":"４３カ所の中に、ついていないところは１９カ所あります。","id":"exchange-023"},{"speaker":"塚本委員","kind":"意見","question":"そういうのは、どういう考え方なのか、ちょっと説明していただけますかとの意見を述べました。","respondent":"鈴木建築課長","answer":"したがって、その４３カ所が指定されてから、擁壁がやりかえられたところもあります。何度かこの場でもご説明しましたけれども、４３カ所にプラスアルファをして、この事業も将来的に見直しを行っていくことになろうかと考えています。","id":"exchange-024"},{"speaker":"塚本委員","kind":"質問","question":"それと、この工事費の助成額について、急傾斜地が３分の１で上限５００万円。赤や緑がついているところで、大体、この上限５００万円の１,５００万円ぐらいで対応できそうだというところは見ていらっしゃるのか尋ねました。","respondent":"鈴木建築課長","answer":"４３カ所、現地を回って、どれだけこの３分の１の助成でできるかという詳細は把握してございません。一定程度、一般的な積算と、あとシミュレーションで出した金額です。","id":"exchange-025"},{"speaker":"塚本委員","kind":"質問・要望","question":"この助成以外にも、何かいろいろなところでそういう支援とかは、どんなことが考えられるのか。もしあれば、お聞かせほしいと求めました。","respondent":"鈴木建築課長","answer":"そういったソフト的な助成もいろいろ検討はしましたけれども、まず事業のスタートとして、こういったメニューを出して進めていきたいところです。今後、直接的にいろいろな声を聞きながら、その後の検討策は考えていきたいと、事業の進捗を見ながら考えていきたいです。","id":"exchange-026"}]},{"id":"topic-04","title":"コンクリートブロック塀の安全点検","agenda":"コンクリートブロック塀の安全点検","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"今、この点検をした上で、いろいろ危険だとなったときに、助成制度等のご案内をされるということです。助成制度にはどういうものがメニューとしてあるのかの説明を求めました。","respondent":"鈴木建築課長、高梨木密整備推進課長","answer":"直接的に、冠にブロック塀とつけての助成制度はございませんが、公園課で行っております防災緑化助成、こちらの塀の除却の助成です。木密整備推進課で行っています不燃化特区の支援制度の中でも、家屋の除却に伴う塀等の工作物も一緒に除却の助成が出るというメニューがあります。","id":"exchange-027"},{"speaker":"塚本委員","kind":"質問","question":"こういう基準に沿ったブロック塀を新たにつくると、これはもう、例えば震度７でも大丈夫みたいな、そういう感じになるものなのですか。防災上、どちらが望ましいかみたいなことがあるのかどうか、そこをお伺いしたいと思います。","respondent":"溝口公園課長、鈴木建築課長","answer":"それに伴うフェンスの設置、ただブロック塀を撤去するだけではなく、その後緑化をしていく。通常のブロック塀の撤去よりも、より重点的に助成額を上げて、整備をやっている事業です。景観、総合的に考えて、こちらがいいということは間違いないところです。いろいろな考え方、いろいろご説明しながら、お使いいただけるものを使っていただければと考えております。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問","question":"なかなか進みづらいものなのか、結構皆さんもう問題意識を持たれているのか。持たれていないから、こういった安全点検で、自分で知りましょうとなっているのかとも思うのですけれども、件数を伺いたいと思います。","respondent":"鈴木建築課長、溝口公園課長","answer":"この基準に合致していない場合は、ブロック塀も安全な、この基準に合うようなものに必ずやりかえなければいけないとなっています。私どもが助成しております防災緑化、また生垣助成、そういったところの実績の件数でいきますと、平成２８年度で４件の助成を行っているものです。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"意見","question":"自分自身で知るというのはすごく大事だと思うのですけれども、この点検シート、ブロック塀をお持ちのお宅に配っていくのがいいのではないかと思うのですが、この周知方法はどのようになりますかとの意見を述べました。","respondent":"鈴木建築課長","answer":"先ほど冒頭でちょっとご説明しましたように、ホームページあるいは窓口での周知は行っていきます。これ専用に個別に調査をかけて配るということは今のところ考えてございませんが、あるいは、今年度から耐震のほうでは戸別訪問を実施してまいります。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"どういうアクションをしてほしいのか、なぜそれが危ないのか、だからチェックしてと。この表現の仕方をちょっと考え直していただきたいのですけれども、いかがか尋ねました。","respondent":"鈴木建築課長","answer":"この項目をつくるバージョンもちょっと検討したのですけれども、つけながら、これをまずスタートさせていただきたいところなのです。助成の説明がこの資料から抜けているところもありますので、総合的な、その辺の工夫はこれからまたしていきたいと考えています。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろやりながら、いろいろご意見をいただけると思うので、ぜひ、ちょっと考えていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"目視レベルで、品川区としては、ちょっと危ないというブロック塀の全体の把握している数というのは大体どのくらいになるのか尋ねました。","respondent":"鈴木建築課長","answer":"全体的な区内のブロック塀の数については、把握してございません。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"それは、あまりにも数が多いとか、そういった理由なのか尋ねました。","respondent":"溝口公園課長","answer":"大体５万３,５００ｍぐらいのブロック塀があると、緑化可能な、道路に面しているところの延長です。民地と民地の間にあったブロック塀とか、私どもで助成をしていく中で、どのぐらいあるかというところの延長というのはつかんでいるものです。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"２点目なのですけれども、今、他の委員の方からもご質問があったのですが、ブロック塀安全点検シート。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]},{"id":"topic-05","title":"「都市鉱山からつくる！みんなのメダルプロジェクト」への参加","agenda":"「都市鉱山からつくる！みんなのメダルプロジェクト」への参加","exchanges":[{"speaker":"西本委員","kind":"質問","question":"携帯電話等なのですけれども、個人情報の処理はどうするのですか。そういう所に出すときには自分でやってというのが基本なのでしょうけれども、そうとも限らない場合があるので、その対処はどうされるのか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"しかし、全てが全てそういった形でやっているわけではございませんが、認定事業者に渡しまして物理的な破壊、解体等をいたします。その物理的な破壊をもって情報は全く出なくなる、削除される仕組みになっております。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"依頼する業者も、そういう守秘義務であったり、信頼がある方とは十分に存じておりますが、ただ、何があるかわからないところがあるので、そこの契約上で何か交わしたりとかはあるのか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"契約上ですけれども、当然、業者とは、個人情報の取扱いについて、厳重に、確実に、物理的破壊をもってという形で契約を結んでおります。そちらの契約事項を守るということで、国から認定を受けているものですので、そういった意味では二重の間違いのない処理がされているです。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"区民の皆様方には、自分でデータを消去してくださいというのが基本だと思うのですけれども、それはどういうところで周知するような方法をとっているのか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"こちらは、私どもで人的配置をしておりまして、回収ボックスに入れても、持ち去りとかといったことができないような仕組みを構築しております。そういった意味では、万全の体制で、持ち去り防止や個人情報の保護という部分を図っておるところです。","id":"exchange-038"},{"speaker":"西本委員","kind":"意見","question":"どういうホームページなのかわからないのですけれども、目立つような形にして、自己責任というところを含めて強調してもらいたいと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問","question":"区に持ってきて、データを何とか消去したいのだけれどもと言ってこられた場合は、対処しようがあるのですか。それとも、携帯屋に行って、削除の作業をしてもらって、持ってくる形になるのか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"携帯電話につきましては、基本的な考え方といたしましては、自己責任、自己処理ですので、ご自分でやっていただく。そうでない場合には、携帯ショップ等に行ってやっていただくという部分をご案内するです。","id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問","question":"小型家電は、主に携帯電話とかデジタルカメラだけなのですか。小型家電と言われても、細かく言うと、携帯電話、デジタルカメラというのは浮かんでくるのですけれども、ほかにはどんなものがあるのか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"１０cm×２５cmのもの、ボックスに入るものということでお願いしておりまして、ボックスに入らないものは対象外となっています。基本的には、ボックスの中に入る電気機器につきましては小型家電と言ってあります。","id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"質問","question":"もう回収を始めているということなのですけれども、結構、入るものでしょうか。まだ周知がされていない状況かもしれないのですけれども、もう何点かは入っている状況か尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"ガラケーは１２０ｇぐらいということで、重量に差異はあるのですが、およそ１,１００個ぐらい１年間で回収されている実績があります。ただ、今回のこの取組みで、さらにこれが加速されるのではないかというのが私どもの考えです。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/594236?Template=document&Id=4200#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":30013,"voices":107}},{"id":"h29-20170515-9","meetingId":"h29-cm05","date":"2017年5月15日","dateIso":"2017-05-15","committee":"文教委員会","time":"午後 １時００分～午後 ４時５０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を78件整理しています。","topics":[{"id":"topic-01","title":"品川区ライフスタイルに関するアンケート調査","agenda":"品川区ライフスタイルに関するアンケート調査","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"統合失調症とか、身体的な病気だとか、妊娠中を選択した云々は除外したと書いてあります。ということは、この除外された人たちは一般群のほうへ入っているのか尋ねました。","respondent":"高山子ども育成課長","answer":"こうした除外のものに該当した方に関しましては、その下のひきこもり親和群などに該当するケースもあるかと思いますので、一般群とひきこもり親和群いずれかに入ってくる可能性があるというふうに考えてあります。","id":"exchange-001"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これは何かちょっと分類でおかしくなってしまうのではないかという気もするのですけれども。このひきこもり傾向群の同居人数でひとり暮らしが９人ということで、この人たちは、ひきこもりなのだけれども一人で暮らしているということか尋ねました。","respondent":"高山子ども育成課長","answer":"別の施策において対応していくということも従前から言われておりますので、我々としても統一のルールとして採用させていただいたものです。","id":"exchange-002"},{"speaker":"鈴木（博）委員","kind":"質問","question":"もう１つは、ひきこもりは家の中にこもっているということだと思うから、もともとひとり暮らしでひきこもりというのはあり得るのですか。その辺が単純な疑問なのですけれども。","respondent":"高山子ども育成課長","answer":"少なくともそうした蓋然性のある方々を除いた方々が一般群として残されているということになろうかと思います。大きくは、そういう意味では、いわゆる６カ月以上継続的に外出をしていないということを１つの要件としてやっているものですので。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"２人とか、３人とか、どう見られているのか伺いたいと思います。そして、今回の、まだこれから分析すると思うのですけれども、今の段階で見えてきた課題について教えてほしいと求めました。","respondent":"高山子ども育成課長","answer":"東京都調査と比較をしたいという意図から、施策においては、やはりそういった方々への支援も考えてまいりたいというふうに考えております。１,５００人規模の調査ですので、分析をしていくに当たっては、その中身については分析してまいりたいというふうに考えております。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"傾向群として一緒にした理由ですけれども、大きな傾向をつかむためというお話でしたが、個別の分析もされていくという認識でよろしいのでしょうか。なかなか地域別で見ると偏りが出てしまうというか、しっかり把握できないという認識だということでいいのか、それは確認です。","respondent":"高山子ども育成課長","answer":"やはり施策を考えていく、考えやすくなるということもありますので、現在のところは個別の部分で分析をする考えはございません。そういった地域性にも着目できればというふうに考えておりますが、いずれにしましても、その点も含めて検討させていただきたいと思います。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ進めていっていただきたいと思うのですけれども、そういった方にいきなり就職しろというような形をとっても、やはり届かないと思うのです。社会との関係を持っていく、そういった取り組みも大切だと思うのですけれども、いかがか尋ねました。","respondent":"高山子ども育成課長","answer":"調査方法を検討するに当たっては非常に苦慮しまして、多少少ないとお感じかもしれませんが、３６項目に絞り込んで調査を実施したものです。お答えいただいた回答の中から、より品川区の若者の実態に迫れるような、そんな分析をこれから進めていきたいと考えております。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"そう感じないように、今後もし２回目のアンケートがある場合、答えたいと思うような設問にしていってほしいと求めました。その１歩目からしっかりと支援していく、そういった場をつくることや、支援もぜひ検討していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"しっかりとした調査をして、区の支援体制を整えてほしいということを要望してまいりましたので、まず一歩進んできたのかなと受けとめております。","respondent":"高山子ども育成課長","answer":"訪問なども１つの手法だと考えられますので、そういったものを採用するかどうかについては、またその時点で考えてまいりたいと考えています。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"今後、まさしくより実態に迫る調査の中で、訪問というものも本当に必要かと思いますので、そこも進めてほしいと求めました。かわりに親が答えたとか、このアンケートの中で出てきているのか、教えてほしいと求めました。","respondent":"高山子ども育成課長","answer":"今回、親御さんがご自分で回答してもいいのかというようなお尋ねでありますとか、ホームページ等に区できちんと実施している調査ですといったことも。基本的には選択式の回答ですので、現在のところ、今回の調査においては把握できていないといったところです。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"何人ぐらいいらっしゃるのかが、なかなか把握が難しいところで、今回の調査だけではなかなか推計値は出しにくいのかなというふうに思います。","respondent":"高山子ども育成課長","answer":"今回は計画策定に向けての資料集めです。１つには、計画については多角的な検討ができればというふうに考えているところですので、より実像に迫ってまいりたいと考えています。","id":"exchange-010"},{"speaker":"あべ委員","kind":"意見","question":"これは今後の計画策定とセットだと思うのですけれども、ぜひ受け皿を充実させていくことと、それから把握することを並行して進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"専門的な方が入るのか、いろいろな部署にかかわる問題が出てくると思うのですが、分析をどこでやられるのかということを教えてほしいのが２点目です。相談場所の紹介とか、そういうものが入っていたのかどうか、その辺もの説明を求めました。","respondent":"高山子ども育成課長","answer":"検討期間がありますので、委員長との相談の中でタイミングについては決めてまいりたいと考えております。特にそういった支援等の窓口等をこの調査の中でご紹介するような、そのような流れでは今回は実施しておりませんので、そういう意味では。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一刻も早い具体的な対策が求められているので、その辺が早くしてほしいと思うのですが、いつごろに具体化されていくのかということをお伺いしたい。１５歳から３９歳というと、まずは分析のところを丁寧にやっていただきたいと思うのですが、いかがか尋ねました。","respondent":"高山子ども育成課長","answer":"策定検討中の子ども・若者計画につきましては、現在、鋭意検討作業を進めているところです。それぞれの部署で考えているそれぞれの見立て、そういったものも最終的には本調査の包括的な部分に反映させていければというふうに考えております。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"役所以外のＮＰＯでいろいろ居場所づくりなどに取り組んでいるところの意見もぜひ取り入れてほしいし、ぜひ分析を深めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問","question":"参考調査のところで、４０歳から６４歳の方のアンケートもとられていますけれども、これはどういうふうに利用していくのか伺いたいと思います。","respondent":"高山子ども育成課長","answer":"４０歳以上６４歳以下の男女ということで、今回、あわせて実施したものです。やはり課題の認識として、本調査から分析されたものについては、子ども未来部以外の部門でも共有していければと考えているところです。","id":"exchange-015"}]},{"id":"topic-02","title":"平成２９年４月入園申込状況等","agenda":"平成２９年４月入園申込状況等","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"そちらのほうが受け入れができなかったということもありますが、ここまで増えてしまったのはなぜかという点をもう１度教えてほしいと求めました。","respondent":"大澤待機児童対策担当課長","answer":"これは去年の時点では３枠しかございませんでしたので、単純に１０倍は枠が増えている、あきの枠があったということです。そのあたりも待機児童が増えてしまった要因の１つではないかというふうにも感じております。","id":"exchange-016"},{"speaker":"新妻委員","kind":"質問","question":"マッチングというところも非常に大きいと思うのですけれども、要は、１２月に締め切った段階で、条件の変更はできないですよね。そうすると、例えば、ここはあいているから、こっちの園はどうですかという変更は、個々のそのやりとりはできるということか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"ぎりぎりになって辞退されてしまうと、二次を出す方にもなかなかご案内ができないという部分はありました。２園、３園、保育園が増えたことによって起こり始めているというような状況はあります。","id":"exchange-017"},{"speaker":"新妻委員","kind":"質問","question":"今後、区として、そこの部分を４月の段階で調整を行うようなことは可能なのでしょうか。条件をちょっと変えてといいますか、ここまでの期日だけれども、そういう部分を変えて４月の段階でそこに入れていくことは考えられるのか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"５月の申し込みで対応するしかないような状況ですけれども、どうしようもないという状況だということは認識していますので、その辺は考えていきたいと思っています。","id":"exchange-018"},{"speaker":"新妻委員","kind":"質問・要望","question":"この後、報告いただきますけれども、来年も既に開園が予定されておりますし、荏原地域が多くなるということも出ておりますが、来年こそは待機児童を本当に減らしていく、ゼロに近づけていくという方向で、さまざま今回のことを踏まえて、変えるべきところは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"あべ委員","kind":"質問","question":"この辺の数字になってくると、ちょっとどうなのだろうと思うのですけれども、何かこれは特別な事情や背景があってのことなのでしょうか。何となく１人を受け入れる行政のコスト、ちょっとどうなのかなという気がするのですけれども、どういうお考えなのか尋ねました。","respondent":"佐藤保育課長、大澤待機児童対策担当課長","answer":"保育園の施設の制度上、従前からそういった対応をしていますので、指数が低いということで入園をさせないということはできない状況です。電話等で聞いた範囲のお答えの中では、お答えしていただいていない方もいらっしゃいますが、そのような理由が多いです。","id":"exchange-020"},{"speaker":"あべ委員","kind":"質問","question":"この点のお考えを、これも聞きにくいことなのですけれども、お伺いできればと考えています。違うのか、この２１９人の中に８８人が全て入るとなると、相差の部分が実際に行くところが現在ない方というふうに考えていいのか尋ねました。","respondent":"佐藤保育課長、大澤待機児童対策担当課長","answer":"３点ご質問をいただきました。日中４時間以上の就労が確保されていれば、保育園の入園の継続が可能というふうになっておりますので、そういうというところだと認識しております。結果、辞退されている０歳児の方は、そこだったら育休を延長して１歳になってから入れますというような方も多いようにお話を聞いていて思います。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"区立園も私立園も基準の面積は確保されているということでよいのかということを１つ確認させてほしいと求めました。もし変更した理由があれば伺いたいと思います。","respondent":"佐藤保育課長","answer":"適用に関しては５月からになります。統計上、私立保育園も８時半までやっている園が増えていますので、こちらに関しては今回の審査をもって廃止するというような見直しをしています。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"区立園でも４６点とか、なかなか４０点以上のところが多いという状況で、やはりまだ入りにくい状況が続いているという印象を強く持っております。","respondent":"大澤待機児童対策担当課長","answer":"平成２８年が８３９人で、平成２９年４月が８８５人なので、そんなに劇的に増えるということではないという説明でご理解いただけると助かります。平成３０年度の開設に向けて、今回の理由を分析して、平成３０年度開設に向けていきたいということを考えております。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"入園者の数が増えなかった理由なのですが、今のご説明だとわかりにくかったので、もう少し何か説明があれば伺いたいと思います。目指しているということですので、区立園の増設も含めて、待機児ゼロを実現させるために頑張ってほしいと求めました。","respondent":"大澤待機児童対策担当課長","answer":"なので、毎年８００人ずつ開設していくと、８００人ずつ入れるという意味なので、前年と比べても入園者数は増えないというのが一番単純な説明です。ゼロに向けて、平成３０年以降、頑張ってまいります。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どうして待機児が増えてしまったのかと、転入・転出のそういった人口の変化の見込み自体はどうだったのかという、そういうものが事前にどのくらい捉えられていたのかという大もとのところをまず聞かせてください。","respondent":"大澤待機児童対策担当課長","answer":"乳幼児人口に関しましても新たな数値を置きまして、計画は見直してまいりたいと考えています。現実と乖離しておりますので、こちらも実態に見合った数字に直して計画を見直して、計画に沿って開設してまいりたいというふうには考えております。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"前年度より１歳児が１２０人増えたというのは、これは予想外だったのですか。伺っていてよくわからなかったのが、７６枠あいて、もう１回教えてほしいと求めました。","respondent":"大澤待機児童対策担当課長","answer":"何らかの方策を実施しないと、１歳児がまた増えることになるので、それはこれから検討を進める予定です。今、どういうやり方かは今後検討していきますけれども、何らかの方法でもう少し丁寧に状況を把握していくことは検討してまいる予定です。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"うまくマッチングをさせていただきたいというのと、途中で生まれたり、これから頑張ってほしいと求めました。のだて委員も意見を言いましたけれども、ぜひ民間頼みではなくて、区立の保育園の増設のところもぜひ考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"高橋（し）委員","kind":"意見","question":"別表１で、新年度が始まってしまいましたので、どのような対策をとっておられるのか。４月からの運営に問題ないように、どう体制を整えられたのかとの意見を述べました。","respondent":"佐藤保育課長","answer":"短時間のアルバイト等も、保育課一丸となって面接等を行いまして確保しまして、広さと人員の配置は確保して安全・安心に気をつけてしっかりと行っていくものです。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１点だけ、済みません。地域別とか需要のところを伺ったら、もうどうせ無理だろうと思って諦めている人もいるので、いかがか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"先ほどの年度途中の入園ですとか、これから入れたいという人の需要にこたえるまでには、今すぐということは、この状況では難しいと思いますけれども、今後は、そういう方たちも含めて考えていかなければいけないということは認識しています。","id":"exchange-029"}]},{"id":"topic-03","title":"認可保育園等の新規開設","agenda":"認可保育園等の新規開設","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"ない場合、代替施設がどこなのか伺いたいと思います。承認予定のものはどこになるのかも伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"６番の目黒駅前だけが、ここだけが４００ｍほど離れていて少し遠くなっておりますが、ここが一番近い公園ということです。承認予定の園ですが、キッズガーデン小山とみらいく保育園と、こころしながわふどうまえが５月の予定ということになってあります。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問","question":"既に保育園が増えてきたところでいっぱいになっていますので、そういったところのお考えは、区としてはどう考えていらっしゃるのでしょうか。公園をつくるというのは別の課になると思いますので、そういった課に要請していたりするのか伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"保育園をつくるときに、もちろん園庭があることが望ましいのは私どももそう考えております。事業者によっては開設前の１週間とか、午前中、その辺で何とか工夫して譲り合って使っていただきたいということでお願いしています。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"品川だけで４園、来年の４月に開設。今、保育園の事故が前年より１.５倍に増えているという、どのようなチェックをされて事業者を選ばれているのかをお伺いしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"ちょっと人数が多くなって、園数が多くなっていきますので、園長会のやり方については検討しているところです。区独自の検査を積極的に進めていくということでやっておりますので、事故については厳しく、気をつけて指導してまいりたいと考えております。","id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今日、離職率とか人件費比率も具体的につかんでいる数字をお伺いしたいと思ったのですが、安心材料をどこかで示していただきたい。やはり明らかにしてほしいと思ったのと、ぜひそういうことも議会に示してほしいと思うのですが、いかがか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"それから、やはり区によって状況が違いますので、品川区で必ず園庭をというふうにするのは、ちょっと難しいというふうに思っています。","id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問・要望","question":"基準、保育の品川基準みたいな、こういうチェックを行っていますというような状況を議会にも区民にも明らかにしていただけるようにしてほしい。もう１点なのですが、この辺は、担当の課長とか部長はどう受けとめていらっしゃるのかお伺いしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"具体的に私立支援係が、４月で１０園、今年度中に１２園増えますので、そこには職員を１人増員しています。足りているか足りていないかということでは、きちんと仕事は回しております。","id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問・要望","question":"具合の悪い人はいないでしょうか。やはりこんなに増えていて、すごい大変だと思うので、健康な方によりよい仕事をしていただきたいと思う見地から、いかがか尋ねました。","respondent":"佐藤保育課長","answer":"私立支援係は、昨年度６名、今年度１人増えております。私立支援係１つの係だけでやっているわけではございませんで、庶務の係もありますし、私も含めて課全体で私立保育園の増には対応しています。","id":"exchange-035"},{"speaker":"あべ委員","kind":"質問","question":"そうすると、この認可外についても、これから区として少し関与を深めていくということなのでしょうか。そういった開設情報とか、変更の情報とか、あるいは質の問題は特に今までどおりという考えなのか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"制度上、難しい問題がありますので、そこはやはり都とどうしても協力しながらという形になっていかざるを得ないという部分はあります。アドバイスを含めて、指導というよりも、どうやったらうまくいくかということは一緒に考えていきましょうというスタンスでいます。","id":"exchange-036"},{"speaker":"あべ委員","kind":"質問・要望","question":"遠い認可に入っていたり、制度的に誘導する視点と言うと言い過ぎですけれども、より有利なルートになっているというのが今の制度設計だと思います。","respondent":"大澤待機児童対策担当課長","answer":"やはりいろいろな話で、こういう制度だと説明したりする場ができましたので、今までよりは大分スムーズに話も進むかなというふうに思ってあります。","id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぜひこの先も頑張っていただきたいのですが、開設者に担当の方からしっかりとお話ししていただきたいのですが、どういう形で行われているのか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"まずは町会長にご説明して、説明会をやるのか、説明会または個別訪問で必ずやるように指導しております。複数回訪問して、基本は説明会または個別訪問で近隣の方には内容をご説明する、それはどこの事業者も一律でやっていただいているところです。","id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、町会の一員になるというお話があったので、まさにそのとおりで、近隣の方への周知とご説明は丁寧にしてほしいと求めました。今出ているところでは、そういうものは出ていないとお聞きしているのですが、現状ではそういうものはないという認識でよろしいか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"場合によっては、区の職員が同行してご説明申し上げたり、説明会にも一緒に参加したりしています。５時間にわたって必死に説明申し上げたりですとか、今のところは、そこまで大きな反対はないという状況です。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問・要望","question":"済みません、１点だけ。先ほど求めたのですが、今日教えていただけるのか、最低でも離職率と人件費比率は知りたいと考えています。","respondent":"大澤待機児童対策担当課長","answer":"参入するためのチェック項目というのは、具体的には、財政状況と……。そういうことではなくて。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問","question":"さっき言ったのは、保育園の経験があるかどうかとか、事故の件とか、最低でも離職率と人件費比率はお伺いしたいと思っているのですが。","respondent":"大澤待機児童対策担当課長","answer":"では、それはまた改めてご報告するということでよろしいでしょうか。","id":"exchange-041"}]},{"id":"topic-04","title":"平成２９年度新入学学校別増減要因一覧","agenda":"平成２９年度新入学学校別増減要因一覧","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"中延小学校は毎年少ないのですけれども、今年も少ないみたいですが、今、学区の組み替えの協議が学事制度審議会でされていますね。その結果が出るまでは現状維持で様子を見るということになるのか尋ねました。","respondent":"有馬学務課長","answer":"中延小学校につきましては、基本的に学区を今現在、来年に向けてどうこうするということは、今のところ考えておりません。基本的には学事制度審議会の中で全体としての学事制度の見直しを全体として、この学校でということではなくて、全体として考えております。","id":"exchange-042"},{"speaker":"鈴木（博）委員","kind":"質問","question":"要するに、学事制度審議会で学区の見直しをしているから、今現在、中延小学校の数が少ないことに関しては、何か学区を動かすとかというのではなくて、魅力の発信だとか、取り組みをするとか。","respondent":"有馬学務課長","answer":"当然、いわゆる小規模校というところに限らず、全校、それぞれ自分の学校の魅力を発信するという努力は行っております。自校の魅力を発信していくということで、毎年それは努力はしているところですので、それは継続して行っていく予定です。","id":"exchange-043"},{"speaker":"鈴木（博）委員","kind":"質問","question":"いや、だから、その結果がこうですかということです。","respondent":"有馬学務課長","answer":"今年度につきましては、中延小学校は希望者が６名ということで、昨年は２名でしたけれども、４名のプラスというようなことで、一応の結果は出ているというふうに認識をしております。","id":"exchange-044"},{"speaker":"のだて委員","kind":"質問","question":"この表の中で、小学校から義務教育学校に移った人数は、どこを見たらわかるのか伺いたいと思います。","respondent":"有馬学務課長","answer":"〔「意味がわからない。中学校、義務教育学校の後半の１番から６番の義務教育学校、これが全体として小学校から入学した７年生という数字になります。","id":"exchange-045"},{"speaker":"高橋（し）委員","kind":"質問","question":"まさに一貫した形の教育が行われていると伺っていますので、その小学校に入りたいといった場合に、学区外からその幼稚園には入れるわけですね。そういった実態について、この前もお話ししたのですけれども、もう一度お考えを聞かせてください。","respondent":"有馬学務課長","answer":"そういったことも総合的に考えていかなければいけないだろうということで、今のところ、そういう結論にも至っていません。今のところ、そういう考え方に立っていないというようなところが現状です。","id":"exchange-046"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"やはり幼稚園と小学校の連携が非常にうまくいっている例だと思うのです、成果が出ているというところだと思うのです。ですから、ぜひ何らかの計画を進めていっていただければということで、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"}]},{"id":"topic-05","title":"わ！しながわオリンピック・パラリンピック教育「ようい、ドン！」","agenda":"わ！しながわオリンピック・パラリンピック教育「ようい、ドン！」","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"各教科等における年間３５時間程度の学習、これ、学校で全体ということなのですか。学年とかではなくて学校全体で年間３５時間、いろいろなところで使っていくという、そこのところをお願いします。","respondent":"熊谷指導課長","answer":"丸々４５分ですとか５０分やるということではなくて、市民科、それぞれの教科等で位置づけながら関連づけてということです。それぞれの子どもたちの実態に応じて、各学校で年間指導計画に位置づけながら活用していただきたいというふうに考えております。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問","question":"いろいろな精神的なものが盛り込まれていたと思うのですが、この品川の教育のところのこれをつくるに当たって、その辺はどういうふうに意識をされているのかの説明を求めました。","respondent":"熊谷指導課長","answer":"それを踏まえた上で、「ようい、ドン！やはりオリンピック・パラリンピックは非常に重要なので、本区における環境の取り組み、そういったことも含めて掲載するように努めました。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、課長がおっしゃったように、ぜひ平和の部分、国際的なつながりとか、そういった面で、いかに平和が大事なのかということも含めて、障害者の理解の面でも深まるように活用してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほどの３５時間の話なのですけれども、それを教えるために学校の授業を使おうかではなくて、基本的に学校でこういうことをしなければいけない。例えば市民科などでも本来やるべき部分が削られてみたいな話になっていくと、本来進めていく中で、いかがか尋ねました。","respondent":"熊谷指導課長","answer":"その中で、例えば社会科で、１９６４の東京オリンピックの前後で町は非常に変わって、そこでレガシーとして今も残っているものがあります。それに絡めてですとか、まず、実際の各教科等でやっていることと関連づけてというときに使ってほしいというふうに思っているところです。","id":"exchange-051"},{"speaker":"高橋（し）委員","kind":"意見","question":"そうしてほしいと求めました。重要性は十分承知しておりますけれども、実際、配慮をしていっていただけるといいかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"}]},{"id":"topic-06","title":"平成３０年度品川区立学校教育職員採用候補者選考日程","agenda":"平成３０年度品川区立学校教育職員採用候補者選考日程","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"昨年、たしか６人採用しようということでやって５人採用だったと思うのですけれども、今回も６人程度の採用予定で３０人の目標人数を達成できるということでよろしいのか尋ねました。","respondent":"熊谷指導課長","answer":"現在、２４名固有教員がおりますので、今年度、６名程度採用いたしまして、ただ、６名絶対にというよりは、品川区で一生先生をしていただく方ですので、資質ですとか適性を見まして、６名程度採用する予定です。","id":"exchange-053"},{"speaker":"新妻委員","kind":"確認","question":"済みません、１点だけ確認いたします。(1)のほうを多くとか、(2)のほうを多くとか、何かそういうお考えはあるのか尋ねました。","respondent":"熊谷指導課長","answer":"どちらかというと、両方持っていてほしいという思いはあります。昨年度も(2)でなられた方も多くおりますので、特に(1)、(2)に軽重をつけるということは考えてはおりません。","id":"exchange-054"},{"speaker":"鈴木（博）委員","kind":"質問","question":"７月と８月に試験をして、最終的に９月下旬ぐらいに決めるということですけれども、仕事をしている職を辞めるということになるのか尋ねました。","respondent":"熊谷指導課長","answer":"それから、産休育休代替の方もいますので、受かるまでは辞める必要はございません。受かったところで辞めて固有教員になっていただくということになります。","id":"exchange-055"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、前のところで、今日も何もいわなかったのですけれども、例えば、６月から９月というのは、これは時期としては適切なのですか。仕事が決まってしまってからということになるのではないかと思いますが。","respondent":"熊谷指導課長","answer":"東京都ですとか、他県も同じ時期に実施していますので、それに準じてということで考えております。ですので、特にこの期間で課題があるかということは今までございませんでしたので、ほかの都道府県と同様に実施していきたいと考えております。","id":"exchange-056"},{"speaker":"沢田副委員長","kind":"確認","question":"今、現状の確認をしたいのですけれども、小学校と中学校の両方の免許状を持っている先生は、この２４人のうちどれぐらいいらっしゃるのか尋ねました。","respondent":"熊谷指導課長","answer":"例えば特別支援の免許ですとか、２４人おりますけれども、実際に免許の総数は４２あります。それから、社会と英語というように複数持っていらっしゃる方もいますので、その方によってさまざまというふうに申し上げたいと思います。","id":"exchange-057"},{"speaker":"沢田副委員長","kind":"質問","question":"先ほど、今回、３年以内に小学校免許取得の意欲のある方を支援していきたいという話があったと思うのですけれども、この今いらっしゃる中で、そういった小学校免許をこれから取りたいという方がいらしたら、その方も支援していかれるということか尋ねました。","respondent":"熊谷指導課長","answer":"今年度採用になった５人のうち２人が小学校免許を持っておりません。この２人については、すぐに免許を取りにいくのは難しいと思いますけれども、この２人についても補助していきたいと考えているところです。","id":"exchange-058"},{"speaker":"沢田副委員長","kind":"質問","question":"ほかのその前のときに入った方とかはどうなのか尋ねました。","respondent":"熊谷指導課長","answer":"もともと小学校免許というふうにうたっていた時期がありますので、実は、昨年度、中学校国語の２級免許を取った方がいます。３年ぐらいかかったのですけれども、実際に全てこちらで補助をして免許を取らせた経緯があります。","id":"exchange-059"}]},{"id":"topic-07","title":"東京学芸大学と品川区との連携による学習支援事業（ＧＳＰ）の概要","agenda":"東京学芸大学と品川区との連携による学習支援事業（ＧＳＰ）の概要","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"試験に受かった人が入るところですから、これで進学の枠をつくって４名上限ということは、入試で入ってくる一般生徒との整合性とかはどうなるのか尋ねました。","respondent":"熊谷指導課長","answer":"東京学芸大学はさまざまこうした取り組みをしているようでして、全入で、そこに上がるための内部試験等はないそうです。ですので、竹早中学校の校風に憧れて行きたいというお子さんがいる場合には、同じような形で面接等で受け入れるということであります。","id":"exchange-060"},{"speaker":"新妻委員","kind":"質問","question":"もうちょっと詳しくお聞きしたいと思います。４名枠ということなのですけれども、希望した人が、まずは品川の中で４名を決めていくという考え方なのか尋ねました。","respondent":"熊谷指導課長","answer":"ですので、４名を決めるのは学芸大附属竹早中学校、学芸大、また、それまでの支援の中でふさわしいお子さんを選んでいくという形になると思います。ですので、最終的には面接で学芸大学附属竹早中学校の先生方との選考の中で決まっていくことになる予定であります。","id":"exchange-061"},{"speaker":"あべ委員","kind":"質問","question":"６年生４０名、この選び方と言ったらいいのでしょうか、要保護等の対象家庭のみにご案内を配付して希望を募ってということにまずなるのでしょうか。その辺の具体的なところの説明を求めました。","respondent":"熊谷指導課長、有馬学務課長","answer":"人数は後ほど有馬課長からご説明いたしますけれども、まず説明会を行いまして、学習支援事業について趣旨をお伝えした上で申し込んでいただいて。２０％というのは小学校全体での２０％ですので、対象は大体４５０名から、多くても５００名ぐらいの数が就学援助の対象になるであろうと見ているところです。","id":"exchange-062"},{"speaker":"あべ委員","kind":"質問","question":"さっきも伺ったと思うのですが、超えたときには、区教委として４０人に絞り込むという形になるということでよろしいのか尋ねました。","respondent":"熊谷指導課長","answer":"面接と、２００字から４００字程度の勉強したいという思いを書くような作文等を出してもらおうかというようなことも考えているところです。","id":"exchange-063"},{"speaker":"飯沼委員","kind":"意見","question":"私たちはもっと小さい年齢から必要な子に支援してほしいということも発言していたので、機会が増えていくということはいいことであると思っています。今ちょっと……との意見を述べました。","respondent":"有馬学務課長","answer":"学習支援をしていくということで、そういう思いもありまして、指導課と一緒になって学習支援という形を進めていきたいというように思ったのがそもそもの発端です。","id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問","question":"そういった意味では、品川区では初めての試みですが、ほかの自治体でもやられていたりするのですか。そういった広がりとか、ここだけの新しい試みなのか、そこの説明を求めました。","respondent":"熊谷指導課長","answer":"この学習支援事業につきましては、本区と学芸大との唯一の取り組みになります。それ以外で、学芸大学はさまざま研究をされていますけれども、この内容につきましては、本区だけということです。","id":"exchange-065"},{"speaker":"沢田副委員長","kind":"質問","question":"そういうものはないですか。その辺のところがどうなっているのか。","respondent":"熊谷指導課長、中島教育長","answer":"ほかの道もある、２番の進学支援の４名という枠も学芸大から提示がありましたので、お受けしたいというふうに考えています。指導課長から説明がありましたような多様な進路を提示するということで、矛盾しているという部分をお感じになられるところも重々私どももわかります。","id":"exchange-066"},{"speaker":"高橋（し）委員","kind":"質問","question":"電車賃はかかるし、その辺はどうするのか、細かくて済みません。３６人は区立中学に行くということですが、そういった成果を見ていくためには、その辺はいかがか尋ねました。","respondent":"熊谷指導課長","answer":"区立中学校または義務教育学校に入ってから残りの３６名の支援ということなのですけれども、１つは、これが１年限りのことではなくて。","id":"exchange-067"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひそこは重々配慮していただきたいと思うのと、区民がこういうことにも使えるような、うまくリンクをさせてほしいと求めました。要望でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"}]},{"id":"topic-08","title":"特別支援学級（中学校・義務教育学校後期課程）の新規開設","agenda":"特別支援学級（中学校・義務教育学校後期課程）の新規開設","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"浜川のほうですけれども、現在ある通級指導学級については、これは従来どおりありつつ、新たに固定級を設置するということなのでしょうか。現状との比較で教えてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"こちらはあくまで通級ですので、平成３０年度より東京都の制度として、特別支援教室に変わっていきます。近隣の中学校に訪問指導に行く制度が平成３０年度よりスタートいたしますので、新たに毎日対象の生徒を指導する特別支援学級が必要となる状態です。","id":"exchange-069"},{"speaker":"あべ委員","kind":"質問","question":"機能としての支援教室になり、新たに学級としての固定学級ができるということの理解でよろしいでしょうか。多分、といって、固定級に移籍していくということをどういうふうにその辺は変更されているのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"純粋な不登校だけの対応のお子さんの場合には、２年間経過措置的に、校内体制の工夫は続けたいというふうに浜川中学校の校長からは聞いております。そこへの支援といたしましては、マイスクール五反田の指導員を例えば定期的に派遣する等工夫してまいりたいと考えております。","id":"exchange-070"},{"speaker":"あべ委員","kind":"質問","question":"何か再配置的な、あるいは今後さらにその面では充実させていくような計画もあわせて、何かそういう不登校対応はありますか尋ねました。","respondent":"大関教育総合支援センター長","answer":"復帰をなるべく前提とできる、あるいは未然防止という段階の対応をしておりますので、大学生等を活用した指導や面談等も行っております。例えば、マイスクール五反田以外にもう１カ所、さらに浜川の場所にそういったものを設ける等の将来的な可能性もないわけではございません。","id":"exchange-071"},{"speaker":"飯沼委員","kind":"質問・要望","question":"せめて２学級、準備をしてほしいという意見をいただいたのと、中学生からですね。どうして後期のみなのか、ぜひ前期のほうも入れていただきたいというご要望をいただいたので、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"最初の当面１学級ではなく２学級程度の希望者があるのではないかという部分につきましては、２学級必要であれば、２学級の準備をしてまいります。","id":"exchange-072"},{"speaker":"飯沼委員","kind":"質問・要望","question":"できるだけ多くのクラスの子どもたちの交流を大切にしてほしいというところにおいては、ほかの学年の人が通るようなところにぜひ配置をして交流を深めてほしいというご意見が出ていたので、この辺もぜひ検討をお願いしたいと思います。","respondent":"大関教育総合支援センター長","answer":"学校の状況等も踏まえながら、なるべく孤立しないように、学校の中でも多くのほかの生徒と交流が進むような場所を選定してまいりたいと思います。","id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問","question":"もう１つなのですが、自閉症と情緒障害のところで、浜川が新たに固定級とするということなのですが、１校で十分なのですか。新しい制度が始まる、特別支援教室が始まっていく中での情緒と自閉症の子どもたちの固定級、１カ所で足りるのかどうか、その辺を聞かせてください。","respondent":"大関教育総合支援センター長","answer":"これまで自閉症・情緒障害特別支援学級、２３区内では、まだ２区しか設置がございません。まずは１学級開設して、当然、将来的にさらに増やしていく必要もあろうかと思います。","id":"exchange-074"},{"speaker":"高橋（し）委員","kind":"意見","question":"２つあって、１つ目は、それぞれの設置については、該当の生徒や保護者の方にとっては大変これからの学校生活でプラスになることだと思いますとの意見を述べました。","respondent":"大関教育総合支援センター長","answer":"学校を通じて、近隣等も含めた保護者等へ説明、それから児童生徒への説明は、丁寧に行ってまいりたいと考えています。それから、６月に最終的な同意という形を都と区との間で行うのが例年の流れとなっておりますが、もう既に担当者レベルで相談は進めております。","id":"exchange-075"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"学校のほうの説明については、在校生から見た通級と固定級だと違いが出てくるので、そこのところを理解して説明を十分してほしいと求めました。ぜひ東京都との連絡・調整も充実したものにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"のだて委員","kind":"質問・要望","question":"新しくなって看護師は配置されたのか、確認させていただきたい思います。","respondent":"吉田保育施設調整担当課長","answer":"看護師も配置されております。","id":"exchange-077"},{"speaker":"あくつ委員長","kind":"質問・要望","question":"思う存分にご意見を述べていただきたいとの思いから、１年間、若干ほっとしております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/203794?Template=document&Id=4912#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":67126,"voices":209}},{"id":"h29-20170515-5","meetingId":"h29-cm05","date":"2017年5月15日","dateIso":"2017-05-15","committee":"総務委員会","time":"午後 １時００分～午後 ３時２５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"シティプロモーションの取り組み","agenda":"シティプロモーションの取り組み","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"ちょっと不勉強でごめんなさい。この２年間やってきて２年間の予算と、それの効果はどのぐらいあったのかという評価をされているのかということをお聞きしたい。","respondent":"木村報道・プロモーション担当課長","answer":"そういうところもありましたので、広報活動に重点を置くような事業には手厚くというような形で昨年度は変更いたしまして進めてまいりました。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"イベントは１回１回だから、そういう発想にはなぜ至らなかったのかというのと、今年の３件１５０万円と減額になったわけですよね。この辺のところの考え方というのを改めて教えていただきたい。","respondent":"木村報道・プロモーション担当課長","answer":"もともとこの考え方そのものは、今後のことを考えますと、発信していっていただくように持っていかなければならないというのが私どもの考えです。","id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問","question":"どうして３５０万円余あったものが、今年は１５０万円で３件という、また来るかもしれないではないですか。そういうふうに減らしたというところの考え方の説明を求めました。","respondent":"木村報道・プロモーション担当課長、中山企画部長","answer":"実際に、昨年度実施した事業者の中でも、安価に運営をされた、安価に効果的に広くＰＲをしていただいたという方がおりました。正直平成２７年度というのは時間も限られていて、品川区の魅力を発信してもらうことを税金で応援していくという発想だというふうに考えました。","id":"exchange-003"},{"speaker":"つる副委員長","kind":"質問","question":"そうすると、それは計画していてもこの事業の対象になるのかどうか、その辺の、どのぐらい柔軟性があって、そういうような形になるのか。逆に、その期間というのはなかなかできませんと言うのか、そのあたりの説明を求めました。","respondent":"木村報道・プロモーション担当課長","answer":"現時点では、８月決定以降から行われるものとして募集をするというところでございまして、今のところは対象というふうには考えておりません。ちょっとかたい答弁で申し訳ないのですけれども、そういう形で進めするというふうに考えております。","id":"exchange-004"},{"speaker":"つる副委員長","kind":"質問・要望","question":"だけど、こういうレベルのものとなると、そのぐらいの期間で設定していて、少額でも何かあればやってみようということもある。５月であればゴールデンウィークとか、今後の検討の中で考えていただきたいなと、最後は要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"吉田委員","kind":"確認","question":"すみません。私は１番のほうの目的のところに、そういうことを考えられているのかどうか確認したいのですが、いかがか尋ねました。","respondent":"木村報道・プロモーション担当課長","answer":"そういう形で、日頃のいわゆる情報発信とは別に、そういう部分も含めてやってまいりたいというふうに考えております。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"そういうことを考えていらっしゃるのでしたら、次の段階としてこういう仕掛けを１０月のプロモーションサミットに向けて考えていますというようなご報告もまたしていただけるというふうに考えてよろしいか尋ねました。","respondent":"木村報道・プロモーション担当課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-02","title":"マイナポータルの運用開始","agenda":"マイナポータルの運用開始","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"制度と言うのですか、いろいろ情報漏えいが現実的にいっぱいあるし、個人情報を使って利用していくということになるわけですよね。先ほどの何点かの質問、。","respondent":"仁平情報推進課長","answer":"これの適切な運用、セキュリティ関係も含めまして、職員の研修のほうをきちんと行って対応をしていきたいと考えています。どういうことを行うのか等、例えば使用上の注意点とか安全面について、その辺も啓発のほうをしていきたいと考えています。","id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"なりすましだって予想されるわけですから、非常に限定していくべきだし、ちょっとそういうふうに思います。私も何人かの方にも伺ったし、なかなかそうも行かない部分も出てくるという、そういうこともあって非常に心配だと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり情報が集約されていくということは危険性も増すということですから、ぜひ今後考えていただきたいなというふうに思います。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"かなりの利便性はもうどんどん、これから１００も２００も、それ以上すごい数の情報が簡単に引き出せるというような状況になってくると思います。意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"}]},{"id":"topic-03","title":"平和首長会議","agenda":"平和首長会議","exchanges":[{"speaker":"南委員","kind":"質問","question":"具体的にこのレベルアップにつながっていくということを、ちょっと漠然としているので、具体的なことがあったら伺いたいと思います。３点です。","respondent":"米田総務課長","answer":"この辺については、その辺の情報収集に努めてまいりたいというふうに思ってあります。世界的な会議ですから、その辺は１つレベルアップにつながるのではないかというふうに、そういうようなことで考えているものです。","id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"私、被爆体験者の話をいうのが出たので、ちょっとそこだけ伺いたいのですけれども、被爆者ってだんだん人口的に本当に少なくなっていますよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"吉田委員","kind":"提案","question":"あまり小さいときでなく、現に今まだお元気でお話をしてくださる方というのは、本当に数少ないのではないかなというふうに思います。本当はあれだけのボリュームのお話を伺ったらもっといいのですけれども、図書館などで広く活用が促せると、これは提案といいますか意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"つる副委員長","kind":"質問","question":"その上で具体的なところで１点だけ、手続きの具体的な部分はどういった部分で、区としてのスケジュールがもう既にあればそれを教えてほしいと求めました。","respondent":"米田総務課長","answer":"なるべく早く手続きのほうは行ってまいりたいと思いますが、手続き自体は、そんなに多く時間はかからないだろうと考えています。スケジュール的なものはおそらく１、２カ月は要するかと思いますが、そんなに時間のかかるものではないと考えております。","id":"exchange-015"},{"speaker":"つる副委員長","kind":"質問・要望","question":"本当に区制７０周年の周知啓発期間のある意味期間内という形でこういう事業、委員会としての本当に大きな成果だったなと思います。本当に区としての取組みという観点を含めて、さらなるレベルアップと平和発信の区として頑張り続けてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-04","title":"東京都議会議員選挙（品川区選挙区）における執行要領","agenda":"東京都議会議員選挙（品川区選挙区）における執行要領","exchanges":[{"speaker":"南委員","kind":"質問","question":"そこの途中にあるので、大体３段というとどのぐらいの高さなのか、特に八潮はそういう傾斜の所に設置する所が結構あったと思うのです。そういうやり方をしていたときもあったけれども、ちょっとどうなのかなというのが心配で伺いたいなと思う、それだけです。","respondent":"安井選挙管理委員会事務局長","answer":"それがはまるようにですので１メートル２０センチぐらいにはなってしまうのですね。恐らくは植え込みでそれほど高くならないようにはしていくと思うのですけれども、そういうような形で、はめるような形で設置してまいります。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問","question":"品川区の場合はどうなのかなと、それだけ伺いたいのです。あくまで住民基本台帳が基準と考えてよろしいか尋ねました。","respondent":"安井選挙管理委員会事務局長","answer":"基本的には住民基本台帳で見るというのが普通で、区もそんなに現場で全ての方を全部チェックするということはなかなかできませんので、まずは住民基本台帳を信用してやっていくという形にならざるを得ないというのが実態だと考えています。","id":"exchange-018"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"栃木県に関しては、危機管理のために宿日直の規定などをつくって、こういう場合に５月の連休なども職員の方が緊急時に備えて庁舎に来ていたと。区民もやはり頼もしいと思うし安心できると思うのですが、その辺についてどのようなお考えでいるのかちょっとお知らせくださいとの意見を述べました。","respondent":"米田危機管理室長","answer":"これが差し迫っている状況の強弱によってとるべき対応というのは違ってくるだろうと思いますので、区としては現状そういうふうに考えているものです。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"それから対応するとなったら、実際本当にできるのですかという話にもなってしまう。そういうシステムがあるのですから、そういうところにやはり安心を持ってもらうために、私はやはり何らかの対応はすべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"つる副委員長","kind":"質問・要望","question":"区民の福祉の向上のためにこの総務委員会が筆頭委員会ですので、総務委員会のために尽力いただきたいということをお願いしたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/762881?Template=document&Id=2074#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":26084,"voices":64}},{"id":"h29-20170516-14","meetingId":"h29-cm05","date":"2017年5月16日","dateIso":"2017-05-16","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ３時００分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"立派な本文計画そのものだと思うのですが、その辺も含めてまだできていないということだったのか、お伺いします。それと、策定のための会議と、委員会なのですかね、何回行われたのか、どのようなことを話し合ったのかお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"それをヒアリングという形式で受けながら、今後この施設をどうしていくのかというのをそれぞれ個別の所管部門と企画部門で検討をする。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"策定委員会は、アドバイザー３人の方それぞれの肩書を教えていただきたいのと、それと計画そのものの策定作業そのものは委託したのでしょうか。どんな意見があったのか何件だったのかもお伺いします。","respondent":"柏原企画調整課長","answer":"これを踏まえながら更新といいますか５年目の見直しの時期に入りますので、住宅の部分につきましてはこれに基づいて今見直しの検討に入っているです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり区民からの意見を伺いたいという姿勢がないわけですから、ぜひここら辺はちょっと反省してほしいと求めました。それと、今受給手続の上でも５月中にという話もありましたけれども、その期間等補助金を受給する上の要件というのは何かあるのか尋ねました。","respondent":"柏原企画調整課長","answer":"このＡ３判でいうところの２ページの方針のところで、例えば全体方針ということで大きく当区の場合は５点ほど挙げさせていただきましたけれども。ただ、この計画そのものに補助金が入るという趣旨ではないということです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"だからつくるのですか、そういう認識なのですか」という質問をしたのですが、財政がどうにもならんと。これからの８０.８億円の経費見込みに十分対応できるというのが今の品川区の現実ではないかと思うのですけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"特にこの２３区、延床面積、そういった今後の需要等を見込みながらそういう考え方を示したというのがこの計画であるとご認識いただければと思います。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"これは十分やっていけるのではないでしょうかということで、もう一度お伺いしたいと思います。区にはそのような考えがあるのかどうか、お伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"その検討で、それを検討しなさい、まず最初にそういう大きな工事のときは検討しなさいというのが国の考えです。ですので、それをＰＦＩを優先的に検討するための手続きをつくりますよというのをここで示させていただいたというのがここのことですので。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"これに関しての区の考え方というのですか、どう対応するつもりなのか。この点をどう解決していこうとしていくのか、お伺いします。","respondent":"中山企画部長","answer":"私の認識が違っていれば申し訳ないのですが、若干その辺のところ、今のご質問の中でもそのようなご主張かというふうにも聞こえたのですけれども。我々が考えていますのは、こういう施設の特に整備については十分今後の需要を考えていかなければいけないというのが１点です。","id":"exchange-006"},{"speaker":"安藤委員","kind":"意見","question":"と言いますのは、例えば学校ですけれども、子どもの数が減るからといって今の学校の学級規模というのはでかいのですよ、欧米に比べてとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"渡部委員","kind":"質問・要望","question":"これは時間は来るわけですからお金のあるなし、１点確認は、そういうのを全て出していただけるのかなというのがあるのですけれども。","respondent":"柏原企画調整課長","answer":"今ここの中長期的な経費の見込みはありますけれども、必要な部分、それからとれる分は全て考えながらということで進めていきたいというものです。","id":"exchange-008"},{"speaker":"渡部委員","kind":"質問・要望","question":"やはり行政需要というのは刻一刻と変わってきますので、しっかりとそれについていかなければならないわけですから。やはりビルドビルドだけではどうしようもありませんで、そこはお願いをしたいと思いますので、その財源的な考え方だけの説明を求めました。","respondent":"柏原企画調整課長","answer":"そういった中でも一定程度の蓄えといいますか、そういったところがあるところで、我々も行政サービスが遅滞なくできるというのがあります。そういったところで区民サービスが遅滞したりとか滞らない、これを進めながら行政の運営をしていくというのが基本であろうと考えています。","id":"exchange-009"},{"speaker":"筒井委員","kind":"質問","question":"私から３点ほどお伺いいたします。その点区のお考えをお聞かせ願いたいのと、あと区外ですけれども、品川荘はどのような扱いになっているのかの説明を求めました。","respondent":"柏原企画調整課長","answer":"今後それもあわせてなのですけれども、この人口推計につきましては、また改めた形で検討したいというのが今の状況です。ただし、それ以上の特殊な建物でありますので、これに準じた形での捉え方をしながわ水族館はしていきたいというのは考え方として持ってあります。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"何点かお伺いしたいと思います。こうしたことについて区ではどうお考えか、まずその１点をお伺いします。","respondent":"柏原企画調整課長","answer":"そういった機能につきましてはこの施設、それをではどういう形で具体的に検証、検討していくのだというのが次のステップで入ってくるです。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問・要望","question":"それから、これも質問というか要望というか。３０年、５０年で使えなくなるような建物をずっとつくり続けていくのではなくて、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"いわゆる冒頭でおっしゃっていただいた超長寿命化というような考え方というのは、先を見たときには必要な考え方なのかなと思ってあります。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"計画が策定されて、統廃合が区民の福祉向上にどう向かっていけるのかというのが私は理解できないので、改めて伺いたいと思います。耐震化も進んでいるところで、どの程度現状で把握されているのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"平塚橋の会館が今の形でいろいろ検討して、特別養護老人ホームであったりゆうゆうプラザであったり、別の機能として生まれ変わっているです。耐震化の問題等がありましたので、基本的には劣化状況等々というのは、全施設に対して順次行っているという状況です。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問・要望","question":"伺いたいと思います。そうすると施設は減らしてはいかないというか、活用していた土地は区の新たなニーズに活用していくということになるのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"それはその施設でそういった方も使えるような方策であったりとか運用であったりとかしていく。そういった方々のニーズも捉えながら新たなニーズにも応えていくというような手法を今までもとってきているです。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"個別の施設について伺っていきたいのですけれども、今の答弁だとないということでいいのか確認させてほしいと求めました。そして、空き施設の有効活用というのが具体的に今そういったところがどこがあるのか、どういうふうに活用していくのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"ただ、これについては他の施設と比較検討しながら進めていくというものでございまして、課題が幾つかあるという認識のもとで進めたいです。それは大きな部分も小さな空き施設もありますので、いろいろな角度から検討したいというものです。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで今まで使っていた人が利用しにくくならないようにしてほしいと求めましたけれども、いかがでしょうか。これはどういったことなのかちょっとイメージが湧かないのですけれども、お考えを伺いたいと思います。","respondent":"柏原企画調整課長","answer":"こういった方々の利用の状態であるとかそういったところは十分考えながらどういった機能になっていくのかというのを検討するというものです。こういったスポーツ振興に資する形で何かいろいろな施設の可能性というのはできないかということを考えているというものを示したです。","id":"exchange-016"},{"speaker":"こんの委員","kind":"質問","question":"先ほどの質問に関連するというか、先ほどの説明で資料編のほうで２６ページの、この施設の統廃合や複合化のご説明はよくわかりました。","respondent":"柏原企画調整課長","answer":"この表記につきましてはちょっと検討しますが、表題のところに「廃」という言葉も入っているというつもりではおりました。ちょっと中身をもう一回検証します。","id":"exchange-017"},{"speaker":"こんの委員","kind":"提案","question":"この内容も先ほどのご説明でよく理解はしているところなので、整合性をというのでちょっと提案をさせていただきましたが。用途変更という形なので今までの機能は変更してなくなって、やはり整合性を持ったほうがいいのかなと思ったので、もう一回ご答弁をお願いできますかとの意見を述べました。","respondent":"柏原企画調整課長","answer":"意味合いとしては、先ほどお話をしたとおりですけれども、ご意見をいただきましたので、全体の構成等と若干絡む部分がありますので、ちょっとその部分を検証させていただきたいと思います。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"人口を増やすということなのでしょうか、ご説明ほしいと求めました。どっちかをなくしてしまうよという考えなのか、そこら辺ちょっとはっきりお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"先ほどもちょっとご議論あったところですけれども、まずＰＰＰ／ＰＦＩの手法というのが使えるかどうかを優先的に検討しなさいというのが考え方です。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"スポーツ施設に関しては、ぜひ積極的にいろいろなところからも施設の要望がありますので、積極的に検討してほしいと求めました。ですから、いないのか、そこら辺だけ一点お伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"いかに一時の建設費用等々を抑えられるかというようなところがメリットといいますかあって、この手法が出てきているというのは認識しています。いろいろな手法を考えながらの一つですので、それは検証しながらこの条件については検討するというか、考えていきたいというものです。","id":"exchange-020"}]},{"id":"topic-02","title":"のその他","agenda":"のその他","exchanges":[{"speaker":"本多副委員長","kind":"意見","question":"いずれにしましても、１年間皆様のご協力に感謝いたします。ありがとうございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/172349?Template=document&Id=6028#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":39898,"voices":50}},{"id":"h29-20170517-18","meetingId":"h29-cm05","date":"2017年5月17日","dateIso":"2017-05-17","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ４時１０分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"渡辺委員長","kind":"提案","question":"その理由は、委員の皆様方のご発言やご提案が大変多かったこと。本当にありがとうございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/645888?Template=document&Id=6514#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":2464,"voices":9}},{"id":"h29-20170519-10","meetingId":"h29-cm05","date":"2017年5月19日","dateIso":"2017-05-19","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件整理しています。","topics":[{"id":"topic-01","title":"議会改革推進会議等の設置","agenda":"議会改革推進会議等の設置","exchanges":[{"speaker":"あくつ委員","kind":"提案","question":"会派で協議いたしまして、こちらの提案のとおりで進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"須貝委員","kind":"確認","question":"今回、会議の運営に関しては「議会・委員会運営に関する申し合わせ確認事項」に載っている、あくまで一過性のものだと思います。大地震発生時の議会・議員の基本的対応見直し等をこういうふうに議論しているわけですから、また、私は筋違いだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"須貝委員","kind":"確認","question":"この申し合わせ事項に載せるということは、議員全体、議会全体の申し合わせ確認事項ですよね。筋道ではないかと思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"須貝委員","kind":"意見","question":"いや、和らいだと言っても、入っていますよね。幹事長どうのこうのというとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"提案","question":"申し合わせ確認事項は、ご提案もあって、賛同していただいて申し合わせ確認を直していくというのは。それは須貝委員が一過性のものに対してというご意見はご意見として伺いますけれども、この先、行政側ともどういう形でそれを扱っていくのかとの意見を述べました。","respondent":"鈴木（真）委員長","answer":"もう１点、先ほど、幹事長が出席というお話をいただきましたが、前回配られた資料、設置についての４項目の中に、そのような要件は入っておりません。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"一応、原則論ということを、それだけは確認をさせてほしいと求めました。やはり我々としては、３人とも賛同できないということなので、原則として進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それは個人のご意見ですから、申し合わせ確認事項が、それはご理解ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"意見","question":"この中でメンバーが出てくるわけでありますけれども、会派の中でもメンバーを決めていくという形を考えると、今、上の部分がありますけれども、リーダー・サブリーダーについては、この割り振りでやっていただいたほうが人選をするにもいいと思いますのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/706163?Template=document&Id=5222#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":8188,"voices":40}},{"id":"h29-20170525-10","meetingId":"h29-cm05","date":"2017年5月25日","dateIso":"2017-05-25","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件整理しています。","topics":[{"id":"topic-01","title":"議事日程（１）、追加議事日程および追加議事日程（２）","agenda":"議事日程（１）、追加議事日程および追加議事日程（２）","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"監査委員の選任同意につきまして、この後、採決の方法について態度を示す関係もありますので、提案者からの説明について若干伺いたいと思うのですけれども、今回の選任したい理由は何か、また共産党を選ばないという考えがあるのかとの意見を述べました。","respondent":"久保田区議会事務局長","answer":"こちらにつきましては、区長から選任同意の議案のご提案があったということで、詳しい理由につきましては、私どもでは聞いておりません。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"もう１点、共産党が第３党になるとこれを変えた理由について、何か伺っているのでしょうか。質問したいと思います。","respondent":"久保田区議会事務局長","answer":"第３会派だというような決まりはございませんので、これはあくまでも区長からの議案としてお預かりしているということでございまして、第３会派から監査委員が出ていたということではございませんので、ご報告します。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"従来の流れを見ておりますと、第３会派が選任されていたという経過がありますので、ご質問させていただきました。選任同意について、ぜひ質疑の場が私は必要ではないかと思いますので、その点は意見を述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"もし区長からそういうふうに指名ということで同意を求められているならば、この議会にあっていいのではないかと思うのです。我々に選任同意を求めるという筋をきちんとしないと、いきなりこの方が選任同意を求められますというのは、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須貝委員","kind":"提案","question":"提案をしているのですが、ここに文章としてきちんと載せていただかないと、私は今みたいに中塚委員のような意見が出てくるのではないかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"選任同意という形で区長から求められましたけれども、そこは是正していくように、区議会としても私は考えていくべきかと思います。今回に関しては、これに対しては同意します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"ですから私は、その使い方をきちんと区議会で決めた以上、それに沿って議員一人一人もやっていくべきだと思います。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/706163?Template=document&Id=5224#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":11464,"voices":66}},{"id":"h29-20170526-5","meetingId":"h29-cm05","date":"2017年5月26日","dateIso":"2017-05-26","committee":"総務委員会","time":"午後 １時０４分～午後 １時２６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"第３８号議案、品川区特別区税条例の一部を改正する条例","agenda":"第３８号議案、品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"納付すべき不足額が生じたときに、こういうふうに対応していくという新しい法改正ということで、私は賛成します。意見だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"改めて伺いたいというのが１つと、同じような出来事というのは過去にあったのかどうか、その３点を伺いたいと思います。","respondent":"伊東税務課長","answer":"過去のことですけれども、品川区におきましては昨年の影響によりまして、総額で１９万４,４００円ほどの不足が生じたです。それに関しては、昨年の１２月の段階で全て完納をしております。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"予想していた額より随分、額的には少ないので、それはそれとして伺っておきたいと思います。改めてこういう場ではっきりと伺っておきたいことかなと思いましたので、差し支えないと思いますので、ぜひの説明を求めました。","respondent":"伊東税務課長","answer":"同様の事例ですけれども、昨年のことは別として、過去にはありません。メーカーですけれども、昨年の不正に関しては、三菱自動車ということで新聞報道もされております。","id":"exchange-003"},{"speaker":"南委員","kind":"意見","question":"環境に対して優しい車であってほしいとみんなが共通に思うわけで、そういう社会の仕組みをつくって、認識も広げるようにしていくことが必要かなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問","question":"逆に払ってくれたのかとか、１個１個というわけはないと思うので、この次もどういうふうになるのか。所有者に１回案内が行くのか、具体的にどういうふうに動いて、これがもし生じた場合はどういうやり方でやっていくのかというのを教えてほしいです。","respondent":"伊東税務課長","answer":"昨年の状況ですけれども、うちの課税情報をもとに、不正車種から税額を再度算出しまして、それで変更の賦課決定をしたわけです。それで、同時並行でメーカー側に納付書を送付しまして、メーカー側から区に納税したという経緯です。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"例えば１,７００ぐらいの自治体があって、１,７００自治体のそういうのも全部、一律同じようなやり方をしたのかどうかというのを教えてほしいです。","respondent":"伊東税務課長","answer":"メーカーの今回の対応ですけれども、どこまで全く同じような形になったかというのはわかりませんが、ほぼ同じような形でやられたと聞いております。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"今の石田委員のご質問の続きみたいな感じなのですけれども、持っていらっしゃる間、毎年の手続的にはどういうふうになっていくのかということ。","respondent":"伊東税務課長","answer":"購入された翌４月１日に課税された部分での軽減ということ、税額という形になりますので、それはそれで実害はないのかと思っているところです。平成２８年度以前の、どうしましょうかという形での問いをして、そこでメーカーに申し出をする機会を与えるものです。","id":"exchange-007"},{"speaker":"大倉委員","kind":"確認","question":"１点確認で、納付忘れがあるかどうかわからないのですけれども、これからの条例改正の部分でどうなるのかという。","respondent":"伊東税務課長","answer":"今回の特例を創設させていただければ、納付忘れといいますか、メーカー側に請求といいますか、賦課しますので、通常の納付忘れに関しては、所有者に対しての督促の際は行わない、そういうことになります。","id":"exchange-008"},{"speaker":"大倉委員","kind":"確認","question":"ごめんなさい、聞き方が。納付を例えば今回忘れてしまっても、特段、課税がかかった部分にお金は改めて払う必要がないかという確認なのですが、ないということでいいのか。","respondent":"伊東税務課長","answer":"はい、そこの部分に関してはありません。大丈夫です。","id":"exchange-009"},{"speaker":"南委員","kind":"意見","question":"当然というか、許されていくというところは、私は問題ではないかなと思うのですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"そういうことで購入させて、それが明らかになったから払いますよと言って払って、メーカー側の責任は許されるものではないと思うのです。","respondent":"榎本総務部長","answer":"今は重課といって、グリーンに反するようなものは大きく税を取る形になっていますので、そういった意味の中で制度ができています。追徴する責任等がありますし、そういった意味で、環境性能のいいものをそれぞれ皆さんが購入していこうという形になると考えております。","id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"だって、改ざんしているのですから、見抜けるはずがないではないですか。行動的にも資料的にも、数字を信用して買うわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/762881?Template=document&Id=2076#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":6452,"voices":41}},{"id":"h29-20170526-10","meetingId":"h29-cm05","date":"2017年5月26日","dateIso":"2017-05-26","committee":"議会運営委員会","time":"午後１時４６分～午後１時４８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/706163?Template=document&Id=5226#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":1117,"voices":11}},{"id":"h29-20170612-6","meetingId":"h29-cm06","date":"2017年6月12日","dateIso":"2017-06-12","committee":"区民委員会","time":"午後１時００分～午後３時５４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"あべ委員","kind":"意見","question":"民進党・無所属クラブのあべ祐美子です。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"概要と方向性について２つだけ伺いたいと思います。この間ありましたけれども、実施するに当たってどういう条件が整ったと判断したら踏み切るのか、これについての条件についても伺いたいと思います。","respondent":"伊崎地域活動課長、提坂戸籍住民課長","answer":"なお、電気自動車の設置については、全地域センターに設置をするということで昨年から始めまして、今年で５カ所です。やはり前にもご説明したことがあると思いますけれども、あと迅速性と正確性を担保しつつ、よりよい区民サービスの向上を目指すということです。","id":"exchange-002"},{"speaker":"藤原委員","kind":"質問・要望","question":"２つの課を１つにしてまでという思いがあるのですけれども、その辺について、これから１年やっていくわけですから教えてください。それと最後にもう１点なのですけれども、この事務事業概要の地域振興部の2)が地域活動課になって、これは独立していないのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"１つのテーマだけ、ここにかかわって品川歴史館の役割や位置づけをどう考えていらっしゃるのか伺いたいと思います。柱になる専門非常勤の学芸員について、いよいよ常勤化・正規雇用化ということを検討していただきたい、この点についても伺いたいと思います。","respondent":"鈴木文化観光課長","answer":"貝塚と連携をしながら活用することで、歴史的な施設だけではなくて観光の資源としても位置づけられるのではないかという検討も行っております。非常勤で３月まで３名いたのが、常勤化も視野に入れながら、それも合わせて全体の検討を今しています。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川全体の文化や積み上げてきた歴史、その全体の掘り起こしという役割も、この課は担っていると思うのですよね。そういう位置づけについてもう一度お伺いしたいのと、そこの点については要望したいと思います。","respondent":"鈴木文化観光課長","answer":"区全体の歴史を保存したり、また区民の方に知っていただくという重要な機能については、今後も変わらずしっかりと取り組んでいく必要があるというふうには考えておりますので、そのことも含めて現在検討しています。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"予算特別委員会でも伺いました品川区の施設等の塀、写真と言うのですか、あれはすばらしいですね。改めてどうやっていくのかを、今日は事務事業概要ですから聞いていることは大きいのですよ、パネルだけではなくて。","respondent":"鈴木文化観光課長、小川オリンピック・パラリンピック準備課長","answer":"１点目のお祭りに関する支援ですが、特に神事にかかわる部分は直接支援というのはやはりしにくいというのが現状です。区内の工事中の壁を活用した３競技の写真の展開ですが、区内のほうでもまた機運醸成のための壁のシール等は展開してまいりたいと考えております。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問・要望","question":"例えば集会室ですとか文化センターですとか、お金を支払うときに、お仕事をされている方がなかなか受付時間中に行けないというお話も聞いております。区としてはそのような考えがあるかどうかということ、なければぜひご検討いただきたいと思うのですが、いかがか尋ねました。","respondent":"池田スポーツ推進課長","answer":"私ども新しく構築するということでございまして、より区民の方の利便性が高くなるようにということで、今コンサルを入れているところです。利用時間について、今以上の形で、区民の方にとって利便性が高まるようなシステムにしたいということで検討しています。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"それを聞いてとても安心いたしました。スケジュール的にいつ頃を目途というのがもしあればの説明を求めました。","respondent":"池田スポーツ推進課長、本多委員長、伊崎地域活動課長","answer":"予定といたしましては平成３１年１月に稼働したいという目標で動いているところです。では、ほかになければ以上で事務事業概要を終了いたします。お配りいたしました平成２９年度品川区民まつり予定表をご覧ください。","id":"exchange-008"}]},{"id":"topic-03","title":"品川区立荏原平塚総合区民会館指定管理者候補者の公募","agenda":"品川区立荏原平塚総合区民会館指定管理者候補者の公募","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"現在の指定管理者がどこかということと、今回、簡易型プロポーザル方式（公募型）に切り替えた理由について、きゅりあんと同様ということですけれども、それだとちょっと理由がよくわからないので。","respondent":"鈴木文化観光課長","answer":"それから、当初は、安定してこの文化振興事業に関して区と密接な連携体制をとりながら実施をしている事業団にまずはお願いをしたところです。例えばほかの施設、よりよい提案を選定する中で、一番適切な管理者を選びたいという趣旨で変更をしたものです。","id":"exchange-009"},{"speaker":"塚本副委員長","kind":"提案","question":"これはいわゆる今までよりも区として期待する指定管理者のいろいろな提案というのですか、応募してくれる候補者に期待するところというのはどういうものがあるのか、教えてほしいと求めました。","respondent":"鈴木文化観光課長","answer":"それから選定委員会のメンバーが、その基準に合っているかどうかを審査するという形で、よりよい運営方法を考えております。それともう１つは、もしくは区民の方に還元できる事業運営なり施設運営ができるかというような視点が中心になるというふうに考えております。","id":"exchange-010"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"区の対策はなぜ数年後になったのか、あとどうして失念という事態が起きたのか、戸籍住民課の個人情報保護についてというのが１つです。この２点ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"渡辺委員","kind":"意見","question":"日常生活にどう反映していくかというか、この年度の所管事務調査でも都市型観光、これをキーワードにやるべきかなと思っているのが１つですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"渡辺委員","kind":"提案","question":"唐津でもう１点、歴史ツーリズムというのも１つ引っかかりまして、親しみを持って提案したいなと思います。これも、とてもその土地自体がもともと何かバックボーンがあるわけではなく見えたので、これは品川の取組みにもおもしろそうだなという観点ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"中塚委員","kind":"意見","question":"その状況はあったにしても、今後正副で調整していく所管事務調査、このテーマに沿った中身がよいのではないかなというのが１点と。神社仏閣だったり、いずれにしても所管事務調査に沿って深めた立場で視察先を決めていくということが望ましいのではないかなと思いますとの意見を述べました。","respondent":"本多委員長","answer":"その後、所管事務調査等を正副で検討させていただき、同時に進めていきたいと考えています。よろしいというふうに受け取りましたので、または１０月３０日から１１月２日のうちいずれか３日間とし、実施するということでよろしいでしょうか。","id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/824061?Template=document&Id=2782#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":54944,"voices":95}},{"id":"h29-20170612-7","meetingId":"h29-cm06","date":"2017年6月12日","dateIso":"2017-06-12","committee":"厚生委員会","time":"午後１時００分～午後４時０４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この２割負担の方の割合を教えていただきたいのと、新たに３割負担の介護保険、試算されていたらお聞かせほしいと求めました。全部聞いてしまったほうが良いか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"毎回この問題をやっていて、個々の問題が出てくるということですけれども、今この時点で確かめておきたい、そして、次に出てきたときにはさらにそれを踏まえて深めていきたいという思いで聞いているのですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは１年に１回以上、分析・評価を行い、この分析・評価というのはされているのかということをお聞かせほしいと求めました。","respondent":"寺嶋高齢者福祉課長、松山高齢者地域支援課長、飛田障害者施策推進担当課長、三ッ橋国保医療年金課長","answer":"年度内ではなく、年内には一定程度の方向性が出せるものというふうに、今の段階では見込んでいるところです。１点目、品川区は平成２７年４月から開始し、モデルで実施しております。第２回自立支援協議会を１１月に予定しております、その辺で計画の提案をいたしまして、またそれを含めて１２月にパブリックコメントを行う予定です。問い合わせが何かございましたら、今回に限らず、丁寧に対応してまいります。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"総合事業では、その総合事業対象者というのは、ケアプランの総合事業という件数イコールということで考えていいのかという確認だけお願いします。","respondent":"松山高齢者地域支援課長、寺嶋高齢者福祉課長、飛田障害者施策推進担当課長、三ッ橋国保医療年金課長","answer":"先ほどの２２ページの実績のケアプランの総合事業につきましては、基本チェックリストを受けている方も全員含まれている数字となっています。あくまでも今の段階の予定ということにはなりますが、やはり７月には制度推進委員会の開催を予定したいというふうには思ってあります。自立支援協議会の中で今回諮っていきますので、新たな協議体の設置は考えておりません。件数、内容のことですけれども、まず、区民の方々に国民皆保険制度、こちらを丁寧にご説明いたしまして、対応してまいりたいと考えています。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"大変国のほうの制度改悪もあって、そういうのがぜひ区民の状況も反映して議論できるような場をつくっていただきたいということで要望します。あれだけ要望が出されていますので、ぜひそこのところはご検討いただけたらということで、要望をします。","respondent":"飛田障害者施策推進担当課長","answer":"現在は公開はしておりません。","id":"exchange-005"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"対象拡大を求めてきまして、周知というのをしてきたのか伺いたいのと、これが２０歳からになって対象者は何人になるのか伺いたいです。結構少ない、障害を持たれたお子さんを持つ親御さんから伺うのですけれども、これはどれくらいあるのか伺いたいと思います。","respondent":"川島健康課長","answer":"予算上２,２００人ほど、これは対象者ではないのですが、新たに歯科健診を受ける方が増えるだろうというふうに予算を見積もっております。実施医療機関については、少し利用者の方にしてみると、よりよい制度になるようにこれから検討していきたいというふうに考えてあります。","id":"exchange-006"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"対象者は、要は、受診券を郵送した数ということになるのではないのですか。その総数がわかれば教えていただきたいです。","respondent":"川島健康課長","answer":"対象者数ということで、受診券を送った数ですが、平成２８年度が３万５,５００件で、平成２９年度、今回送る数というのは今手元にはないです。申しわけございません。","id":"exchange-007"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（真）委員","kind":"提案","question":"品川区議会自民党・子ども未来は、この提案に沿ってなのですけれども、総合事業に関することということで、テーマを挙げました。この３課にまたがった部分もありますし、私ども会派としては必要性があるということで、この判断をしておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"若林委員","kind":"質問","question":"どうしても議論が１年間で１つのテーマ、やって２回なので、時間的にそこからなかなか奥に入れないということになってしまいます。去年ですかね、どういうふうに計画を立てているのかというのが、一つの事業として障害者の相談事業も含めて３つを出したです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"改めて現場の実態を踏まえて、どうあるべきなのかというところも、第七期に向けて議会のほうから提案していきたいです。障害者差別解消法ができて、本当に全体としても大きく改善が求められているところだと思うのですけれども、提案をさせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"大倉委員","kind":"意見","question":"地域包括ケアシステム、そういった意味では、そこを中心にいろいろな物事が進んでいけるようになるのかなという部分で挙げさせていただきました。２となっていますけれども、そういった部分を受けて、その後のあり方とかというのができればと思って書かせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、それを提言という形で行政のほうにここで所管事務調査をもとにしてまとめて出していくという考えは私としても持っておりません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/999880?Template=document&Id=3478#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":61965,"voices":93}},{"id":"h29-20170612-8","meetingId":"h29-cm06","date":"2017年6月12日","dateIso":"2017-06-12","committee":"建設委員会","time":"午後１時００分～午後２時５３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"西本委員","kind":"確認","question":"確認です。計画実行の仕切りというか、まずは委員長がされて、実際はどういう形で仕切りをしているのかというの説明を求めました。","respondent":"松代防災まちづくり部長","answer":"先ほどの説明の中では触れませんでしたが、ここ１０年ほど、ずっと取り組んできたことです。そういったところも、今後連携を図りながら、しっかりとご説明をし、齟齬がないような感じで進めたいと考えています。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、質問については、答えられない部分があると思うので、そこは私たち委員も配慮していかなければいけないと思います。共通的なところは、やはり関係部署には説明いただきたいなと思っているのですか、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"区はどういう姿勢なのかというのをお伺いしたいのが１つです。直近の状況を伺いたいというのが１つ。","respondent":"中村都市計画課長、長尾住宅課長","answer":"庁内での連携を図りまして、教育施設や福祉施設といったものの今後の将来の計画の中で対応していけるように、庁内での情報共有を図っていくです。１点目の公営住宅にかわるものとしての空き家の有効活用の検討という内容だと思います。現在、中高層建築物の紛争を予防するために、事前に標識の設置および説明会の実施を建築主の方にしていただいているところです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"区の評価を伺いたいというのが１つです。その具体的な工事に際しての問題に対しての区のかかわり方でもあると思うのですけれども、その両面について、区のスタンスをお伺いしたいと思います。","respondent":"中村都市計画課長、東野まちづくり立体化担当課長、稲田都市開発課長","answer":"防災上必要な道路についての整備がスムーズに、道路整備が円滑に進めばいいというところで、この９５％の用地未取得のほうに入っている施設である。その中で、都市開発課の中にあるという意義が、やはり再開発等の連携といったところがあると考えています。２２ページを開いていただきますと、委員ご指摘のまちづくり整備手法の検討の部分なのですけれども、一部マンションの建替え等が進められてきました。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"上流の区の現状を含めて、この対策を加速していくべきだと思うのですけれども、現状と今後をお伺いしたいと思っています。改めて、部長として自治体の災害対策にとって何が重要だと今お感じになっているのか、もしよろしければ、感想や実感を率直に伺えればと思います。","respondent":"稲田都市開発課長、古巻防災課長、持田河川下水道課長","answer":"例えばゆうぽうとにおきましては、従前はホール等があったというところもあります。その中に、防災対策に関する考え方というものを定めております。そちらの理念にのっとりまして、今後も災害対策を進めていきたいと考えております。７１ページにありますように、立会川ではこのような処理施設の整備を進めてあります。","id":"exchange-005"},{"speaker":"筒井委員","kind":"質問","question":"ひいては、他の課との連携はお考えになられていないのかということが３点目です。以上３点、ご回答のほど、。","respondent":"曽田災害対策担当部長","answer":"つくってからしばらくたっておりまして、組織改正などに対応しておらず、改訂をしなくてはいけないなというところであります。いろいろと避難などに関する考え方も変わってきておりますので、この計画を修正する必要性があるのであれば、改訂も考えていきたいです。","id":"exchange-006"},{"speaker":"筒井委員","kind":"質問","question":"今年度は、国の動きを待って、それから行くということで、今年度は予算もないということで、国の動きを注視して、それに合わせていくということでよろしいのか尋ねました。","respondent":"曽田災害対策担当部長","answer":"はい、そのとおりです。","id":"exchange-007"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"開発の２７ページの立体化についてお伺いしたいのです。限定的なものなのか、それとも長期にわたっての立体交差のビジョンなのか、その辺を教えていただきたいのです。","respondent":"東野まちづくり立体化担当課長、松代防災まちづくり部長","answer":"昨年の３月、今後、２９号線などと一体的に進めていこうというところになっております。私どもは、その２路線につきまして、まちづくりと一体的に進めていくという課です。加えて、区単独事業では非常に難しいところで、東京都での連携をもって進めるというのが、これまでの一番進めやすい形で進めてきたところです。","id":"exchange-008"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"本当に３０分とか１時間の間なのですけれども、鉄道がどうあるべきかというのも、ぜひ考えていただきたいなと思って質問しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]},{"id":"topic-02","title":"平成２９年７月区営住宅入居者募集","agenda":"平成２９年７月区営住宅入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"お一人暮らしの高齢者の方を中心に、こういう低廉な住宅に対する要望というのは強く感じているのですけれども、２点だけお伺いします。私の記憶違いというか、忘れてしまったのですが、いかがか尋ねました。","respondent":"長尾住宅課長","answer":"窓口でもお問い合わせがありましたら、募集の時期でなければ、一般的な対応としてお伝えさせていただいている状況です。ポスターへの掲載等につきましては、それに限らず、区民の方への周知については、いろいろ状況を踏まえながら工夫していきたいと考えております。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"どういった方が本当に苦労して何回も応募している方がこれだけいるのだとか、あるいは新規なのか、ぜひ把握していただきたいというのが要望です。大事な施策だと思いますので、ぜひ努力で広げていただきたいと、これも要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-03","title":"平成２９年度品川区電力節減方針","agenda":"平成２９年度品川区電力節減方針","exchanges":[{"speaker":"西本委員","kind":"確認","question":"２点だけ確認です。毎年、方向をつけて、全体的な動きになってくると思うのですが、そこのまとめ役は環境課という認識でよろしいか尋ねました。","respondent":"小林環境課長","answer":"データの集約ですが、毎月、各課からデータを集計いたしまして、環境課で取りまとめて、最終的に何％だったかということを公表しています。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"それと同時に、権限というのは、どこまで権限があるのですか。もう少し何とかしなさいとか、対応しなさいという権限というのは、環境課にあるのか尋ねました。","respondent":"小林環境課長","answer":"今回の削減方針にもありますように、暑ければ区民の皆様への影響等もありますので、そこまで絶対下げろというところではございません。やはり節電というのは非常に大切なところですので、強制力はないにしても、努力は続けてくださいということで指導はあります。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"ここは１２％とか、ここはもう少し頑張って１８％とか、トータル的に１５％になればいいのかなと思うのです。施設によっての細かい節電のあり方を検討していただけるものなのか、しているのか、いかがか尋ねました。","respondent":"小林環境課長","answer":"１つ１つ施設の用途・目的に応じて、そういったパーセンテージを細かく出すというのは、非常に難しいかなと考えております。基本的には全体の中で１５％を目標として達成するということを我々は考えてあります。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"将来的には、何年先にはこれぐらいのＣＯ２削減まで含めての計画的な目標ができるのではないか。ぜひ環境課が中心になって、安全に進めていただきたいなと思っていますので、ご検討。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"筒井委員","kind":"質問","question":"エアコンの設定温度についてなのですけれども、つい先頃、２８度の根拠はないとか、いや、あるんだという論争に一時なりました。品川区としては、推奨設定温度は何度になるのか尋ねました。","respondent":"小林環境課長","answer":"エアコンの設定温度ではなくて、室温を２８度に設定するように調整するです。２８度が推奨温度です。","id":"exchange-016"}]},{"id":"topic-04","title":"平成２９年度立会川・勝島運河環境美化運動","agenda":"平成２９年度立会川・勝島運河環境美化運動","exchanges":[{"speaker":"西本委員","kind":"質問","question":"通常７月１日だったので、選挙の件があってということなのですけれども、この日程設定はどうだったのでしょうか。日程の調整は、どういう調整をされたのか尋ねました。","respondent":"持田河川下水道課長","answer":"こちらはこちらで５日に決まっていて、これは動かせないということになってしまいまして、実態として同じ日の開催になっているです。その辺は正直に事前に説明しておりまして、また小学校のお子さんたちもいらしていますので、この日で決定という形になっている状態です。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問・要望","question":"お互いが日にちを譲れないというのは、わからないではないのですが、都議選が７月２日にあるというのは、もう大分前に決まっていた話です。調整していかないものについては、調整を図っていただきたいと思っていますが、いかがか尋ねました。","respondent":"持田河川下水道課長","answer":"実態としてはなかなか難しいということもあり、さらにもっと前にずらすなど、いろいろ案は考えたのです。今年度はこういった形で設定したですので、いろいろなことがありながら、今後も継続していくのが大事だと考えております。","id":"exchange-018"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"区の耐震改修促進計画も含む地域防災計画について、所管事務調査で取り上げてはどうかというのが１つです。提案しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"新妻委員","kind":"質問・要望","question":"地域防災計画が今年度改訂ということですので、具体的なところをしっかりと調査を進めていきたいなというところです。弱者の方のための避難所対策のあり方など、ペット対策も含めて、そこもぜひしっかりとやっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問・要望","question":"無電柱化の推進ということも、１つの項目かもしれませんけれども、それも踏まえて、ぜひ調査をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"先ほど来お話があるように、改訂についてはしっかり議論したほうがいいのではないかなという思いであります。どちらにしても、もう一点は、後日提出させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"新妻委員","kind":"意見","question":"品川区には木密地域があるというところで、昨年起こりました糸魚川市の火災を、少し時間がたちましたので、行政側がどのような対応をしているのかというところを、しっかりと見て参考にしていきたいなという思いがありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/594236?Template=document&Id=4202#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":36836,"voices":132}},{"id":"h29-20170612-9","meetingId":"h29-cm06","date":"2017年6月12日","dateIso":"2017-06-12","committee":"文教委員会","time":"午後１時００分～午後３時４１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"義務教育学校のところで、そういった学校では校庭や体育館を３分割して使用しているというお話を聞いて、改善策などあれば伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"６年間たってきているわけですから、そういったところを巡回指導員の方がしっかりと把握できているということなのでしょうか。改めて伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"体育館が足りなくて３分割というような実態は授業においてはございません。例えば、今後はそちらのほうの十分な活用等も含めた研修を今進めているところです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"図書館のことについてもお伺いしたいのですけれども、よく活用されているというところで、そこを超えていくべきだというお話をお聞きいたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"１６ページの学校改築なのですが、今年度は４校だということで、そのあたりのことを伺いたいのが１つです。ある程度の傾斜があるということですから、私はすぐに調査するべきだと思うのですけれども、そういう点も含めて伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"学校改築の今後の予定ですけれども、現在の長期計画のもとでは、そういったペースで進んでいくということになろうかと思います。それから、そういったものは随時私どもの庶務課の担当などに入ってまいりますので、それは随時必要な対応をとっているところです。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"不勉強で教えていただきたいのですけれども、トータルで４校だと、そういう理解でいいかということが１つです。即刻調査をすべきだと思うのですが、こういう現状があることをご存じなのかどうかと、そこを改めてお願いします。","respondent":"品川庶務課長","answer":"それから、床についてですが、子どもの健康状態に影響するような状況がある床はないと考えています。それが子どもに影響があるということが証明できるような情報があれば、それは即刻見に行って改修なり何なりやっていかなければいけないと考えます。","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ、そういう声があるということなので、即刻調べてほしいと求めました。個別に後で私も申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"質の関係でお話をお聞きしたいのですけれども、ある園で、昨年、クリスマス会をやらなかったという声をお聞きしました。様々聞いておりまして、そういったところをできるだけ柔軟に対応していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"福島子ども未来部長","answer":"今後も様々なご意見は出るかと思いますけれども、保護者の身になって誠実に対応していきたいというふうに考えております。ですから、個別の１つ１つについて、どれをこうしたということはここでは答えませんけれども、苦情につきましては全て適切に対処しています。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"子どものためにもよくないと思いますし、今後そういったことがあったときも、やはり帰されてしまうということになるのでしょうか。そこは、しっかりと対応していただきたいのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"それで、個別具体的な話ではあるけれども、保育園という施設が親に対してそういう対応をしていいのかという問題ですから、保育内容そのものなのです。答弁をもう１回お願いしたいと思います。","respondent":"福島子ども未来部長","answer":"もちろん適切に対応してまいりますし、個別的に見ていきますと、やはり様々な事情があってその問題は起きています。それにつきましては、１件１件解決するように行っていますし、保護者の方に不自由をかけないような体制で臨んでいきたいというふうに考えております。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"貸してくれるべきものを貸してもらえないで自宅に帰れということは、出勤するな、遅刻しなさいと言っていることと同じではないですか。その上で納得したいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"渡部委員","kind":"確認","question":"１件だけ確認をいいですか。例えば事業廃止によって何かそういうトラブルになったりしないのかというところだけ確認させてください。","respondent":"廣田子ども家庭支援課長","answer":"今後の方針についてなのですけれども、軽減されているのは主に授業料ですので、そちらの方向で考えていくというところです。予定数を満たしていないので、近いものをやるよりも、違った形でニーズがあるものにシフトするということも必要ではないかと思っているところです。","id":"exchange-011"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"南委員","kind":"確認","question":"４点目には、会場ですけれども、品川図書館と品川区の教育総合支援センターということでよかったのですか。その確認です。","respondent":"熊谷指導課長","answer":"義務教育学校後期課程への進学支援ということで、学習支援、東京学芸大学付属竹早中学校への進学をできるような連携事業としております。それから、場所につきましては、先ほど委員ご指摘のとおり、教育総合支援センターと品川図書館の２か所を考えているところです。","id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっとわからないのでそこを教えていただきたいのと、そこも含めてどういうふうに考えているのかということと、あと最後に。そういう方々に対する対応も同時に考えていってほしいというふうに思っているので、意欲のある子で作文等を確認して、そのあたりの考え方。","respondent":"有馬学務課長、熊谷指導課長","answer":"１点目の就学援助の対象についてお答えいたします。確かに６年生のときには就学援助対象者で、国公立に枠を広げるべきかどうか、それをあわせて検討してまいりたいと考えています。それから３点目ですけれども、実際に４０名に入らなかった子ども、地域未来塾という学習支援を行っています。そういったものも組み合わせながら学習支援、進路支援を行っていきたいと思っています。","id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問","question":"２つお伺いしたいのですが、１つは、現時点で品川区でそういうことがあったのかどうかということが１つです。それからもう１つは、それがあったのですけれども、その辺のお話が入っていらっしゃるかどうかということです。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"１点目の体罰の件ですけれども、平成２７年度、平成２８年度、両方とも０件が品川区です。本来ですと、本日の文教委員会でお示しする予定でございましたけれども、次回の文教委員会で詳細を説明させていただきたいと思います。例えば、何歳ぐらいの男性あるいは女性の方に声をかけられて、こういう状況でしたという情報提供はしております。児童連れ去り未遂という形での報告は受けておりませんが、何月何日のどの件でございましょうか。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問","question":"先週、下校するときには気をつけるようにという一斉配信があったとお聞きしているので、その辺の事情がもしもわかったらということです。大井町駅のすぐそばであったということですので、もしあとで調べてわかれば、ご報告していただければいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"渡部委員","kind":"意見","question":"もう１点、そういうものが１つ１つ実はやっていかなければならないのかなと、どのように活用していったらいいのだろう。１つは、これをどういうふうにこの先発展させていくかというのは、その辺を自民党・子ども未来として出させてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"こんの委員","kind":"質問・要望","question":"なぜ必要なのか、どういったところで、特に保健のところを考えてみました。向上していただきたいという思いで、現状どういう形で調査をし、質の確保をしているのかというところを調査をしてみたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"その活用と実践を品川区にどう求めていったらいいかということのベースがあるのであれば、そういうものも出せたらいいのではないかと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"松永委員","kind":"質問・要望","question":"もう１つは、これも先ほど共産党もおっしゃったように、教職員の負担が多いので、負担軽減について調査をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"高橋（し）委員","kind":"意見","question":"１８歳選挙権で、新たな道徳との関連になるかと思うのですが、その調査です。多くの側面があるので、そういったくくりで調査というか、研究ができればと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"渡部委員","kind":"意見","question":"特定事件調査の中に入っているので、言葉はちょっと選べないのですけれども、所管事務に上げるのはそのままというのは難しいと思うのですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"先に場所というようになってくると、３０年ぐらい前に逆戻りしてしまうような気がしてすごく気になるので、次回でいいのではないかと思います。調査内容が決まってから視察先を、私たちも一生懸命努力して探しますので、そういう扱いではどうでしょうかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"渡部委員","kind":"意見","question":"今、これだけ内容が出ていますから、二泊三日では足りないぐらいの行政視察が組めるのではないかというような内容でもあります。特段どこでどういうものというよりも、そのような形でお進めいただいて私どもは結構ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/203794?Template=document&Id=4914#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":50729,"voices":119}},{"id":"h29-20170612-5","meetingId":"h29-cm06","date":"2017年6月12日","dateIso":"2017-06-12","committee":"総務委員会","time":"午後１時００分～午後３時１６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"中には文書で出されても、ぜひ直接意見も聞いてほしいといったご要望もありますので、その辺をぜひ検討していただきたいと思うのが２点目です。","respondent":"秋山財政課長、中元広報広聴課長","answer":"新公会計ですけれども、昨年度総務委員会においても、予算書の様式であるとか決算書の様式のほうはお示ししています。区長まで決裁をとらせていただいて回答させていただいているところで、何しろ１カ月を超えないようにというところを心がけて努力しています。今年度は公募型で１００名規模の会場で２回やるということで予定しています。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっとそこを１点お伺いしたい。担当がどこにあるのかというのをお伺いしたいのと、ぜひここのところは明らかにしていってほしいと思うのですが、教えていただきたいのが２つ目です。","respondent":"島袋人権啓発課長、黒田人事課長","answer":"平成３０年からの計画物ですが、こちらのほうを、他区の状況等を調べつつ検討してまいりたいと思っているところです。２点目、何年かに１度ずつ、引き続きこちらのほうも検討してまいりたいと思っているところです。非正規職員の多様な身分というお尋ねですが、例としましては、臨時職員ですとか非常勤職員というものがあろうかと思います。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこをお答えいただきたいのと、セクハラのところは、第三者機関などは全然かかわりがない状況なのでしょうか。約２,５００人対約１,０００人、３人に１人が非正規だということなのですが、あと今後の方向性を簡単にの説明を求めました。","respondent":"島袋人権啓発課長、黒田人事課長","answer":"今年度の予定は、さらに広げて、ＬＧＢＴに特化したものを研修の内容として、今、検討しています。どういった制度になるかというところを注視してまいりたいと考えていますし、民間で行うことによって、まず行政で行わなければならないものについては行政でしっかりとやっていくというようなスタンスで進めてまいりたいと考えています。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どうしたら改善していくのか、前向きに改善していっていただきたいので、そこのところはよろしくお願いします。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"やっぱり一般の方に入っていただいてやるべきことではないかと思うのですが、その辺、ご見解をお聞かせください。さまざまやっておりますが、これも第三者の人がやはり監査としてきちっと見るべきものだと思うのですが、その辺についてご見解の説明を求めました。","respondent":"米田危機管理室長、伊東税務課長、安井選挙管理委員会事務局長、江部監査委員事務局長","answer":"そちらについては、こちらの下にありますように、平成１９年度から防災課のほうに主管が動いております。どれだけの影響が出るのかというところ、そこの部分だけを抜き出すというのは、なかなか難しいというような状況になってあります。我々がこうするというようなことは、法律上、今現在できない形になってあります。先ほど事務事業概要の説明の中でも申し上げましたが、今国会の中で、その中で議選監査の方の取り扱いがちょっと見直されると聞いております。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"質問ではないのですが、やはりきちんと危機管理室でもミサイルの問題も注視していくということは、そういう対応は示すべきではないかと思います。意見だけ言わせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"ＰＰＰ／ＰＦＩ方式ですか、要望活動および折衝等を行う」ということなのですけれども、こちらは企画担当なのです。では、この計画担当というのが、もしかして、国が進める方向に密接に関係しているのかと思ったので、そういうところであるのか、伺いたいのです。","respondent":"柏原企画調整課長","answer":"まず検討しなさいというのが国の考え方ですので、区の考え方として検討を一旦はするというのを、総合計画の中に入れているということです。計画担当のほうで、その考え方に沿った形で、各主管部門のほうでそれを検討するという流れになっているというものです。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"では、そういう計画というのは、その施設が関係する各部署でまず検討されてということで、ここでということではないという理解でよろしいですか。これは要望でいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]},{"id":"topic-02","title":"」を聴取いたします。「品川音頭リニューアルの周知","agenda":"」を聴取いたします。「品川音頭リニューアルの周知","exchanges":[{"speaker":"高橋（伸）委員","kind":"意見","question":"平成２３年度に阪神・淡路の財政状況についてということで、これは東日本、それから熊本地震の財政状況というのもいいのではないか。以上、３点ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"生活できるような賃金にしてほしいといった要求が出ていますけれども、公契約条例のところをやりたいと思っています。３点です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"あくつ副委員長","kind":"確認","question":"ここについて、現在の品川区の制度の状況を確認して、品川区ではどうしていくべきなのかということを確認して調査していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、さっきは品川区がどう進んでいるかというご報告も早くいただきたいと言ったのですけれども、私たちとしてもうまく活用できるのかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"できれば皆さんと一緒に議論しながら、また教えていただければありがたいということを、所管事務調査の一つに加えていただけるとありがたい。希望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"石田（し）委員","kind":"意見","question":"１つは働き方、１つは人権も含めた問題等が、制度のあり方。以上、３点ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"もし内容的なものだったら、申しわけないのですけれどご足労いただいてお話を伺うとか。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"須貝委員","kind":"提案","question":"そういう地域をやはり見て、そしてどのような問題点があるのかということを品川区に活かせるように、私はじっくり勉強すべきではないかと思います。何も２泊３日に限らずとも、１泊でもいいのでしょうし、皆さんどうでしょうかという提案をしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"意見","question":"須貝委員がおっしゃったように、２泊３日にこだわらなくても、身近なところで見られるところも多分たくさんあるのです。２泊３日でそろって行って帰ってくるという考え方は捨てていただいて、もうちょっと違った方法でも効率よくできるのではないかと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"あくつ副委員長","kind":"提案","question":"私はずっとフィルムコミッションについて伺っていたのですが、兵庫というくくりで考えると、そのようなものの視察をすることを提案したいとの意見を述べました。","respondent":"伊藤委員長","answer":"さまざまな観点から検討させていただきまして、７月の委員会で、調査項目等の案を示させていただきたいと思います。以上で本日の予定は全て終了いたしました。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/762881?Template=document&Id=2078#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":42880,"voices":111}},{"id":"h29-20170613-14","meetingId":"h29-cm06","date":"2017年6月13日","dateIso":"2017-06-13","committee":"行財政改革特別委員会","time":"午後１時００分～午後３時０５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件整理しています。","topics":[{"id":"topic-01","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"筒井委員","kind":"質問","question":"やはり１万人ぐらいの差が出ているということで、いま一度そうしたことも踏まえて人口の推計を取り直したほうがいいのではないかということが１点と、この点はいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"現状は推計と同じか、人口推計については、今年度この推計については新たなちょっと検討ということで今入っているものです。今後の、これは平成２７年を基準にやっておりますので、皆さんが共通でわかるような示し方というのは考えていきたいというふうに思ってあります。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"設置に当たっては、計画案の提出と、実際の相談所の開設はいつごろを予定しているのか伺いたいと思います。それがどうなるのかをお伺いしたいのと同時に、身近な品川区として、品川区としてはどのように考えているのか伺いたいと思います。","respondent":"高山児童相談所移管担当課長","answer":"計画案の策定ということが必要でございまして、それについては現在進めておりますモデル的確認実施区における知見のフィードバックなどを待って。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとそういうふうに聞こえてしまったのですが、もう少しあれば伺いたいと思います。これは全体を理解するために伺いたいのですけれども、ちょっとかみ砕いてご説明いただきたいのと、そこら辺をあわせてお伺いします。","respondent":"高山児童相談所移管担当課長、柏原企画調整課長","answer":"私のほうからは、委員お尋ねの１点目、児童相談所推進委員会の昨年度の成果といいますか、取り組みです。モデル的確認実施区というところを入口に、平成２９年度につきましては、さまざま検討するべき事項がありますので。大きく２点ご質問いただきましたが、後半のほうのご質問を先にお答えといいますか、ご説明したいと思います。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"地域共生社会のほうで１点だけお伺いしますが、先ほど若干説明があったのですが、市町村による包括的支援体制の制度化が平成２９年度だと。共生型サービスの創設と書いてあるのですけれども、ちょっとそこら辺をお伺いしたいと思います。","respondent":"柏原企画調整課長、大串福祉計画課長","answer":"それを将来的に継続的にというところで申しますと、これは継続されていくのがあるべき姿だろうというようなところがありますので、子育てであったり。これは本年２月に出て、区としての取り組みというか認識といったところになろうかと思いますけれども、着実に行ってきたところです。","id":"exchange-004"},{"speaker":"渡部委員","kind":"質問・要望","question":"質問というかというところでお伺いしたいのですけれども、横須賀児童相談所ですとか、比較的近隣で先駆的な取り組みを行っているところもあります。子育てがどうなっていくのかですとか、これは要望だけさせていただいて、今お答えがあればいただきたい。","respondent":"鈴木（ひ）委員長","answer":"今日は概要説明をしていただいていますけれども、この後にこれから先の１年間に、この概要説明の後にそういう時間を設けたいと考えています。","id":"exchange-005"},{"speaker":"渡部委員","kind":"質問・要望","question":"安心いたしましたというか、承知いたしました。最後に要望とかという形にしていただかないと、そういうのもありまして、今ちょっと確認しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"意見","question":"児童相談所のところで、今現在の区が課題と考えているところ、やはり虐待の相談件数なんかもすごく増えてきていると思うのですね。そういった部分で、区として今課題と考えていることというのは何かというのを概要ですので、大まかでいいですのでの説明を求めました。","respondent":"高山児童相談所移管担当課長","answer":"そういったものも含めますと、児童相談所を設置するに当たっては、そういった部分も穏やかに進めていかなければならないということが一つあります。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問","question":"今ご説明いただいたとおり人材が本当に大切かなと思うのですけれども、１,０００m2以上ある土地を確保して、また相談、一時保護、こういうことを進めていくわけですけれども、どれぐらいの規模の人員設計になっていくのか。","respondent":"高山児童相談所移管担当課長","answer":"ちょっと今日はこういった委員会の場ですので、相談にかかわる人員と保護所を運営するのに必要な人員が必要となってくるということで考えております。必要数については、所要人員につきましては、今後積み上げてまいりたいというふうに考えております。","id":"exchange-008"},{"speaker":"松永委員","kind":"確認","question":"ちょっと確認が２点ありまして、まず一つは、東京都はその部分を公園の拡張ということで考えているということでよろしかったのか確認をお願いします。","respondent":"柏原企画調整課長、立川経理課長","answer":"私から前段のご質問２点についてお答えいたします。現段階では特に何かという具体案はないのですけれども、ここについてはもう少し有効的な活用について検討したいというふうに思ってあります。３階のプラッツァにあります噴水の件ですが、こちらは東日本大震災以降、節電・節水の観点から運用を停止しています。","id":"exchange-009"},{"speaker":"松永委員","kind":"質問・要望","question":"最後の噴水なのですけれども、やはり結構人目につく場所なので、何か、例えばオリンピック前までに何とかするとか、何か考えていただきたい。もし、壊す費用がかかるのであれば仕方がないかなとは思うのですけれども、ぜひ要望ですので、何か改革をお願いいたします。","respondent":"立川経理課長","answer":"今後の運用につきましては、いろいろな観点から研究してまいりたいなというふうに考えております。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと資料について伺いたいのですけれども、建築学的な構造上の理由からももちませんと、ちょっと教えていただきたいというのが１点です。品川区としてはこの土地についてはどのように捉えているのか、活用の考えはあるのかちょっと伺いたいのが２点目です。","respondent":"柏原企画調整課長","answer":"そういう話ではなくて、建物の寿命であったりだとか、そういったところをよく見ながら考えなければいけないだろうです。そういったところもいろいろな面で総合的に考える必要はあるだろうという考えでいるというものです。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"都の見解等を伺いながらということですけれども、報告していただきたいというふうに要望したいと思います。区としては、この状況をどう考えているのか、現在の見通しだけちょっとお伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"それを踏まえて２点質問なのですけれども、あと何がどのように不十分と区としては考えてこのような記述にしたのか伺いたいというのが１点です。","respondent":"中村都市計画課長","answer":"まだ実施がなされると、そういった認識はなくて、あくまで案の段階であるという認識です。区民に対して理解を深めるような説明会をさらに行っていただきたいというふうに考えておりますし、品川区にはどういった対応を国がしてくれるのか。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと最初の質問のほうの説明が不十分というところで、内容そのものについて理解されていないと感じているというのはわかったのですけれども、その後ちょっと、区へも同じような意見が寄せられているみたいな答弁の内容がちょっとわからなかったので。","respondent":"中村都市計画課長","answer":"次に、あるいは航空機の墜落ですとか、そしてそれを国のほうでは安全対策や騒音対策をしっかりやっていきますということで説明をしています。そういったところが、主に区民の皆様からいただく意見で、区が認識しています。","id":"exchange-014"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"私はそこまで児童相談所の問題について自分で研究したことがないものですから、この中に一時保護所というのですかね。その上で、実はモデル地域になっているところは幾つもあるものですから、もし視察等をさせていただければ大変ありがたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"渡部委員","kind":"質問・要望","question":"それに近い、多分話を聞いてもなかなかいい話が出てこなかったら嫌だななどというのもちょっと思ったものですから、それはそれなのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"横山委員","kind":"質問・要望","question":"先ほど他の委員のご質問にもあったのですが、例えば虐待などの相談の件数の増加というところが最近課題になっているかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問・要望","question":"どういったものを、どういったことを想定しているのか、このポンチ絵以上のものを教えていただければなと考えています。少なくとも現状の部分で、何かフロー図でわかるようなものがあるのか、そういったものがあれば提示をお願いしたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"安藤委員","kind":"提案","question":"暫定活用地も含めた全体像がわかるような資料を提出していただきたいというふうに要望したいと思います。直接の責任者は国ですから、ですから、これも提案したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問・要望","question":"私から、今回実現の方向性に向かっていると思うのですけれども、区の希望というのをちょっとお聞きしたいなということがまず１点あります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"大倉委員","kind":"意見","question":"この後どういうふうに、そういうところの、何か具体的にこれについてというのがあるとありがたいかなと思っています。庁舎の修繕計画とかも、予算とか金額とかがあるともう少しわかりやすいのかなというところで、その辺も出していただければいいかなと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"若林委員","kind":"質問・要望","question":"会派からも今要望等させていただきましたけれども、視察に行くということを要望させていただいて進めていただきたいのですが。これはどうなのですか、皆さん、議会運営委員会でもこの話は出ていなかった。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/172349?Template=document&Id=6030#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":42110,"voices":90}},{"id":"h29-20170614-18","meetingId":"h29-cm06","date":"2017年6月14日","dateIso":"2017-06-14","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後１時００分～午後３時２０分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件整理しています。","topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"新妻委員","kind":"確認","question":"１点、大井ホッケー競技場の整備についてというところで、確認します。来年１月頃から工事に入るということですが、これは、公園内には入れなくなるということでよろしいか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"先ほどご説明しました来年１月頃からの工事につきましては、あくまでもメインピッチの第一球技場だけの話しです。あくまで大会開催期間中に、セキュリティー等の関係で公園内が閉鎖になるかと思われます、という旨を申し上げました。","id":"exchange-001"},{"speaker":"本多委員","kind":"意見","question":"本日が１１３６日前なので、１０００日前は１０月末ごろになると思うのですが、資料に書かれている以外の１０００前フェスタについて現時点で固まっていることがあれば概要をお知らせくださいとの意見を述べました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"フェスタにつきましては、これまで平成２６年から続けてまいりました。１０００日前フェスタと、１０月２８日ジャストでやるわけではございませんが、９月９日にフェスタという位置づけでやらせていただくものです。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問・要望","question":"最後に１点、意見だけ言わせてください。それぞれ教室を５回開催予定なのですが、こういったことを充実していただきたいと思うのですが、意見だけ述べます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"お伺いいたしますけれども、区の認識を伺いたいのと、準備状況について伺いたいと思います。具体的な事業について、現在のところの位置づけや方向性について、どういう状況なのかお伺いしたいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"それから今後、大会について様々な問題についても取り組んでいくと、大会組織委員会からはそういう話も聞いています。今の性的差別の問題等も、大会組織委員会と歩調を合わせて、品川区にできることを全てやっていきたいと考えています。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"とりわけ品川区自身は、開催の地元自治体となるわけですから、より一層の役割が、私は期待されると思うのです。先ほど歩調を合わせるというご答弁がありましたが、現在の進捗状況と、今後の方向性についても伺いたいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"オリンピック自体の考え方については、連携しながら、進めていきたいと思います。開催自治体としても、成功に向けて大会組織委員会等と協力をしながら、取り組んでいきたいと考えています。","id":"exchange-005"},{"speaker":"中塚委員","kind":"提案","question":"３年後ということで、進めてほしいと求めましたけれども、この中でもしっかりと議論をしていきたいと提案したいと思います。差別の克服や理解の促進などの事業を具体化するための準備を、私は今から始めるべきだと思いますけれども、改めてお伺いしたいと思いますとの意見を述べました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"人権の課題といたしましては、現在所管は人権啓発課ということで、具体的に取り組んでいるところです。いつでも」という理念のもとに推進してきたところですので、そういったところも踏まえつつ、今後も取り組んでいきたいと考えています。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはりスポーツには、ＬＧＢＴを含めあらゆる差別をなくす力を持っていると思います。その中で東京大会を開催して、誰もが祝福される大会として迎えられるように、今から準備を進めることを求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"ですから大会組織委員会として進んでいることがあると思うのですけれど、そもそもの大会組織委員会の考え方なのかお聞きいたします。なので、ぜひそういった機運を、オリンピック・パラリンピック推進特別委員会から盛り上げていってほしいと求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"大会組織委員会の考え方ですが、今回の大会は「全員が自己ベスト」「多様性と調和」「未来への継承」ということがコンセプトにあります。どんな方でも様々な形で、そうした組織委員会の理念も踏まえつつ、区としても独自に検討してまいりたいと思ってあります。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"提案","question":"区からもきちんと確認作業をして、そういうことをどうしていこうと思われているのか、一つお聞きしたい。そういうことをどういうふうにしていけばいいか、そういうことも取り組んでみたいと思っているかどうか、というところの説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"１点目の練習会場の件ですが、委員ご指摘の立候補ファイル上の練習会場につきましては、一旦白紙に戻すと言っておりました。そういったアイデアにつきましては、ともに協力して様々やっていけたらと思いますので、お話しいただければと考えているところです。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"きょうから１年始まるわけですから、改めてお伺いしたいんですけれども、品川区の立ち位置といいますか。資料のことだけならばいいのですけれども、連携はとれているのか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そうしたところで東京都の幹部、あるいは大会組織委員会の幹部より、情報提供をしてくれることもあります。そうした意味で、連携はとれているところです。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"質問","question":"これはどのように使うのかということと、あと今後様々なご案内とかこういうチラシをつくる際に、同じような形で入れていくのかどうか。位置づけというか、どういう考えで入れているのか、の説明を求めました。","respondent":"中山障害者福祉課長","answer":"ホームページなどに載せるとき、今は品川区のホームページも音声対応になっておりますので、視覚障害の方が情報を取りやすくなっている状況です。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問・要望","question":"ホッケー競技場の整備費が４８億円と記載されておりますけれども、この内訳というのはわかりますでしょうか。そして、ビーチバレーボールの会場の資料はないのか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"２点目の４８億円の内訳ですが、区として把握してございません。それからビーチバレーボールの会場につきましては、仮設ということで聞いておりまして、まだ資料は出ておりません。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"それを確認させていただきたいということです。ほかの会場についても、まだ資料はないということで、よろしいか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"委員ご指摘のとおりです。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"伺いたいのは、解決が必要な事柄とはどんなことだとお考えか、この点を伺いたいと思います。日常的なスポーツの振興のためにも、大事だと私は思うのですけれど、この点について現状をお伺いしたいと思います。","respondent":"池田スポーツ推進課長","answer":"ここはどんな景色かとか、今は海のそばだから風が吹いているというように説明しながら、ウオーキングを楽しんでいる姿も見受けられました。今後も、「いつでも、どこでも、誰でも」のフレーズがかなえられるよう、事業を進めていくことが最良であると思っているところです。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"障害を持っている方にお話を伺うと、様々なスポーツをする環境をもっと整えてほしいという声をよく伺うのですね。障害がある方が品川区でできるスポーツは何種目あるのか、これを広げていくにはどういうことが必要なのか、基本的な考えを伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"大人につきましては、現在のところございませんけれど、１８歳以下の方については、そういった形で支援をしています。それこそ障害をお持ちの方ができるスポーツを皆さん考えているところですので、たくさんの種類ということしかお答えできません。","id":"exchange-015"},{"speaker":"中塚委員","kind":"確認","question":"東京２０２０大会のパラリンピックについて、５月１１日にパラリンピックの準備状況を確認するため、報道がありました。こうした宿泊施設、オリンピック・パラリンピックに向けてしっかり持っていくということが必要ではないかと思うのですけれども、如何か尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"今の質問は、バリアフリーに関することで、昨年の委員会の中でも、バリアフリーについては担当課長に出ていただいて質疑しています。きょうは総括的な質問ということで、個別の問題はまた別の機会にするべきだと、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"一言だけよろしいでしょうか。ぜひ客室の確保や料金の設定など、幅広く障害者スポーツの振興に向けて、取り組んでいただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問・要望","question":"いながわ委員だったでしょうか、もっと全体的にみんなに理解していただきたいというのがあって、今年７月はデフリンピックの年です。もし何かお考えとかあれば、伺いたいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"委員会として取り上げるかは、正副委員長間で話し合わせてほしいと求めましたので、それは後日、また検討します。","respondent":"木村委員長、小川オリンピック・パラリンピック準備課長","answer":"ただいまのご意見ですけれど、正副委員長で検討させていただきたいと思います。なければ以上で、(2)障害者スポーツの推進に関することの、概要説明を終了いたします。上の参画プログラムと違い、公式スポンサー以外の企業等が実施する事業も対象となっているというものです。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"この文化プログラムとはどういうものかということを、もう少しご説明いただきたいと思い、質問させてほしいと求めました。そこをオリンピズムの根本原則に沿って、文化プログラムとは何か、ご説明ほしいと求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"オリンピック期間中に、大会組織委員会が毎回ＩＯＣの理事会にかけて事前に承認を得るということは、物理的に大変難しいということを聞いてあります。オリンピックが終わった後も、継続的に文化が根強く発信していけるようにという思いが込められたものだと、理解しています。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が伺ったのは、なぜ文化プログラムが位置づけられているのか、どう理解しているのか伺いたかったのです。単なる手続とか、オリンピックを通じて文化プログラムはむしろとても大事に位置づけてきたわけですから、現在の認識をご説明ほしいと求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そうした部分で全て品川区の文化ということを、このオリンピックを機会に魅力を発信し、品川区全体の魅力として位置づけていきたいという思いです。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問","question":"課長の答弁を伺って、どういう形でやっていきたいと思っているのか、教えていただけますか。","respondent":"鈴木文化観光課長","answer":"現在、実際に区民の方、また区内の団体に取り組んでいただくための準備作業を、連携して行っているところです。文化活動については区としても支援しておりますので、またあわせて支援をしながら、今後もしっかり続けていきたいと考えております。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問・要望","question":"大枠の確認です。ＩＯＣ理事会には当然、承認を求めるのでしょうけれども、実務的なことは品川区がやっていくのかということの確認が一つです。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"２点目の内容ですが、大変幅広い内容です。既にやっている品川区の文化的なイベントとあわせ、新しいものも拾い上げていけるように、品川区としては努力していきたいと考えています。","id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"教えていただきたいのですが、品川区は会場所在の地方公共団体で、申請をして公認プログラムマークがあると。区はオリンピック憲章に基づいてやるということですが、このマークの仕分けというのは、どういうふうに考えるべきか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"例えば大会組織委員会ですとか、国が、きちっと責任を持って認定するべきだと考えています。このマークを提供したいと考えてございまして、しながわ文化プログラムというふうに位置づけ、品川区を挙げて盛り上げていきたいという思いです。","id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"意見","question":"区がその数を把握して一緒になってやりましょうというほうが、もっと簡易に、ハードルが下がって、やる方もいいだろうと思う。今の答弁で大体わかったのですけれど、そう理解していて、いいのかどうかとの意見を述べました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"組織委員会から東京２０２０参画プログラムのご案内があった時点から、こちらの申請につきましては、区として強く申し入れているところです。","id":"exchange-026"},{"speaker":"いながわ委員","kind":"質問","question":"私もある小学校でこういうものをやっているのですかと聞いたら、いや、体験することが障害者スポーツに対する一番の経験になると思うのです。では、選ばれなかったところはどうだったのですかと。","respondent":"熊谷指導課長","answer":"そして義務教育学校は、もちろん本区の１校ということになっています。私としてははっきり言って都内の６２市区町村の中で、オリンピック・パラリンピック教育を一番やっているのが品川区だと自負しております。","id":"exchange-027"},{"speaker":"伊藤委員","kind":"確認","question":"確認といいましょうか、大枠の質問ですけれど、表題が「オリンピック・パラリンピック教育」で、目標を３つ挙げられております。もちろん正しいことでやっていくべきですけれども、オリンピックが終わった後どうするのかということについても、お考えの説明を求めました。","respondent":"熊谷指導課長","answer":"２０２０年が終わったら終わりではなく、共生協調社会の形成、地域貢献ということもできるような大人になっていってほしいと考えています。","id":"exchange-028"},{"speaker":"伊藤委員","kind":"確認","question":"それは当然わかっているのですけれど、私が確認したいのは、こういう個々の具体的な事業がありますよね、資料にあるような。だから３５時間程度のオリンピック・パラリンピック学習をどう展開していくのかとか、どうするのですかということをお伺いしたいので。","respondent":"熊谷指導課長","answer":"３５時間程度のオリンピック・パラリンピック学習をということでありますけれども、これも非常に大変難しいところであります。さらに地域のこと、実際に大会が終了した後も、これは子どもたちの心の中に伝えていけるような内容にしてあると思っています。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"オリンピック・パラリンピック教育について、冒頭、歴史や意義を正しく理解できるようにというご説明がありました。子どもたちに知る機会をぜひつくっていただきたいと思うのですけれど、どのように位置づけているのか、伺いたいと思います。","respondent":"熊谷指導課長","answer":"昨年度の４月に配っているのですけれども、そういったことも含めてオリンピック憲章に基づいて、記載されています。特に聖火リレーを通じて１９６４年の大会では意味づけられていますので、そうしたことを通じて、子どもたちに伝えていきたいと考えております。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"オリンピックの目的そのものが平和の祭典ですから、発達に沿った学習教材を使って、進めてほしいと求めました。スポーツを人類の調和のとれた発展に役立てるとされておりますので、子どもたちの学年に沿った教育を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問・要望","question":"どういう思いというか、私も自分で体験したことについてお伺いしたいので、大枠で教えてほしいと求めました。２０２０年オリンピック・パラリンピックが終わった後という質問が出てご答弁いただいたのですけれど、その辺に関しては、教えていただきたいです。","respondent":"熊谷指導課長、小川オリンピック・パラリンピック準備課長","answer":"本当に協調というか、応援というか、人は１人では生きられないなというのをすごく感じる競技だと思っています。わからないことを知る、そして障害者理解において、違いを知るということの大切さということを伝えていきたいと思います。現在も教育委員会と私どもの課とは大変連携がとれているところで、他区からも羨望の目で見られているところです。","id":"exchange-032"},{"speaker":"たけうち委員","kind":"意見","question":"学びながら、あと３年ですけれど、そうするとでこのオリンピック・パラリンピック教育をしたことが生きてくるのではないかと思います。一人でも多くの方が参加し、できれば学校単位でも参加していくということがあるかと思うのですけれど、その辺のご感想をお願いしますとの意見を述べました。","respondent":"熊谷指導課長","answer":"それを考えると、文化に関しては４つのテーマの一つに入っているのですが、またそれで自分たちがつくっていくということも大事だと思います。学年として、これから子どもたち、学校での文化プログラムに参加ということも検討してまいりたいと思います。","id":"exchange-033"},{"speaker":"たけうち委員","kind":"質問・要望","question":"３９年の東京オリンピックのときは一応生まれていましたけれども、私は２回経験できる、私はぜひ参加させてほしいと求めました。ぜひ藤原委員も含めて参加していただくのがいいのではないかと、これは意見として終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それで、私がお伺いしたいのは、せっかくここまでやってきたのであれば、例えば今、この教育を受けた子どもが、大学２年生ぐらいまでいきますか。お考えの説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"大会組織委員会だけではできません、早々と接触し、区としてもアピールしています。区といたしましては引き続きそうした思いを伝えていきたいと考えています。","id":"exchange-035"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今、いい関係にあると思いますので、ぜひ一緒にやってほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-02","title":"しながわ文化プログラム","agenda":"しながわ文化プログラム","exchanges":[{"speaker":"いながわ委員","kind":"確認","question":"しながわ」というのは、それともここは日本ですから、日本語を理解してくださいということでいくのかどうかという思いがあります。しながわ」というのもあっていいのではないかと思いますけれど、いかがか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"現在、しながわ文化プログラムにつきましては、このマークでまず行かせていただきたいと考えています。しながわ」と連携して、このロゴマークを作成したわけですが、まずこちらを浸透させていきたいと考えています。","id":"exchange-037"},{"speaker":"つる委員","kind":"質問","question":"今、いながわ委員からもありましたが、ロゴマークの決定過程の説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"この事業を制度設計いたしますとき、まず、せっかく「わ！しながわ文化プログラムというものを全面に出したいということから、下につけて、このような形で区として決定したものです。","id":"exchange-038"},{"speaker":"つる委員","kind":"提案","question":"３年あるわけですから、今後変わらないというふうになるかもしれないですけれど、品川区独自の文化プログラムですから幅広く様々できると思うのです。そうしたことから、やはり工夫が必要ではないかと思うのですが、今後そういう余地があるかどうかも含めて、の説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そうした中で、まずはこちらのマークで出発させていただきたい。今、いただきましたご意見につきましては、今後の参考にさせていただきたいと思います。","id":"exchange-039"},{"speaker":"つる委員","kind":"質問","question":"そうですかということになるのでは、それでこういうふうになったというのであれば、なるほどそういう意識を持ってやっているのだなとわかります。そういったところも含めて、せっかくいいことをやっていくわけですので、お伝えほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"石田（秀）委員","kind":"意見","question":"しながわ」だと、私は思っていて、そこに文化プログラムというものをつけてやるということは、いかがなものかと思っています。それだけ言っておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問","question":"そこを伺いたいのです。少し手を加えて使うということが、果たしてよいのかと率直に疑問に思うのですけれど、その点だけ伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"こちらのロゴマークに、例えば２０２０ですとか、オリンピック・パラリンピックという文言を使うと問題になります。ただ、文化プログラムという単語自体に知的財産権はございませんので、しながわ文化プログラムという表現については何ら問題もございません。","id":"exchange-042"},{"speaker":"藤原委員","kind":"質問","question":"だから、やはりこのロゴマークもいいかもしれませんけれども、本当にこのロゴで満足されているのでしょうか。本当に１００％満足してやっているのですという思いならいいですけれども、その辺について、どう思われますか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ただ、組織的にこういったことで決定させていただきましたので、まずこれで出発させていただきたいと思います。委員ご指摘のご意見につきましては、貴重なご意見として承りたいと考えています。","id":"exchange-043"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"やはり議論を深める必要があると思いますので、今後の委員会運営の中に反映してほしいと求めました。オリンピックとＬＧＢＴについて話を詳しく伺って、議論を深めることができたらと思いますので、正副委員長でご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"これは総務委員会、教育委員会も絡んでまいります。この場で内容的に、視察に行きますという部分でもお答えはしにくい状況ですので、その辺ご理解ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん、この場で返事を求めているのでなく、正副委員長でご検討いただきたいという趣旨です。様々かかわるので、特別委員会が一番ふさわしいのではないかと思いますので、ご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"石田（秀）委員","kind":"提案","question":"そこの視察にどういうふうにやったらこういうふうになるのだというのがわかってきたら、提案しますので、機運醸成にはおもしろいかなと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/645888?Template=document&Id=6516#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":44475,"voices":141}},{"id":"h29-20170615-10","meetingId":"h29-cm06","date":"2017年6月15日","dateIso":"2017-06-15","committee":"議会運営委員会","time":"午後１時００分～午後２時０７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"議長会への要望事項","agenda":"議長会への要望事項","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"活用について国の補助制度の拡充を求める要望というのは、我々はこれを４点書かせていただいて、ここへ出してこなかった。そこの不安を払拭していただく努力を国にしっかり求めていくべきだろうと思っておりまして、羽田空港については要望を出させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"塚本委員","kind":"質問・要望","question":"高齢者施設に関する要望ということで、引き続きの要望として、４つ目が高齢者の住まい確保のための空き家利用といった内容の要望です。３点目は、国・都に強く要望していきたい、０～２歳児を含む幼児教育の完全無償化というところでの要望をさせていただいておるところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"３０人学級ということで、子どもの教育を充実させるという点での３０人学級は、基本的な要望だと思いますので出しました。どうしても交付金があるということで、きちんとこういう交付金制度はやめると、そういう要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"保育園の待機児童はずっと課題になっているので、これは質と量とともに改善をしなければいけないということで、要望に出させていただきました。オリンピック・パラリンピックの開催に向けた環境整備等については、喫緊の課題だということで、要望を出させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区は独自に小中一貫教育、むだな経費とむだな時間は省くべきだと考えまして、このように要望書を提出していただくということを決めました。それを支える人材の処遇を改善しないと解決することはできないのではないかと思いまして、これを国と東京都に要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"表現が定員拡大にならないので、そういうことではないのではないかと思ったので、その辺の考え方を伺いたいと思います。これとこれとこれをしなさいという具体的な要望で、そこの点についてはどうなのかという、この２点を伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"必ずいろいろ要望なり、要望書なり、まず最初は区民だと。地域事情も理解をしてほしい、東京都に要望を上げてほしいということで、こういう案文にしたという理解をしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"たけうち委員","kind":"質問・要望","question":"都に求めているわけでして、南委員おっしゃったように、大分弾力化をできるところまでやった経緯があります。区の単費だけではなくて、国や都もそういうものに対しても支援してくださいと、そういう意味です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"南委員","kind":"確認","question":"そういうことになるのだろうと思うのですけれども、その辺のことをまず１点、一番最初に確認をしておきたいと思います。特に小さい子どもの年齢になればなるほど命の問題ですから、やはり必要な職員配置、それが定数という形で示されるわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"だから今、多くの皆さんの求めていることは、保育園の増設です。そういうところを踏まえて要望を上げていくということが大事なのではないかと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"議長会要望をやりましょうと、どうぞそれを見ていただければと、各区の要望は全部あります。だから、そういうこともきちんとご理解をして提出をされてきたのですかということを聞きたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"ですから質問をさせていただいているわけであって、別にそのことは何も不自然なことではないと思います。私が伺いたかったのは、どうも今の説明では、そういう経過があるというふうに理解していいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"渡部委員長","kind":"確認","question":"過去の決め方も私も議運の委員で出ておりましたが、やはり品川区としてこれは必要なのではないかというものに関して、最終的には議長のご判断を仰ぐ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"要望事項の１つの文言に対して、提出を受けた機関は、これが品川区議会の総意なのだという受けとめを当然するわけです。ですから、そういうことで温度差がこんなに違うものを１つのところにまとめて出すということは、それはどうか尋ねました。","respondent":"渡部委員長","answer":"従来どおりの進め方を、従来の手続きを踏んで説明していますので、特段今年初めてということを今やっているわけでもございません。きっと南委員以外は皆さんそのようなご認識だと思われます。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、失礼な言い方はやめてほしいと求めました。石田委員が、昨年は要望に上がらなかったので、品川区議会として自民党会派から上げたという、そのことはそういうふうに受けとめております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"どういう文言修正があった、その書類は読んだのですかとさっき聞いたのに何も触れられていないから、今みたいな発言はないと思うのですよ。議長もそれは提出をしてくれたけれども、議長会の中で、その要望を国なり東京都なりに上げるということには至らなかった。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"国、東京都に要望は届かなかったけれども、やはりこの部分については言っていかなくてはならないだろうということで我々は要望をさせていただいたと。だから、読んだのか、読んでいないのかも含めて答えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"ですから…。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"南委員","kind":"意見","question":"手を挙げて言うように、そういう議会にしましょうよとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"先ほど石田委員がおっしゃったとおり、私もそういうふうに認識をして伺っておりました。意思としてというところで出すべきだと思いますので、これはこれとして１つの条件闘争という、そういうふうに考えて発言をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"したがって、赤ペンも入れていないし、コピーもしていない、そういうことであります。よろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"意見","question":"飯沼委員が３年もいらっしゃったからということなのだけれども、議長が全てここで話をできるわけではなくて、資料を事務局にあるので読んでくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"意見","question":"そのためにはこういう文書がいいのではないかということでやっている。会派としてやれるわけであって、そういうことをやってもいないで、私はやっていないからどうだみたいな発言はおやめになったほうがいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"そこのところはわかってほしいと求めました。議長を経験したどうのこうのということを同じことを繰り返すのは、やめて、そして建設的な話し合いをしていくべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"もう１点なのですが、共産党は要望に挙げています４点目「特養ホームの介護報酬を元にもどすこと」と書いてあるのですけれども、年間赤字が出てくる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-02","title":"第２回議会報告会報告書","agenda":"第２回議会報告会報告書","exchanges":[{"speaker":"南委員","kind":"意見","question":"そのときは、開会時間が若干ずれるということになっていくことも予想されるのではないかと思うのですけれども、その辺はどうなのか。どういうふうに、そういう制限をするものでもないのかと思うので、どんなふうに考えていらっしゃるのかとの意見を述べました。","respondent":"久保田区議会事務局長","answer":"機器の設置ですけれども、委員会開会前に時間に余裕をもって来ていただければ、委員会開会のところから設置をしてお使いいただけます。事務局としましては、できるだけぎりぎりで来ましても、開会時間に影響のないように、設置は急いで行いたいと思ってあります。","id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"そのときに、設置にある程度の時間がかかるかもしれないので、できるだけお早めにみたいな、そんなことは案内してはいけないのか尋ねました。","respondent":"久保田区議会事務局長","answer":"ホームページには、時間がかかるというか、できるだけ早く来ていただければということのご案内はする予定です。わかりやすく使いやすいということをモットーで今までやってありますので、そういった工夫は当然ながらやっていきます。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/706163?Template=document&Id=5228#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":22395,"voices":74}},{"id":"h29-20170705-10","meetingId":"h29-cm07","date":"2017年7月5日","dateIso":"2017-07-05","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時４９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/706163?Template=document&Id=5230#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":6879,"voices":29}},{"id":"h29-20170706-10","meetingId":"h29-cm07","date":"2017年7月6日","dateIso":"2017-07-06","committee":"議会運営委員会","time":"午前１１時００分～午前１１時０２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/706163?Template=document&Id=5232#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":880,"voices":7}},{"id":"h29-20170710-6","meetingId":"h29-cm07","date":"2017年7月10日","dateIso":"2017-07-10","committee":"区民委員会","time":"午前１０時００分～午前１１時０７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"臨海部広域斎場組合の火葬料の改定","agenda":"臨海部広域斎場組合の火葬料の改定","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"臨海部広域斎場組合議会において、８月に開かれますけれども、品川区はこの提案について賛成をするのか。品川区に照らしたときに幾らになるのか、その金額を教えてほしいと求めました。","respondent":"提坂戸籍住民課長","answer":"８月の組合議会に提案させていただいて、品川区は賛成する予定ということで事前に区長にも報告しています。品川区も大体それぐらいの金額になります。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"５区でいうと３,０００万円強、こうした住民への負担を転嫁しないと安定した運営が維持できないということなのか伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"ほかの４区の考え方も基本的には似たような形で区長のコメントをいただいているところでございまして、利用する方、利用しない方に。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまりはどうして今回の改定を行うのか、改めてなぜ住民に負担を求めるのか、ご説明ほしいと求めました。要するに５区全体が３,０００万円の負担をしないと赤字になってしまうというのがよくわからないので、ここは詳しくご説明ほしいと求めました。","respondent":"提坂戸籍住民課長","answer":"利用する方、それから先ほどほかの斎場との利用料金比較ということでご説明しましたけれども、その辺の火葬料の原価分については足りない分。先ほどもご説明しましたが、開設後１３年を経過してまいりますので、２０年ずっと増えていくという想定が出ております。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"私はこうした施設は社会的に必要なものだと思いますので、それを利用する、しないで住民に負担を求めるというのは間違った考えだと思います。","respondent":"提坂戸籍住民課長","answer":"区民の皆様に公平に住民税をご負担いただいているのですが、その中で臨海斎場をご利用しない方も７割近くいらっしゃるわけです。その辺を利用する方に公平にご負担いただきたいということで、組合議会のほうでは使用料改定についてはご賛成いただきたいと考えています。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"５区全体で３,０００万円程度の赤字だと、これは当然自治体が負担すべき役割だと思います。なので、使用する、しないで住民の負担を求めるという考えは改めていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"それと、具体的に人件費の部分はこれこれこういう方たちの人件費がどう上がったから、上がるからということも説明していただけますか。具体的にの説明を求めました。","respondent":"提坂戸籍住民課長","answer":"ごめんなさい、その辺の負担増が見込まれるところがあるので、平成２９年度の金額が今ちょっと出ていないのですが。失礼いたしました、前回の改定のときと比べますと、３５０万円程度増になってあります。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問・要望","question":"なぜこういうふうに伺うかというと、基本的には火葬するわけですから、誰もが火葬するわけですから。だけれども、そういう思いがあるから伺っているので、ちょっと具体的に改めて教えていただけますか。","respondent":"提坂戸籍住民課長、堀越地域振興部長","answer":"全体の使用料および手数料に対する施設整備費とかその辺の歳出と比較しますと全体で１億円ぐらい赤字になるのですね。もちろん委託の部分、先ほど人件費とご説明しましたけれども、ある意味区内の利用の方をある程度誘導するという考え方だと思います。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問・要望","question":"この２つ、電気料とか人件費という形で伺ったのですけれども、やはり議員ですからその辺きちんと説明をしなくてはいけない。それが議員の仕事の一つでもあるわけですから、やはりこの資料を出すときにその辺のことをしっかりきちんと書いていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"使っていない方が６８％いるから、そこに対してやはり使っている側の方の負担を増やそうという考え方というのは、やはりちょっとよくわかりにくい。","respondent":"提坂戸籍住民課長、堀越地域振興部長","answer":"臨海斎場を利用していただく方については、それに見合った３年ごとの利用料の見直しということでご理解いただきたいと考えています。ちょっと今説明させていただいたのですが、施設の使用料の考え方というのはいろいろあると思うのです。その中で、その辺はちょっと説明がうまくなくて申し訳ございませんが、そのようにご理解をいただければと思ってあります。","id":"exchange-009"}]},{"id":"topic-02","title":"東京２０２０公認文化オリンピアード「品川薪能」の開催","agenda":"東京２０２０公認文化オリンピアード「品川薪能」の開催","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"そういう公園の占有のこととか、どういうふうに主催者が思う、そこはちょっときちんと説明をいただきたいというのが大きな１点です。","respondent":"鈴木文化観光課長","answer":"次の日に撤収という３日間で済むということで、電源の設備だとか使用については協議をしたという中で、今回の実施にこぎつけたところです。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひダイナミックに魅力を持って進めていただきたいのと、協力を得ながら進めていただきたいということと、そういうものを今後積み重ねる中で努力を続けていただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"始まる本当に一、二時間前とかに曇ってきたなというときに、どこに問い合わせればいいのかというのがすぐにわかるように。ホームページの一番トップにあるとか連絡先がどこかすぐにわかるようにということとか、その周知などについて伺いたいと思うのですけれども。","respondent":"鈴木文化観光課長","answer":"基本的にはチケットを文化振興事業団、お買い上げいただいて実際来ていただく方には当然もう少ししっかりとしたお知らせはご案内する予定です。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"予算額が５００万円ですけれども、これは具体的にどういう形か教えていただければ。","respondent":"鈴木文化観光課長","answer":"今回の薪能は、総事業費が約１,１００万円ほどになります。はチケットの売上げと喜多能楽堂の負担で約６００万円程度、区も共催で実施するという、そのスキームを使って実施するものです。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"区外の方や外国人にも多く鑑賞してもらいたいということなのですが、区が税金で５００万円出すことですよね。その辺はこれからも文化という意味においては区外の方にもお金を使っていってもいいではないかという考えを基本的にしていくのか尋ねました。","respondent":"鈴木文化観光課長","answer":"文化に関してはですが、文化だけでなく観光の視点も入っているのと、それから先ほど申し上げたように区の魅力発信という部分もあります。Ａ席でも３,５００円ということで、その売上げも事業実施の経費に繰り込むということで、これを合わせて事業を実施するという考え方です。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"誰でも亡くなるということで税金を投入するべきということで質問をしていた流れになってしまうのですが、この方たちだけへの税金を使うわけですよね。でも、一般の区民の方に関してはという思いも出てきてしまうので、その辺についてお伺いします。","respondent":"鈴木文化観光課長、小川オリンピック・パラリンピック準備課長","answer":"区が区民の多くの方に文化を振興するという事業に協力をいただくという考え方で、見る方が区の税金で見るというような考え方はとっておりません。こちらにつきましては課長のほうから説明があったように組織委員会のほうでやっている参画プログラムという中での事業の一環ですが。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問","question":"ケーブルテレビでの放送というのはあるのでしょうか。なので、ケーブルテレビでの放送はどうなのかなと思って、そこら辺の説明を求めました。","respondent":"鈴木文化観光課長","answer":"ご覧いただく方もチケットを買っていただいて実施に協力いただくという形になりますので、今回はケーブルテレビでの放送は予定はしておりません。","id":"exchange-016"}]},{"id":"topic-03","title":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、区民委員会にかかわる項目","agenda":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、区民委員会にかかわる項目","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"自民党からの質問で、文化観光で歴史館が出たと思うのですけれども、学芸員を具体的に人員配置みたいなご答弁が出ていたと思うのですが、ストレートにこれから品川歴史館の学芸員はどうなっていくのか、具体的に伺いたいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"藤原委員","kind":"質問・要望","question":"ちょっと生活安全担当課長にお伺いしたいのですけれども、２週間前ぐらいは、犯人検挙という形でよかったのですが。やはり私たちの仕事というのは区民の安心・安全というのも大切な仕事の一つですから、その辺についてお伺いできればと思います。","respondent":"菅生活安全担当課長","answer":"これにつきまして区の対応としましては、しなメール等で区民の方々に注意喚起ということでお知らせをしております。区としても、警察あるいは町会のパトロール等と連携をしながら、新たに犯罪が発生しないようにまた今後防犯対策を進めてまいりたいと考えています。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/824061?Template=document&Id=2784#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":19591,"voices":51}},{"id":"h29-20170710-7","meetingId":"h29-cm07","date":"2017年7月10日","dateIso":"2017-07-10","committee":"厚生委員会","time":"午前１０時００分～午前１１時４３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件整理しています。","topics":[{"id":"topic-01","title":"はじめに、予定表の１、議案審査(1)第４７号議案、品川区社会福祉基金条例の一部を改正する条例","agenda":"はじめに、予定表の１、議案審査(1)第４７号議案、品川区社会福祉基金条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"高齢者福祉の進展のためにということで、こういう形で寄贈されたということは、本当に大変ありがたいことだというふうに思います。その処分というふうなところ、具体的にどのようなときに活用されることがあるのかということだけ、１点の説明を求めました。","respondent":"大串福祉計画課長","answer":"いろいろなケースが考えられるかと思いますけれども、やはり高齢者用の社会福祉基金で１４億４,０００万円、基金に積んでいたものがあります。今後ともさまざまな形で検討を加えながら、一番ご遺族の、そうした中で検討を重ねていきたいというふうに思っているところです。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"確認","question":"今の、基金型にするか使用型にするかというのは、受けるときに確認をするということで対応するのですか。そこだけ確認をさせてください。","respondent":"大串福祉計画課長","answer":"今回、１,０００万円いただいたものにつきましては、やはり何らかで１つ使ってほしいというところが大きかった。条例化については対応させていただき、こういったものを図っていきたいと、このように考えているところです。","id":"exchange-002"},{"speaker":"若林委員","kind":"確認","question":"中身そのものとは違うかもしれませんけれども、少し確認をさせてください。この１,０００万円というお金はどのような扱いになっていたのかというのが１つと、なかったのかという、そういうところの説明を求めました。","respondent":"大串福祉計画課長","answer":"したがいまして、１,０００万円入って運用が始まるのが、その補正予算の議決後という形になるものです。その辺は我々のほうとしましても、その辺は慎重にさせていただきながら、寄附の受領については行っていければというふうに思っているところです。","id":"exchange-003"}]},{"id":"topic-02","title":"第４１号議案、平成２９年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第４１号議案、平成２９年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"浅野委員","kind":"質問・要望","question":"今回の補正予算について少し質問させていただきたいのですが、合理化が図られるということと、あと紙で送ることのリスクと言うのか尋ねました。","respondent":"三ッ橋国保医療年金課長","answer":"２３区で申し上げますと、実際に実施している区は５区ございまして、千代田区となっております。そのほかの部分につきましては、これから検討中や、実施していく予定という状況になっております。","id":"exchange-004"},{"speaker":"浅野委員","kind":"質問・要望","question":"生活保護費について伺います。小学校４年生から中学校２年生までの何％の方が受けられているのかということを教えていただきたいのと、これを見込んでいるのかの説明を求めました。","respondent":"矢木生活福祉課長","answer":"中学校３年生の人数といたしましては２２人を対象としておりまして、７割、８割程度の方が申し込みをされるのではないかとこちらでは期待しています。高校４年生は定時制、これが合わせまして３２人で、それぞれ７割前後の方のお申し込みを想定しています。","id":"exchange-005"},{"speaker":"浅野委員","kind":"質問・要望","question":"続きまして、ＡＥＤの設置補助ですけれども、２７浴場ということで伺いました。この点に関しまして、今後の浴場の動向か尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"うまくコミュニケーションをとって、利用できる人に対しては実施できるようにお願いしたいということを要望します。私どもの要望の中に入れさせていただいた部分で、年度内であれば逆にこの時期の補正でなくても、お答えほしいと求めました。","respondent":"川島健康課長","answer":"ＡＥＤの設置、なるべく早く設置できるように、私どもとしても働きかけていきたいと考えております。それから、ＡＥＤを設置したもののどう使うかわからないということでは困りますので、これは浴場組合のほうから。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問","question":"補助金ですから、区が買うのではなくて、先方が買うということで、この金額で個別に買っていくのですか。数が多ければ金額的にもいいのかと思ったのですが、それはもう全て個々の浴場が自分たちで買う、契約は自分たちでやるということになるのか尋ねました。","respondent":"川島健康課長","answer":"今回の助成金は浴場組合に対してのものですので、浴場組合でまとめて購入して、浴場組合のほうに私どものほうで助成金を支出するという形になっております。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"１５届出書が対象で、その対象外というのは今後電子媒体となっていくという見通しがあるのかということが１点、職員の負担となることがあるのかということについてもの説明を求めました。","respondent":"三ッ橋国保医療年金課長","answer":"例えば資格関係の訂正・追加ですとか、細かい部分がございまして、そのような部分は電子媒体化にすぐ対応できないとなっております。こちらはシステム上の運用ができればボタン１つでＤＶＤ化できるようになりますので、それほど職員の負担はないと考えられます。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"次に、生活保護の法外援護についてお聞かせほしいと求めました。１５万円と、受験料の８万円も含めて、都の基準ということで決められている額なのかということについても教えてほしいと求めました。","respondent":"矢木生活福祉課長","answer":"大学受験料の対象者数ということで、先ほど申し上げた高校３年生、高校４年生、３２名が受験料の対象者数です。次に２点目、塾代の上限額が都の基準かという質問ですが、ご指摘のとおりです。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それからあと、生活保護世帯で、またそれを支援するにあたり課題になっていることがどういうことなのかについてもお聞かせほしいと求めました。","respondent":"矢木生活福祉課長","answer":"こちらは平成２８年度の実績です。こういった方にどのような支援があるかですが、要するに、ご家族の生活費のために充てないといった処理をさせていただいて支援を行ってあります。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区としてもどんどん意見を言っていっていただきたいと思っているのですが、その中で、合計も合わせてわかったら教えてほしいと求めました。今年度は７名ということだったのですが、そういう方がどれくらいいるのかということも、わかったら教えてほしいと求めました。","respondent":"矢木生活福祉課長","answer":"厚生労働省社会・援護局長通知「生活保護法による保護の実施要領について」の第１－２－（７）に規定されていて、同一世帯に居住を認めます。全国一律での制度を考えた場合、大学支援までの制度というのは、国等の動向を見たいというふうに考えてあります。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"さらにそういう支援の充実というところで、区のほうからも声を上げていただけたらというふうに要望させてほしいと求めました。どこにどう増やしていきたいとか、そういう計画があるのかどうかについて、その点だけの説明を求めました。","respondent":"川島健康課長","answer":"２４時間対応というのがなかなか難しいところではあるのですが、例えばコンビニへの設置の働きかけですとか、今までもしてきたのですけれども。区として、民間企業のほうに設置を進めていくという話になると、そういった形の施策を検討していきたいと考えています。","id":"exchange-013"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"１点だけ。先ほど、それともなかなか１０万円では足りなくて利用ができないということなのか、実態と合わせてみてどういう２名なのかを少し伺いたいと思います。","respondent":"矢木生活福祉課長","answer":"これは各世帯によってまちまちでございまして、ただ私どものほうで子ども家庭支援ですとか就学支援ということを平成２６年度から行っています。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問・要望","question":"大学進学率がなぜ品川区は全国平均に比べて約９ポイント高いのかというのを、何かわかっていることがあればお聞きしたいと思います。浴場内、施設内、および地域の安全・安心につなげてくださいというようなことが何かあれば教えてほしいと求めました。","respondent":"矢木生活福祉課長、川島健康課長","answer":"これにつきましては地道な学習支援ですとか、品川の立地条件等々があるものと、複合的な要因かと考えています。それから町の方が緊急で必要な場合は貸し出しするということも条件のようにさせていただきたいと考えています。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その後この基本方針については見直しがされたのかということを１点お聞かせいただきたいのと、その点の取り組みはどうなっているのかということ、ここの実績というのがどれぐらいになっているのかということについてもお聞かせほしいと求めました。","respondent":"川島健康課長","answer":"ただいまご質問にございました品川区受動喫煙防止対策基本方針、今後当然見直される、見直していくというふうに考えてあります。区民の健康状態に関するアンケート調査というのを実施する予定ですので、その中で、恐らくかなり実際の割合に近いものが出てくると考えています。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はその点でも、区としてできることがあるのではないかと思っているのですけれども、いかがでしょうか。１万５,０００人もの方が４項目に限っただけでも亡くなっているということを直視した対策が本当に求められていると思うのですね。","respondent":"川島健康課長","answer":"国保医療年金課で区民を対象としました卒煙セミナーというのを昨年１１月と１２月に実施しておりますので、今お話のございましたようなところというのも、いろいろな情報を収集しながら対策を進めていくために検討していきたいと考えています。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"糖尿病、もっと区としてできることがあるのではないかと思っているのですけれども、その点が１点。それからもう１つ、その辺も教えていただきたいのですけれども、その点はいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"屋外以上に害になりますし、屋内１００％禁煙化という厚生労働省の案から始まっていくということは本当に大事なことではないかと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"意見","question":"４件とも受動喫煙の防止の案件だと思うのですが、内容が違うという中で、去年の議事録を読ませてもらいましたが、現状で去年と変わらない、同じような質疑を繰り返している部分だと思いますので、国の方針、都の方針も出てくるのを待つという状況を含めてとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"提案がされなかったという、ほかの３件に対しては、そういう態度でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"大倉委員","kind":"意見","question":"陳情に関してですが、内容としては受動喫煙を防止していこうということで方向性は一緒かと。都や国の動向を注視していかないとなかなか対応としても難しいという話でしたので、会派としては継続ということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/999880?Template=document&Id=3480#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":26034,"voices":85}}]);
